window.QUIZ_ZK_DATA=window.QUIZ_ZK_DATA||{};
window.QUIZ_ZK_DATA["ai13011"]=[{"id":"ai13011-pl-P5154630","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"“大数据”一词最早出现在哪个国家的学术与产业讨论中？","opts":["A. 英国","B. 日本","C. 美国","D. 德国"],"ans":2,"explain":"根据教材内容，“大数据”一词最早出现在20世纪90年代的美国，后来逐渐获得业界广泛关注。因此正确选项为C。"},{"id":"ai13011-pl-P5154631","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在早期定义中，大数据最初是指（ ）。","opts":["A. 需要处理的信息量超过一般计算机处理数据时所能使用的内存量","B. 所有结构化数据的集合","C. 仅指社交媒体产生的文本数据","D. 特指金融领域的交易数据"],"ans":0,"explain":"在最开始的时候，大数据并没有一个确切的概念，而是指需要处理的信息量很大，已经超过一般计算机在处理数据时所能使用的内存量，迫使工程师必须改进处理数据的工具。"},{"id":"ai13011-pl-P5154632","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"谷歌的Map Reduce和开源的Hadoop平台的出现，主要解决了大数据处理中的什么问题？","opts":["A. 数据可视化问题","B. 大量数据的获取、存储和处理能力问题","C. 数据安全性问题","D. 数据标准化问题"],"ans":1,"explain":"谷歌的Map Reduce和开源的Hadoop平台的出现使人们可以处理的数据量大大增加，从而提升了对大量数据的处理能力。"},{"id":"ai13011-pl-P5154633","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下关于大数据发展历程的描述，正确的是（ ）。","opts":["A. 2008年，大数据理念首先被美国政府用于气象预测领域","B. 2010年，随着Web2.0时代的到来，社交网络和智能移动终端的普及使数据量进一步激增","C. 2011年，联合国发布了首份大数据政务白皮书","D. 2015年，美国白宫发布了《大数据研究和发展倡议》，标志着大数据进入美国国家战略"],"ans":1,"explain":"A项错误：2008年大数据理念首先被雅虎、谷歌等大型互联网公司采用。B项正确：2010年Web2.0时代到来，社交网络发展和智能终端普及使数据激增。C项错误：联合国发布大数据政务白皮书是在2012年7月。D项错误：2015年国务院印发《促进大数据发展行动纲要》，使大数据进入我国国家发展战略。"},{"id":"ai13011-pl-P5154634","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"第一家上市的大数据公司Splunk是在哪一年于纳斯达克上市的？","opts":["A. 2008年","B. 2010年","C. 2012年","D. 2014年"],"ans":2,"explain":"2012年4月，第一家大数据公司Splunk在纳斯达克上市。"},{"id":"ai13011-pl-P5154635","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"2014年4月，世界经济论坛围绕“大数据的回报与风险”主题发布了名为（ ）的报告。","opts":["A. 《大数据计算：在商务、科学和社会领域创建革命性突破》","B. 《大数据：创新、竞争和生产力的下一个新领域》","C. 《全球信息技术》","D. 《大数据：抓住机遇、守护价值》"],"ans":2,"explain":"2014年4月，世界经济论坛围绕“大数据的回报与风险”主题发布了名为《全球信息技术》的报告。"},{"id":"ai13011-pl-P5154636","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"大数据具有体量巨大、处理速度快等显著特征。其中，数据格式繁多、包含结构化、半结构化与非结构化数据，指的是大数据的（ ）。","opts":["A. Volume（大量）","B. Variety（多样）","C. Velocity（高速）","D. Value（低价值密度）"],"ans":1,"explain":"大数据的“Variety（多样性）”强调的是数据来源和数据类型的多样化，包括传统的结构化数据以及文本、图像、音视频等半结构化与非结构化数据。故本题正确选项为B。"},{"id":"ai13011-pl-P5154637","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"大数据特征中，“真实性”指的是（ ）。","opts":["A. 数据体量巨大，已经超越EB级别","B. 数据来源可靠，根据真实可靠的数据才能制定确实可靠的决策","C. 数据种类繁多，包含网络日志、社交信息等","D. 数据处理速度要求高，用户要求即时得到分析结果"],"ans":1,"explain":"真实性(Veracity)是指可靠的数据来源能够保障数据的真实性，只有根据真实可靠的数据才能制定确实可靠的决策。"},{"id":"ai13011-pl-P5154638","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在大数据的特征中，面对非结构化数据（如图片、视频）无法用传统系统处理，这体现了大数据的（ ）。","opts":["A. 大容量(Volume)","B. 速度快(Velocity)","C. 非结构性(Nonstructural)","D. 时效性(Timeliness)"],"ans":2,"explain":"非结构性是指在获得数据之前无法提前预知其结构，目前绝大多数数据是非结构化数据（如图片、视频）或半结构化数据（如网页），传统的系统对这些数据无法完成处理。"},{"id":"ai13011-pl-P5154639","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"大数据特征中，关于“时效性(Timeliness)”的描述，正确的是（ ）。","opts":["A. 数据规模越大，分析处理时间越短","B. 用户要求即时得到数据分析结果，需要在处理速度与规模之间折中考虑","C. 时效性只与数据存储设备有关，与算法无关","D. 大数据不需要关注处理速度，只需要关注数据体量"],"ans":1,"explain":"数据规模越大，分析处理时间越长。在许多情况下，用户要求即时得到数据的分析结果。因此，需要在实践、处理速度与规模之间折中考虑，寻求新的方法。"},{"id":"ai13011-pl-P5154640","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"大数据特征中的“安全性(Security)”主要关注的是（ ）。","opts":["A. 数据存储设备的物理安全","B. 数据的隐私保护和有效管控风险","C. 数据传输过程中的加密技术","D. 数据中心的防火防盗措施"],"ans":1,"explain":"数据的隐私保护是大数据分析和处理的一个重要问题，一旦对个人数据的使用不当，尤其是涉及大批量的关联数据泄露，将会导致严重的后果。"},{"id":"ai13011-pl-P5154641","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"大数据的核心功能是（ ）。","opts":["A. 数据存储","B. 数据可视化","C. 预测","D. 数据清洗"],"ans":2,"explain":"大数据的核心功能是预测，通过将数学算法运用到海量的数据上来预测事情发生的可能性。"},{"id":"ai13011-pl-P5154642","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"关于大数据分析信息时的三个转变，下列说法错误的是（ ）。","opts":["A. 可以分析和某个特别现象相关的所有数据，不再依赖于随机采样","B. 研究数据量之多使人们不再热衷于追求精确度","C. 大数据侧重对因果关系的发掘而不再注重相关关系","D. 以上说法均正确"],"ans":2,"explain":"大数据的精髓在于分析信息时的三个转变：第一，可以分析更多的数据，不再依赖于随机采样；第二，不再热衷于追求精确度；第三，侧重对相关关系的发掘而不再注重因果关系。C项将“相关关系”和“因果关系”说反了。"},{"id":"ai13011-pl-P5154643","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"大数据的价值主要体现在（ ）。","opts":["A. 数据体量越大，价值越高","B. 量变导致质变，对大数据分析和利用可以带来经济利益并融入生活各领域的决策","C. 只有结构化数据才有价值","D. 大数据价值与数据质量无关"],"ans":1,"explain":"一方面，对大数据的分析和利用可以带来经济利益；另一方面，大数据已经融入现代生活的方方面面，从商业到医疗、政府、教育等各领域的决策都离不开大数据。量变导致质变正是大数据价值的体现。"},{"id":"ai13011-pl-P5154644","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"人工智能(AI)的概念最初是在哪一年哪个会议上提出的？","opts":["A. 1943年，普林斯顿大学","B. 1956年，达特茅斯学会","C. 1950年，图灵测试会议","D. 1965年，斯坦福大学"],"ans":1,"explain":"人工智能最初是在1956年的Dartmouth学会上提出的。"},{"id":"ai13011-pl-P5154645","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"从计算机应用系统的角度出发，人工智能是研究如何制造智能机器或智能系统来模拟人类智能活动的能力，以延伸人类智能的科学。这一定义强调了人工智能的（ ）。","opts":["A. 硬件属性","B. 模拟与延伸人类智能的本质","C. 商业价值","D. 数学基础"],"ans":1,"explain":"教材定义中明确指出，人工智能是“研究如何制造智能机器或智能系统来模拟人类智能活动的能力，以延伸人类智能的科学”，强调了模拟与延伸人类智能的本质。"},{"id":"ai13011-pl-P5154646","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"人工智能从仿生学的角度出发，通过算法模仿人类的神经元，强调复杂的智能活动是由大量简单的单元并行运行的结果。这一学派属于人工智能的（ ）。","opts":["A. 符号主义(Symbolicism)","B. 连接主义(Connectionism)","C. 行为主义(Actionism)","D. 逻辑主义(Logicism)"],"ans":1,"explain":"连接主义学派从仿生学角度出发，通过建立感知机和神经网络来模仿人类大脑的结构与机制，强调复杂的智能活动是由大量简单的单元并行运行的结果。"},{"id":"ai13011-pl-P5154647","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"符号主义学派认为思维的基本单元是（ ），认知的过程可以被建模为符号表示的运算。","opts":["A. 神经元","B. 符号","C. 行为","D. 概率"],"ans":1,"explain":"符号主义学派认为思维的基本单元就是符号，而认知的过程可以被建模为符号表示的运算。"},{"id":"ai13011-pl-P5154648","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"行为主义学派从生物对环境的适应角度出发，将生物的适应过程建模成基于（ ）的方法来模拟智能。","opts":["A. 符号推理","B. 神经网络","C. 感知行动","D. 逻辑演绎"],"ans":2,"explain":"行为主义学派从生物对环境的适应角度出发，将生物的适应过程建模成基于“感知行动”的方法来模拟智能。"},{"id":"ai13011-pl-P5154649","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"人工智能发展的第一次寒冬发生在（ ）。","opts":["A. 1956年—1960年","B. 1974年—1980年","C. 1987年—1993年","D. 2000年—2005年"],"ans":1,"explain":"AI在20世纪70年代遇到了瓶颈，第一次寒冬发生在1974年—1980年。"},{"id":"ai13011-pl-P5154650","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"1986年，经典的反向传播算法(BP)是由（ ）等提出的。","opts":["A. Hopfield","B. Rumelhart","C. Brooks","D. Turing"],"ans":1,"explain":"1986年，经典的反向传播算法(BP)被Rumelhart等提出。"},{"id":"ai13011-pl-P5154651","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在人工智能的发展历史中，“专家系统”在（ ）时期得到了广泛应用并推动了第二次发展高潮。","opts":["A. 1955年—1974年","B. 1974年—1980年","C. 1980年—1987年","D. 1993年至今"],"ans":2,"explain":"在20世纪80年代初，随着“专家系统”类AI程序被产业界、学术界证明其强大的智能模拟能力，人工智能研究迎来了第二轮发展高潮（1980年—1987年）。"},{"id":"ai13011-pl-P5154652","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下哪个领域不属于人工智能的主要应用范围？","opts":["A. 自然语言处理","B. 机器翻译","C. 数据库索引优化","D. 计算机视觉"],"ans":2,"explain":"教材列举的人工智能应用领域包括自然语言处理、机器翻译、计算机视觉、推荐引擎、专家系统、机电控制、虚拟现实等。数据库索引优化属于传统数据库技术，不属于AI主要应用领域。"},{"id":"ai13011-pl-P5154653","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"推荐引擎能主动发现用户的当前需求甚至潜在需求，并将这些信息主动推送给用户。以下哪个是推荐引擎最典型的应用例子？","opts":["A. 搜索引擎结果排序","B. 网上购物平台根据浏览记录推送相关产品","C. 邮件自动分类","D. 文档自动摘要"],"ans":1,"explain":"最典型的推荐引擎应用例子就是网上购物，如淘宝、京东等购物平台能根据之前的浏览记录或者搜索记录推送相关的产品。"},{"id":"ai13011-pl-P5154654","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"专家系统是一种具有特定领域内大量知识与经验的程序系统。以下关于专家系统的描述，正确的是（ ）。","opts":["A. 专家系统可以替代人类专家解决所有领域的问题","B. 专家系统是目前人工智能中成果最不丰富的研究领域之一","C. 专家系统能够解决人类专家所解决的问题，并为人类专家的推理提供辅助","D. 专家系统不需要专业知识，只需要通用推理能力"],"ans":2,"explain":"专家系统是目前人工智能中成果最丰富的研究领域之一，给计算机程序学习并使其灵活运用专业知识，其就能解决人类专家所解决的问题，而且可以为人类专家的推理提供辅助和错误判断。"},{"id":"ai13011-pl-P5154655","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"大数据和人工智能的关系是（ ）。","opts":["A. 两者是相互独立的领域，没有关联","B. 大数据为人工智能提供海量数据支撑，人工智能为大数据提供技术支持","C. 人工智能将取代大数据的所有功能","D. 大数据是人工智能发展的阻碍因素"],"ans":1,"explain":"大数据和人工智能实际上是相辅相成、互相促进发展的。一方面，人工智能的决策和判断建立在大量数据基础上；另一方面，人工智能为大数据提供了技术支持。"},{"id":"ai13011-pl-P5154656","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"人工智能技术立足于神经网络并发展出多层神经网络结构，从而可以通过（ ）对多网络模型进行训练。","opts":["A. 线性建模","B. 深度机器学习","C. 简单的统计分析","D. 手工规则编写"],"ans":1,"explain":"人工智能技术立足于神经网络，并在此单层或数层神经网络的基础上发展出多层神经网络结构，从而可以通过深度机器学习对多网络模型进行训练。"},{"id":"ai13011-pl-P5154657","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"人工智能算法之所以在以前被提出却得不到快速发展，主要原因是（ ）。","opts":["A. 算法理论不完善","B. 有限的计算机运算能力无法应对庞大的运算量","C. 数据量太小","D. 没有应用场景"],"ans":1,"explain":"这样的算法之所以在以前被提出却得不到快速的发展，是因为有限的计算机运算能力无法应对如此庞大的运算量。现在计算机算力提高，可以进行高速并行运算。"},{"id":"ai13011-pl-P5154658","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在机器翻译中，现有自然语言理解(NLU)系统面临的主要难题是（ ）。","opts":["A. 词汇量不足","B. 无法结合具体语境消除歧义，学习深度不够","C. 翻译速度太慢","D. 只支持英文翻译"],"ans":1,"explain":"机器翻译容易遇到歧义性问题。要想消除歧义必须结合具体语境，但现有翻译方式通常将句子甚至词组作为理解单元，忽视具体语境。且现有NLU系统学习深度不够，无法随时间增长提高解读能力。"},{"id":"ai13011-pl-P5154659","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"自动定理证明中，1965年鲁宾孙提出的（ ）对该领域做出了重大贡献，但该方法与人类的自然演绎推理方法完全不同。","opts":["A. 归结原理","B. 贝叶斯定理","C. 最大熵原理","D. 最小二乘法"],"ans":0,"explain":"1965年鲁宾孙提出的归结原理对该领域做出了重大贡献。归结原理采用演绎方法，但与人类的自然演绎推理方法完全不同，将逻辑公式转化为子句集合的同时丧失了其固有的逻辑蕴含语意。"},{"id":"ai13011-pl-P5154660","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在模式识别领域，当前技术与人认识外界感官机制的主要差距在于（ ）。","opts":["A. 计算机处理速度太慢","B. 理论方法与人的形象思维能力存在较大差距","C. 数据量不够大","D. 算法过于复杂"],"ans":1,"explain":"模式识别的理论方法和人认识外界的感官机制有很大的差别。人认识事物的方法、所拥有的形象思维能力，是世界上任何先进的计算机识别系统无法比拟的。"},{"id":"ai13011-pl-P5154661","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"关于大数据与人工智能面临的挑战，以下说法正确的是（ ）。","opts":["A. 大数据不存在隐私安全问题","B. 人工智能不会出现偏见或歧视问题","C. 机器学习可能摄入性别歧视与种族歧视等不良内容，且可能被人为利用","D. 人工智能系统完全不会做出危害人类的事情"],"ans":2,"explain":"机器学习系统的学习有了一定的自主性，能自发地学习一些知识，但不可避免地摄入了一些不好的东西，如性别歧视与种族歧视。此外，人工智能可能被人为利用。"},{"id":"ai13011-pl-P5154662","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下哪个领域被教材列为大数据与人工智能未来有望突破的方向？","opts":["A. 数据存储硬件开发","B. 自动推理中的知识系统动态演化及可行性推理研究","C. 传统关系型数据库优化","D. 手工数据录入自动化"],"ans":1,"explain":"自动推理是人工智能经典内容之一，其基本理论是人工智能其他分支的共同基础，而知识系统的动态演化及可行性推理的研究又是自动推理的热点之一，是有望突破的方向。"},{"id":"ai13011-pl-P5154663","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"关于“暗数据”的描述，正确的是（ ）。","opts":["A. 暗数据是指所有无法访问的数据","B. 暗数据是指商业上无法被直接变现获利的数据，随着AI发展逐渐被证明存在价值","C. 暗数据是指被加密保护的数据","D. 暗数据没有任何使用价值"],"ans":1,"explain":"暗数据是指商业上一些无法被直接变现获利的数据。随着人工智能和大数据的不断发展，这些暗数据被逐渐证明了它们的存在价值。"},{"id":"ai13011-pl-P5154664","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"人工智能和云计算的结合能够带来的好处是（ ）。","opts":["A. 完全消除数据安全问题","B. 在降低成本并保持数据有序的情况下满足和管理不断增长的需求","C. 使所有企业都可以免费使用AI服务","D. 完全替代所有人工决策"],"ans":1,"explain":"云计算结合人工智能，能在降低成本并且保持数据有序的情况下，满足和管理不断增长的需求。"},{"id":"ai13011-pl-P5154665","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在各种常见的数据类型中，占据存储空间大且在网络传输中消耗大量带宽资源，同时由于数据量巨大且需要逐帧处理，其内容检测与识别技术难度最高的数据格式是（ ）。","opts":["A. 文本数据","B. 音频数据","C. 图片数据","D. 视频数据"],"ans":3,"explain":"视频数据占据存储空间大、在网络传输中占据大量带宽资源；由于视频由许多帧图像构成，需要逐帧进行图像处理，工作量巨大且面临运动物体识别的挑战，处理技术难度最高。"},{"id":"ai13011-pl-P5154666","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下关于文本数据的描述，正确的是（ ）。","opts":["A. 文本数据是最不常见的数据类型","B. 计算机处理得最完善和最成熟的数据类型是文本数据","C. 文本数据无法进行计算机处理","D. 文本数据只能用于社交软件"],"ans":1,"explain":"文本数据是最普通也是最常见的数据类型，现在计算机处理得最完善和最成熟的就是文本数据。"},{"id":"ai13011-pl-P5154667","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下哪种数据格式在处理时需要识别运动的物体，给处理技术带来了更为严峻的挑战？","opts":["A. 文本数据","B. 音频数据","C. 图片数据","D. 视频数据"],"ans":3,"explain":"对视频处理有时需要识别运动的物体，这种需求给视频的处理技术带来了更为严峻的挑战。"},{"id":"ai13011-pl-P5154668","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在交通智能化分析中，研究人员发现可以通过分析城市供水系统数据中的晨洗高峰时间，加上时间偏移量来预测交通早高峰时间。这体现的数据来源是（ ）。","opts":["A. 使用者自身产生的文本或音视频数据","B. 机器自身配备监控装置的测量报告","C. 存在较强关联性的其他领域的数据","D. 计算机产生的关于使用者行动的分析数据"],"ans":2,"explain":"交通状况与其他领域的数据（如供水系统数据、电网关灯数据等）存在较强的关联性，通过发掘跨领域数据流之间的相关性来预测交通状况，属于“存在较强关联性的其他领域的数据”这一来源。"},{"id":"ai13011-pl-P5154669","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下哪个不属于数据的主要来源？","opts":["A. 使用者自身产生的数据/信息","B. 机器自身配备装置的测量报告","C. 计算机产生的数据","D. 人工凭空编造的数据"],"ans":3,"explain":"教材将数据主要划分为四个来源：使用者自身产生的数据、机器自身配备装置的测量报告、计算机产生的数据、存在较强关联性的其他领域的数据。人工凭空编造的数据不属于数据来源。"},{"id":"ai13011-pl-P5154670","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"大数据应用于医疗方面，主要作用不包括以下哪项？","opts":["A. 监测病人生理状况，帮助医生进行治疗","B. 在几分钟内解码整个DNA，找到新的治疗方法","C. 帮助人们更好地理解和预测疾病模式","D. 完全取代医生的诊断工作"],"ans":3,"explain":"大数据在医疗方面可以通过收集数据加以分析，对疾病起到预防和治疗作用。大数据分析可以帮助医生诊断，但不能完全取代医生的诊断工作。"},{"id":"ai13011-pl-P5154671","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"大数据在金融行业的主要应用是（ ）。","opts":["A. 生产制造","B. 地理信息系统","C. 金融交易，利用大数据算法迅速决定是否将商品卖出","D. 医疗诊断"],"ans":2,"explain":"大数据在金融行业的主要应用是金融交易，很多股权交易是利用大数据算法进行的，这些算法可以迅速决定是否将商品卖出。"},{"id":"ai13011-pl-P5154672","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"将大数据技术合理应用于地理信息系统的主要好处是（ ）。","opts":["A. 完全消除地理信息误差","B. 不仅能及时处理地理信息，还能提高处理结果的准确度","C. 使地理信息系统不需要存储数据","D. 使地理信息系统完全自动化"],"ans":1,"explain":"将大数据技术合理应用于地理信息系统不仅能及时处理地理信息，还能提高处理结果的准确度。"},{"id":"ai13011-pl-P5154673","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据工程一般流程的正确顺序是（ ）。","opts":["A. 数据获取→数据存储→数据清洗→数据建模→数据处理→数据分析→数据可视化","B. 数据清洗→数据获取→数据存储→数据建模→数据分析→数据处理→数据可视化","C. 数据存储→数据获取→数据清洗→数据建模→数据分析→数据处理→数据可视化","D. 数据获取→数据清洗→数据存储→数据建模→数据处理→数据分析→数据可视化"],"ans":0,"explain":"数据工程一般分为：数据获取、数据存储、数据清洗、数据建模、数据处理、数据分析、数据可视化等若干个流程，顺序为A选项所示。"},{"id":"ai13011-pl-P5154674","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据清洗在数据工程流程中的核心目的是（ ）。","opts":["A. 将数据从外部源导入系统","B. 把非格式化或“污染”的数据规范化为标准格式的数据","C. 对数据进行统计分析","D. 将数据以图表形式展示"],"ans":1,"explain":"数据清洗是指把非格式化或“污染”的数据经过特定的处理，规范化或格式化为标准格式的数据，以供用户分析和决策使用。"},{"id":"ai13011-pl-P5154675","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据工程的最终目的是（ ）。","opts":["A. 采集更多的数据","B. 从海量杂乱无章的数据中抽取并推导出对人们有价值、有意义的数据","C. 建设更大的数据中心","D. 购买更多的存储设备"],"ans":1,"explain":"数据处理的目的在于从海量的杂乱无章的数据中抽取并推导出某些特定的对人们生产有价值、有意义的数据。"},{"id":"ai13011-pl-P5154676","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"根据麦肯锡全球研究所的分析，利用大数据使美国零售业净收益可增长（ ）。","opts":["A. 3%","B. 6%","C. 10%","D. 15%"],"ans":1,"explain":"美国零售业净收益可增长6%，年劳动生产率提高0.5%～1%。"},{"id":"ai13011-pl-P5154677","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下哪个不属于企业相关大数据的4个来源？","opts":["A. 机器配备的连续测量和报告运行情况的装置","B. 计算机产生的关于使用者行动和行为的信息","C. 使用者自身产生的文本信息","D. 政府公开的气象数据"],"ans":3,"explain":"与企业经营相关的大数据可以划分为4个来源：机器传感数据、计算机产生的数据、使用者自身产生的数据、音频视频和符号数据。政府公开气象数据不属于企业大数据来源。"},{"id":"ai13011-pl-P5154678","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"DPI采集方法采集的数据大部分是“裸格式”的数据，即数据未经任何处理。DPI采集软件主要部署在（ ）上。","opts":["A. 应用服务器","B. 骨干路由器","C. 数据库服务器","D. 客户端计算机"],"ans":1,"explain":"DPI数据采集软件主要部署在骨干路由器上，用于采集底层的网络大数据。"},{"id":"ai13011-pl-P5154679","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在系统日志采集方法中，以下哪个不属于日志采集软件？","opts":["A. Chukwa","B. Flume","C. Scribe","D. MySQL"],"ans":3,"explain":"教材列举的日志采集软件包括Hadoop的Chukwa、Cloudera的Flume、Facebook的Scribe等。MySQL是关系型数据库，不属于日志采集软件。"},{"id":"ai13011-pl-P5154680","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在网络数据采集方法中，数据采集和处理的第一步是（ ）。","opts":["A. 爬虫从Internet抓取网页内容","B. 将需要抓取数据网站的URL信息写入URL队列","C. 爬虫从网页中抽取数据写入数据库","D. 数据处理模块读取数据进行处理"],"ans":1,"explain":"根据教材图22所示，Web数据采集和处理的第一步是将需要抓取数据网站的URL信息写入URL队列。"},{"id":"ai13011-pl-P5154681","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下哪个是Apache旗下开源的数据采集系统，使用JRuby构建，依赖Java运行环境？","opts":["A. Fluentd","B. Logstash","C. Flume","D. Splunk Forwarder"],"ans":2,"explain":"Flume是Apache旗下的一款开源、高可靠、高扩展的数据采集系统，Flume使用JRuby来构建，所以依赖Java运行环境。"},{"id":"ai13011-pl-P5154682","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"Splunk是一个分布式的机器数据平台，在其架构的三个核心角色中，负责数据的收集、清洗、变形，并将处理后的数据发送给Indexer的角色是（ ）。","opts":["A. Search Head","B. Forwarder","C. Master Node","D. Worker Node"],"ans":1,"explain":"Splunk架构中主要包含三个角色：Search Head负责数据的搜索和处理；Indexer负责数据的存储和索引；Forwarder负责数据的收集、清洗、变形，并发送给Indexer。"},{"id":"ai13011-pl-P5154683","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据存储方式不包括以下哪种？","opts":["A. 文件","B. 数据库","C. 网络","D. 纸质档案"],"ans":3,"explain":"数据存储方式有三种：文件、数据库、网络。纸质档案不属于电子数据存储方式。"},{"id":"ai13011-pl-P5154684","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"企业的数据处理大致分为两类，其中操作型处理也称为（ ）。","opts":["A. 联机事务处理(OLTP)","B. 联机分析处理(OLAP)","C. 数据挖掘","D. 数据可视化"],"ans":0,"explain":"企业的数据处理大致分为两类：一类是操作型处理，也称为联机事务处理(OLTP)；另一类是分析型处理。"},{"id":"ai13011-pl-P5154685","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"存储区域网络(SAN)是一种采用高速网络连接专业主机服务器的存储方式，其主要采用的高速I/O连接方式不包括（ ）。","opts":["A. SCSI","B. ESCON","C. FibreChannels","D. USB"],"ans":3,"explain":"SAN使用高速I/O连接方式，如SCSI、ESCON及FibreChannels。USB属于低速通用接口，不属于SAN的高速连接方式。"},{"id":"ai13011-pl-P5154686","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据仓库和操作型数据库的根本区别是（ ）。","opts":["A. 数据仓库存储量更大","B. 数据仓库面向主题，操作型数据库支撑业务","C. 数据仓库速度快","D. 数据仓库不需要数据清洗"],"ans":1,"explain":"面向主题特性是数据仓库和操作型数据库的根本区别。操作型数据库是为了支撑各种业务而建立，而分析型数据库是为了对从各种繁杂业务中抽象出来的主题进行分析而建立。"},{"id":"ai13011-pl-P5154687","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据仓库的“时变性”特点是指（ ）。","opts":["A. 数据会随时间变化而删除","B. 数据仓库包含来自其时间范围内不同时间段的数据快照","C. 数据仓库的数据每小时更新一次","D. 数据仓库只保存最近一个月的数据"],"ans":1,"explain":"时变性是指数据仓库包含来自其时间范围内不同时间段的数据快照。有了这些数据快照，用户便可将其汇总，生成各历史阶段的数据分析报告。"},{"id":"ai13011-pl-P5154688","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"现实世界中的数据大体上是不完整、不一致、含有噪声的。以下哪个不属于数据预处理的方法？","opts":["A. 数据清理","B. 数据集成","C. 数据可视化","D. 数据变换"],"ans":2,"explain":"数据预处理主要包括数据清理、数据集成、数据变换、数据归约四种方法。数据可视化属于数据工程的最后环节，不属于数据预处理方法。"},{"id":"ai13011-pl-P5154689","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在处理数据集中的缺失值时，利用回归、贝叶斯推理工具或决策树归纳来确定缺失属性值的方法，属于（ ）。","opts":["A. 忽略元组","B. 使用全局常量填充","C. 使用最有可能的值填充","D. 使用属性的均值填充"],"ans":2,"explain":"利用回归、基于贝叶斯推理的工具或决策树归纳来预测并填补缺失值，利用了已有数据的大部分信息来推断缺失值，属于“使用最有可能的值填充”这一方法。"},{"id":"ai13011-pl-P5154690","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下哪种分箱方法使每个箱子具有相同的记录数？","opts":["A. 等宽分箱法","B. 等深分箱法","C. 用户自定义区间","D. 聚类分箱法"],"ans":1,"explain":"等深分箱法将数据集按记录行数分箱，每箱具有相同的记录数，每箱记录数称为箱子的深度。"},{"id":"ai13011-pl-P5154691","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据光滑技术中，通过考察数据的“近邻”（即周围的值）来确定最终值的预处理方法是（ ）。","opts":["A. 回归","B. 聚类","C. 分箱","D. 最小最大规范化"],"ans":2,"explain":"分箱是一种简单常用的预处理方法，通过考察数据的“近邻”（即周围的值）来确定最终值。"},{"id":"ai13011-pl-P5154692","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在数据集成过程中，检测不同属性间是否存在冗余时，对于标称数据通常使用（ ）。","opts":["A. 相关系数","B. 协方差","C. 卡方检验","D. 最小最大规范化"],"ans":2,"explain":"对于标称数据，使用卡方检验检测冗余；对于数值属性，使用相关系数和协方差。"},{"id":"ai13011-pl-P5154693","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在数据变换中，将属性数据按比例缩放，使之落入一个小的特定区间的过程称为（ ）。","opts":["A. 数据泛化","B. 规范化","C. 聚集","D. 光滑"],"ans":1,"explain":"规范化又称为归一化，特征缩放，是将属性数据按比例缩放，使之落入一个小的特定区间。"},{"id":"ai13011-pl-P5154694","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"小数定标规范化的公式为$v&#039; = v/10^j$，其中j是使（ ）的最小整数。","opts":["A. $max(|v|) &lt; 1$","B. $max(|v&#039;|) &lt; 1$","C. $max(|v|) &gt; 1$","D. $max(|v&#039;|) &gt; 1$"],"ans":1,"explain":"小数定标规范化$v&#039; = v/10^j$，j是使$max(|v&#039;|) &lt; 1$的最小整数。"},{"id":"ai13011-pl-P5154695","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下哪种数据归约方法属于参数方法？","opts":["A. 直方图","B. 聚类","C. 抽样","D. 回归"],"ans":3,"explain":"对于参数方法而言，使用模型估计数据，使之只需要存放模型参数，而不是实际数据。回归和对数线性模型就是例子。"},{"id":"ai13011-pl-P5154696","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在机器学习模型中，通过模型训练中的学习算法自动调整的参数称为（ ），不是通过学习算法得来但同样需要调优的参数称为（ ）。","opts":["A. 模型参数；超参数","B. 超参数；模型参数","C. 训练参数；测试参数","D. 输入参数；输出参数"],"ans":0,"explain":"模型参数是通过模型训练中的学习算法而进行调整的，而模型超参数不是通过学习算法得来的，但是同样需要进行调优。"},{"id":"ai13011-pl-P5154697","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在回归任务中，平方根误差(RMSE)的主要缺点是（ ）。","opts":["A. 计算过于复杂","B. 对异常点敏感","C. 不能反映预测误差的方向","D. 只能用于二分类问题"],"ans":1,"explain":"RMSE使用平均误差，而平均值对异常点较敏感，如果回归器对某个点的回归值很不理性，那么它的误差较大，会对RMSE的值有较大影响，即平均值是非鲁棒的。"},{"id":"ai13011-pl-P5154698","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"为改进RMSE对异常点敏感的缺点，可以采用（ ）来代替平均数以提高评价指标的鲁棒性。","opts":["A. 最大值","B. 最小值","C. 中位数","D. 方差"],"ans":2,"explain":"为了改进RMSE的缺点，提高评价指标的鲁棒性，使用误差的分位数来代替，如中位数来代替平均数。假设100个数，最大的数无论怎样改变，中位数也不会变，因此其对异常点具有鲁棒性。"},{"id":"ai13011-pl-P5154699","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据可视化领域的起源可以追溯到20世纪50年代的（ ）。","opts":["A. 信息可视化","B. 科学可视化","C. 计算机图形学的早期","D. 数据仓库技术"],"ans":2,"explain":"数据可视化领域的起源，可以追溯到20世纪50年代计算机图形学的早期。当时，人们利用计算机创建出了首批图形图表。"},{"id":"ai13011-pl-P5154700","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在各种数据可视化应用工具中，主要用于复杂网络分析、基于Java语言开发且使用OpenGL作为可视化引擎，适合对大规模网络与关系数据进行专业深度挖掘的工具是（ ）。","opts":["A. ECharts","B. OpenRefine","C. Gephi","D. Bonsaijs"],"ans":2,"explain":"Gephi是一款开源免费基于JVM的复杂网络分析软件，基于Java在Netbeans平台上开发，使用OpenGL作为可视化引擎，专用于复杂网络、社交网络及生物网络等大规模数据的深度可视化与探索。"},{"id":"ai13011-pl-P5154701","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"百度团队开源的数据可视化JS框架ECharts底层依赖于轻量级的Canvas类库（ ）。","opts":["A. ZRender","B. D3.js","C. Trifacta","D. Node"],"ans":0,"explain":"ECharts底层依赖轻量级的Canvas类库ZRender，提供直观、生动、可交互、可高度个性化定制的数据可视化图表。"},{"id":"ai13011-pl-P5154702","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"D3.js的核心特点是（ ）。","opts":["A. 提供大量开箱即用的图表模板","B. 严格遵循Web标准，允许将数据绑定到DOM上，以数据驱动的方式操作文档","C. 只能用于地理数据可视化","D. 不支持大型数据集"],"ans":1,"explain":"D3.js严格遵循Web标准，允许开发者将任意数据绑定在文档对象模型(DOM)上，然后应用数据驱动转换到文档中。"},{"id":"ai13011-pl-P5154872","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在大数据的4V特征中，数据规模大到无法通过目前普及的计算机系统在用户可容忍时间内获取、存储、处理，这主要体现的是（ ）。","opts":["A. Variety（多样）","B. Volume（大量）","C. Velocity（高速）","D. Veracity（真实性）"],"ans":1,"explain":"大数据主要是指海量乃至巨量数据，数据规模大到无法通过目前普及的计算机系统在用户可容忍时间内获取、存储和处理，这体现了大容量(Volume)特征。"},{"id":"ai13011-pl-P5154873","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"2008年年末，计算社区联盟发表的白皮书《大数据计算：在商务、科学和社会领域创建革命性突破》指出，大数据重要的是其（ ），而不再是数据本身。","opts":["A. 存储方式","B. 新用途和新见解","C. 处理速度","D. 数据来源"],"ans":1,"explain":"该白皮书打破人们的思维局限，指出大数据重要的是其新用途和新见解，而不再是数据本身。"},{"id":"ai13011-pl-P5154874","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"大数据特征中，可靠的数据来源能够保障数据的真实性，这体现了（ ）。","opts":["A. 大容量(Volume)","B. 多种类(Variety)","C. 真实性(Veracity)","D. 安全性(Security)"],"ans":2,"explain":"真实性(Veracity)是指可靠的数据来源能够保障数据的真实性，只有根据真实可靠的数据才能制定确实可靠的决策。"},{"id":"ai13011-pl-P5154875","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"大数据的精髓在于分析信息时的三个转变，其中第三个转变是（ ）。","opts":["A. 可以分析和某个特别现象相关的所有数据，不再依赖于随机采样","B. 研究数据量之多使人们不再热衷于追求精确度","C. 侧重对相关关系的发掘而不再注重因果关系","D. 数据量的增加会导致质量的下降"],"ans":2,"explain":"大数据的精髓在于分析信息时的三个转变：第一，不再依赖于随机采样；第二，不再热衷于追求精确度；第三，侧重对相关关系的发掘而不再注重因果关系。"},{"id":"ai13011-pl-P5154876","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"人工智能的概念最初是由被称为计算机之父和人工智能之父的（ ）提出的。","opts":["A. John McCarthy","B. Alan Turing","C. Marvin Minsky","D. John Hopfield"],"ans":1,"explain":"人工智能的概念最初是由被称为计算机之父和人工智能之父的Alan Turing提出的。"},{"id":"ai13011-pl-P5154877","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"连接主义学派在20世纪80年代重新成为学界讨论的热点，部分原因是Hopfield教授在（ ）年发表了两篇重要论文，传达了使用硬件模拟神经网络的思想。","opts":["A. 1960年和1964年","B. 1982年和1984年","C. 1986年和1988年","D. 1990年和1992年"],"ans":1,"explain":"1982年和1984年，Hopfield教授通过两篇重要论文传达了使用硬件模拟神经网络的思想，连接主义重新成为学界讨论的热点。"},{"id":"ai13011-pl-P5154878","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"人工智能第二次寒冬期间，出现的主要问题不包括（ ）。","opts":["A. AI硬件需求下跌","B. “专家系统”领域窄、更新维护成本高","C. 计算机算力得到极大的发展","D. 商业界对AI变得冷淡，资金短缺"],"ans":2,"explain":"第二次寒冬期间，AI硬件需求下跌，“专家系统”领域窄、更新维护成本高，商业界对AI变得冷淡，资金短缺。计算机算力仍然没有得到很好的发展，而非得到极大的发展。"},{"id":"ai13011-pl-P5154879","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在机电控制领域，人工神经网络具有自学习和自适应能力，可以实时模拟受控对象的变化。当受控对象的输出与模型的输出存在一定误差时，神经网络的（ ）使控制系统具有一定的鲁棒性。","opts":["A. 容错能力","B. 并行处理能力","C. 记忆能力","D. 泛化能力"],"ans":0,"explain":"当受控对象的输出与模型的输出存在一定误差时，神经网络所具有的容错能力使控制系统具有一定的鲁棒性。"},{"id":"ai13011-pl-P5154880","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"人工智能和大数据的关系中，以下说法正确的是（ ）。","opts":["A. 人工智能的决策和判断不需要大量数据支持","B. 数据量越大，人工智能的效果不一定越好","C. 人工智能为大数据提供了技术支持，在大数据领域使用人工智能进行数据分析将如虎添翼","D. 大数据和人工智能是完全独立发展的两个领域"],"ans":2,"explain":"大数据和人工智能相辅相成、互相促进发展。人工智能为大数据提供了技术支持，如果能在大数据领域使用人工智能进行数据分析，那么大数据将会如虎添翼。"},{"id":"ai13011-pl-P5154881","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"人工智能在气象预测、股票预测、医学检测等方面的应用表明，与人类相比，人工智能可以（ ）。","opts":["A. 完全取代人类专家","B. 更好更快地完成任务，而且不会感到疲劳","C. 在所有领域都超过人类","D. 不需要人类监督"],"ans":1,"explain":"与人类相比，人工智能可以更好更快地完成任务，而且不会感到疲劳。"},{"id":"ai13011-pl-P5154882","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在数据工程中，数据建模的最终目的是（ ）。","opts":["A. 存储更多的数据","B. 提升用户使用系统的效率","C. 增加数据的安全性","D. 减少数据采集的成本"],"ans":1,"explain":"数据建模的最终目的是提升用户使用系统的效率。"},{"id":"ai13011-pl-P5154883","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据预处理中，通过平滑、聚集、规范化等方法把原始数据转换成适合数据挖掘形式的过程属于（ ）。","opts":["A. 数据清理","B. 数据集成","C. 数据变换","D. 数据归约"],"ans":2,"explain":"数据变换是通过平滑、聚集、规范化、最小最大规范化等方法，把原始数据转换成适合数据挖掘的形式。"},{"id":"ai13011-pl-P5154884","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在数据清理中，使用属性的均值填充缺失值时，如果数据分布是倾斜的，则应该使用（ ）作为更好的选择。","opts":["A. 均值","B. 众数","C. 中位数","D. 最大值"],"ans":2,"explain":"正常数据分布可以使用均值，而倾斜数据分布应该使用中位数。"},{"id":"ai13011-pl-P5154885","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在数据变换的规范化方法中，$v&#039; = (v 属性A的均值)/属性A的标准差$属于（ ）。","opts":["A. 最小最大规范化","B. Zscore规范化","C. 小数定标规范化","D. 对数规范化"],"ans":1,"explain":"Zscore规范化（零均值规范化）的公式为$v&#039; = (v 属性A的均值)/属性A的标准差$。"},{"id":"ai13011-pl-P5154886","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在数据归约中，通过变换以得到原数据的归约或“压缩”表示，如果原数据能够从压缩后的数据重构而不损失信息，则称该数据归约为（ ）。","opts":["A. 有损的","B. 无损的","C. 参数的","D. 非参数的"],"ans":1,"explain":"如果原数据能够从压缩后的数据重构而不损失信息，则称该数据归约为无损的。"},{"id":"ai13011-pl-P5154887","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在回归评价指标中，MAPE是指（ ）。","opts":["A. 均方误差","B. 平均绝对误差","C. 相对误差的中位数","D. 最大误差"],"ans":2,"explain":"MAPE是一个相对误差的中位数，也可以使用别的分位数。"},{"id":"ai13011-pl-P5154888","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"OpenRefine工具中，发现一些拼写不一样但实际上应分为一组的文本的功能称为（ ）。","opts":["A. 数据清洗","B. 聚类编辑","C. 数据变换","D. 数据归约"],"ans":1,"explain":"Refine设有内置算法，可以发现一些拼写不一样但实际上应分为一组的文本，选择编辑单元格→聚类，编辑，然后选择要用的算法。"},{"id":"ai13011-pl-P5154889","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"Bonsaijs是一个轻量级的免费开源的JavaScript图形库，使用（ ）作为输出方式来生成图形和动画效果。","opts":["A. Canvas","B. SVG","C. WebGL","D. CSS"],"ans":1,"explain":"Bonsaijs使用SVG作为输出方式来生成图形和动画效果。"},{"id":"ai13011-pl-P5154930","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下关于“大数据”基本概念的描述，正确的有（ ）。","opts":["A. “大数据”一词最早出现在20世纪90年代的美国","B. 大数据最初是指需要处理的信息量超过一般计算机处理数据时所能使用的内存量","C. 谷歌的Map Reduce和开源的Hadoop平台的出现提升了人们对大量数据的处理能力","D. 大数据仅指结构化数据，不包括非结构化数据"],"ans":[0,1,2],"explain":"A项正确：“大数据”一词最早出现在20世纪90年代的美国。B项正确：大数据最初是指需要处理的信息量很大，已经超过一般计算机在处理数据时所能使用的内存量。C项正确：谷歌的Map Reduce和开源的Hadoop平台使人们可以处理的数据量大大增加。D项错误：大数据不仅包括结构化数据，还包括半结构化和非结构化数据。"},{"id":"ai13011-pl-P5154931","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"关于大数据发展历程中的重要事件，以下说法正确的有（ ）。","opts":["A. 2008年，大数据理念被雅虎、谷歌等大型互联网公司尝试采用","B. 2010年，随着Web2.0时代的到来，社交网络飞速发展使互联网数据进一步激增","C. 2012年，第一家大数据公司Splunk在纳斯达克上市","D. 2014年，国务院印发《促进大数据发展行动纲要》"],"ans":[0,1,2],"explain":"A项正确：2008年，电子商务快速发展，大数据理念被雅虎、谷歌等大型互联网公司尝试采用。B项正确：2010年，Web2.0时代到来，社交网络飞速发展使数据激增。C项正确：2012年4月，第一家大数据公司Splunk在纳斯达克上市。D项错误：国务院印发《促进大数据发展行动纲要》是在2015年，而非2014年。"},{"id":"ai13011-pl-P5154932","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"大数据的特征中，以下属于大数据4V特征的有（ ）。","opts":["A. Volume（大量）","B. Variety（多样）","C. Velocity（高速）","D. Veracity（真实性）"],"ans":[0,1,2,3],"explain":"教材明确指出大数据的4V特征包括：Volume（大容量）、Variety（多种类）、Velocity（速度快）、Veracity（真实性）。此外还包括非结构性、时效性、安全性等特征。"},{"id":"ai13011-pl-P5154933","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下关于大数据特征“多种类(Variety)”的描述，正确的有（ ）。","opts":["A. 数据可被归类为结构化数据、半结构化数据和非结构化数据","B. 现如今的数据多为非结构化数据","C. 非结构化数据包括网络日志、社交网络信息、地理位置信息等","D. 传统的关系数据属于非结构化数据"],"ans":[0,1,2],"explain":"A项正确：多样化的数据可被归类为结构化数据、半结构化数据和非结构化数据。B项正确：与以往结构化数据为主要数据的局面不同，现如今的数据多为非结构化数据。C项正确：非结构化数据包括网络日志、社交网络信息、地理位置信息等。D项错误：传统的关系数据属于结构化数据，而非非结构化数据。"},{"id":"ai13011-pl-P5154934","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下关于大数据基本认识的描述，正确的有（ ）。","opts":["A. 大数据的核心功能是预测","B. 预测系统的关键是它们建立在海量数据的基础之上","C. 在大数据时代可以分析和某个特别现象相关的所有数据，不再依赖于随机采样","D. 大数据侧重对因果关系的发掘而不再注重相关关系"],"ans":[0,1,2],"explain":"A项正确：大数据的核心功能是预测。B项正确：预测系统的关键是它们建立在海量数据的基础之上。C项正确：在大数据时代可以分析更多的数据，有时甚至可以处理和某个特别现象相关的所有数据，而不再依赖于随机采样。D项错误：大数据侧重对相关关系的发掘而不再注重因果关系。"},{"id":"ai13011-pl-P5154935","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下关于人工智能三大派别的描述，正确的有（ ）。","opts":["A. 符号主义起源于数学逻辑，希望通过符号来建模人类学习事物的过程","B. 连接主义从仿生学角度出发，通过算法模仿人类的神经元","C. 行为主义从生物对环境的适应角度出发，基于“感知-行动”的方法模拟智能","D. 连接主义学派认为思维的基本单元就是符号"],"ans":[0,1,2],"explain":"A项正确：符号主义起源于数学逻辑，希望通过符号来建模人类学习事物的过程。B项正确：连接主义从仿生学角度出发，通过算法模仿人类的神经元。C项正确：行为主义从生物对环境的适应角度出发，基于“感知-行动”的方法模拟智能。D项错误：符号主义学派认为思维的基本单元就是符号，而非连接主义。"},{"id":"ai13011-pl-P5154936","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下关于人工智能发展历史的描述，正确的有（ ）。","opts":["A. 人工智能的概念最初由Alan Turing提出","B. 1956年达特茅斯会议上人工智能被正式列为研究学科","C. 1986年Rumelhart等提出了经典的反向传播算法(BP)","D. 人工智能第一次寒冬发生在1987年—1993年"],"ans":[0,1,2],"explain":"A项正确：人工智能的概念最初由Alan Turing提出。B项正确：1956年达特茅斯会议上人工智能被正式列为研究学科。C项正确：1986年Rumelhart等提出了经典的反向传播算法(BP)。D项错误：第一次寒冬发生在1974年—1980年，第二次寒冬发生在1987年—1993年。"},{"id":"ai13011-pl-P5154937","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于人工智能应用领域的有（ ）。","opts":["A. 自然语言处理","B. 机器翻译","C. 计算机视觉","D. 推荐引擎"],"ans":[0,1,2,3],"explain":"教材列举的人工智能应用领域包括：自然语言处理、机器翻译、计算机视觉、推荐引擎、专家系统、机电控制、虚拟现实等。A、B、C、D均属于人工智能的应用领域。"},{"id":"ai13011-pl-P5154938","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下关于大数据与人工智能关系的描述，正确的有（ ）。","opts":["A. 大数据为人工智能提供了海量数据的支撑","B. 人工智能为大数据提供了技术支持","C. 大数据和人工智能是相辅相成、互相促进发展的","D. 人工智能的发展不需要数据的支持"],"ans":[0,1,2],"explain":"A项正确：随着大数据持续发展，人工智能有了海量数据的支撑，得到了快速发展。B项正确：人工智能为大数据提供了技术支持。C项正确：大数据和人工智能相辅相成、互相促进发展。D项错误：任何智能的发展都离不开数据的支持，人工智能的决策和判断建立在大量数据基础上。"},{"id":"ai13011-pl-P5154939","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于大数据与人工智能面临的难题的有（ ）。","opts":["A. 机器翻译的歧义性问题","B. 自动定理证明的演绎局限","C. 模式识别与人脑机制的差距","D. 大数据的隐私和安全风险"],"ans":[0,1,2,3],"explain":"大数据与人工智能面临的难题包括：机器翻译的歧义性问题、自动定理证明的演绎局限、模式识别与人脑机制的差距、大数据的隐私和安全风险、人工智能的是非判断和安全性问题等。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154940","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于大数据与人工智能未来前景方向的有（ ）。","opts":["A. 自动推理中的知识系统动态演化研究","B. 机器学习中的在线学习方法","C. 人工智能和云计算的结合","D. 暗数据的新纪元"],"ans":[0,1,2,3],"explain":"大数据与人工智能的未来前景包括：自动推理研究、机器学习在线学习方法、自然语言处理、人工智能与云计算结合、暗数据新纪元、医学进一步应用等。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154941","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下关于数据格式多样性的描述，正确的有（ ）。","opts":["A. 文本数据是最普通也是最常见的数据类型","B. 音频数据比较具有代表性的是mp3格式的数据","C. 图片数据主要用于记录静态信息","D. 视频数据占据存储空间大、在网络传输中占据大量带宽资源"],"ans":[0,1,2,3],"explain":"A项正确：文本数据是最普通也是最常见的数据类型。B项正确：音频数据比较具有代表性的是mp3格式的数据。C项正确：图片数据主要用于记录静态信息。D项正确：视频数据占据存储空间大、在网络传输中占据大量带宽资源。"},{"id":"ai13011-pl-P5154942","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于数据主要来源的有（ ）。","opts":["A. 使用者自身产生的数据/信息","B. 机器自身配备装置的测量报告","C. 计算机产生的数据","D. 存在较强关联性的其他领域的数据"],"ans":[0,1,2,3],"explain":"教材将数据主要划分为四个来源：使用者自身产生的数据/信息、机器自身配备装置的测量报告、计算机产生的数据、存在较强关联性的其他领域的数据。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154943","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"大数据在以下哪些领域有重要应用？（ ）","opts":["A. 医疗领域","B. 金融行业","C. 地理信息系统","D. 制造业"],"ans":[0,1,2,3],"explain":"大数据应用于医疗、金融行业、地理信息、消费、制造业等多个领域。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154944","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"数据工程的一般流程包括（ ）。","opts":["A. 数据获取","B. 数据清洗","C. 数据建模","D. 数据可视化"],"ans":[0,1,2,3],"explain":"数据工程一般分为：数据获取、数据存储、数据清洗、数据建模、数据处理、数据分析、数据可视化等若干个流程。A、B、C、D均属于数据工程的一般流程。"},{"id":"ai13011-pl-P5154945","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下关于数据工程各流程的描述，正确的有（ ）。","opts":["A. 数据获取是指将不同数据源的数据自动收集到一个装置中","B. 数据存储是指对采集到的数据进行持久化的保存","C. 数据清洗是指把非格式化或“污染”的数据规范化为标准格式的数据","D. 数据分析是指从海量的数据中利用数据挖掘的方法获取有用的信息"],"ans":[0,1,2,3],"explain":"A项正确：数据获取是指将不同数据源的数据自动收集到一个装置中。B项正确：数据存储是指对采集到的数据进行持久化的保存。C项正确：数据清洗是指把非格式化或“污染”的数据规范化为标准格式。D项正确：数据分析是指从海量数据中利用数据挖掘的方法获取有用的信息。"},{"id":"ai13011-pl-P5154946","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于数据采集方法的有（ ）。","opts":["A. DPI采集方法","B. 系统日志采集方法","C. 网络数据采集方法","D. 数据库采集"],"ans":[0,1,2,3],"explain":"教材列举的数据采集方法包括：DPI采集方法、系统日志采集方法、网络数据采集方法、数据库采集、其他数据采集方法。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154947","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于大数据采集平台的有（ ）。","opts":["A. Apache Flume","B. Fluentd","C. Logstash","D. Splunk Forwarder"],"ans":[0,1,2,3],"explain":"大数据采集平台包括：Apache Flume、Fluentd、Logstash、Splunk Forwarder等。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154948","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下关于数据存储方式的描述，正确的有（ ）。","opts":["A. 数据存储方式有文件、数据库、网络三种","B. DAS是直接连接于主机服务器的一种存储方式","C. NAS是一套网络存储设备，性价比高","D. SAN使用高速I/O连接方式"],"ans":[0,1,2,3],"explain":"A项正确：数据存储方式有三种：文件、数据库、网络。B项正确：DAS是直接连接于主机服务器的一种存储方式。C项正确：NAS是一套网络存储设备，特点是性价比高。D项正确：SAN使用高速I/O连接方式，如SCSI、ESCON及Fibre-Channels。"},{"id":"ai13011-pl-P5154949","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于数据仓库特点的有（ ）。","opts":["A. 面向主题","B. 集成性","C. 历史性","D. 时变性"],"ans":[0,1,2,3],"explain":"数据仓库具有以下特点：面向主题、集成性、企业范围、历史性、时变性。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154950","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于数据预处理方法的有（ ）。","opts":["A. 数据清理","B. 数据集成","C. 数据变换","D. 数据归约"],"ans":[0,1,2,3],"explain":"数据预处理主要包括：数据清理、数据集成、数据变换、数据归约。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154951","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于处理缺失值方法的有（ ）。","opts":["A. 忽略元组","B. 使用全局常量填充","C. 使用属性的均值填充","D. 使用最有可能的值填充"],"ans":[0,1,2,3],"explain":"教材列举的处理缺失值方法包括：忽略元组、人工填写缺失值、使用全局常量填充、使用属性的均值填充、使用与给定元组属同一类的所有样本的属性均值、使用最有可能的值填充。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154952","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于数据光滑技术的有（ ）。","opts":["A. 分箱","B. 回归","C. 聚类","D. 最小-最大规范化"],"ans":[0,1,2],"explain":"数据光滑技术包括分箱、回归、聚类。最小-最大规范化属于数据变换中的规范化方法，不属于数据光滑技术。"},{"id":"ai13011-pl-P5154953","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下关于分箱方法的描述，正确的有（ ）。","opts":["A. 等深分箱法每箱具有相同的记录数","B. 等宽分箱法使数据集在整个属性值的区间上平均分布","C. 用户自定义区间是分箱方法之一","D. 分箱是通过考察数据的“近邻”来确定最终值"],"ans":[0,1,2],"explain":"A项正确：等深分箱法将数据集按记录行数分箱，每箱具有相同的记录数。B项正确：等宽分箱法使数据集在整个属性值的区间上平均分布。C项正确：用户自定义区间是分箱方法之一。D项错误：分箱是通过考察数据的“近邻”来确定最终值，这是分箱的定义本身，但D项描述的是分箱的一般原理而非分箱方法的分类。"},{"id":"ai13011-pl-P5154954","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"数据集成中的主要问题包括（ ）。","opts":["A. 模式匹配","B. 数据冗余","C. 数据值冲突的检测与处理","D. 数据可视化"],"ans":[0,1,2],"explain":"数据集成有三个主要问题：模式匹配、数据冗余、数据值冲突的检测与处理。D项数据可视化不属于数据集成的问题。"},{"id":"ai13011-pl-P5154955","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于数据变换内容的有（ ）。","opts":["A. 光滑","B. 聚集","C. 数据泛化","D. 规范化"],"ans":[0,1,2,3],"explain":"数据变换涉及的内容包括：光滑、聚集、数据泛化、规范化、属性构造。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154956","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于数据归约策略的有（ ）。","opts":["A. 维归约","B. 数值归约","C. 数据压缩","D. 数据集成"],"ans":[0,1,2],"explain":"数据归约策略包括维归约、数值归约、数据压缩。数据集成属于数据预处理方法，不属于数据归约策略。"},{"id":"ai13011-pl-P5154957","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下关于模型超参数的描述，正确的有（ ）。","opts":["A. 超参数不是通过学习算法得来的","B. 超参数同样需要进行调优","C. 特征的数目是超参数的一个例子","D. 超参数是通过模型训练中的学习算法而进行调整的"],"ans":[0,1,2],"explain":"A项正确：模型超参数不是通过学习算法得来的。B项正确：超参数同样需要进行调优。C项正确：特征的数目是超参数的一个例子。D项错误：模型参数是通过模型训练中的学习算法而进行调整的，而非超参数。"},{"id":"ai13011-pl-P5154958","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于分类评价指标的有（ ）。","opts":["A. 精确率","B. 召回率","C. F1值","D. RMSE"],"ans":[0,1,2],"explain":"分类评价指标包括精确率-召回率(Precision-Recall)等。RMSE（平方根误差）属于回归评价指标，不属于分类评价指标。"},{"id":"ai13011-pl-P5154959","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于回归评价指标的有（ ）。","opts":["A. RMSE","B. MAPE","C. “Almost Correct” Predictions","D. 准确率"],"ans":[0,1,2],"explain":"教材列举的回归评价指标包括：RMSE、Quantiles of Errors（如MAPE）、“Almost Correct” Predictions。准确率属于分类评价指标。"},{"id":"ai13011-pl-P5154960","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下关于RMSE的缺点及改进方法的描述，正确的有（ ）。","opts":["A. RMSE对异常点敏感","B. 可以使用中位数来代替平均数以提高鲁棒性","C. MAPE是相对误差的中位数","D. RMSE完全不适用于回归任务"],"ans":[0,1,2],"explain":"A项正确：RMSE使用平均误差，对异常点敏感。B项正确：为了提高鲁棒性，可以使用中位数来代替平均数。C项正确：MAPE是一个相对误差的中位数。D项错误：RMSE是回归模型中最常用的评价指标之一。"},{"id":"ai13011-pl-P5154961","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于数据可视化发展历程阶段的有（ ）。","opts":["A. 科学可视化","B. 信息可视化","C. 数据可视化","D. 人工智能可视化"],"ans":[0,1,2],"explain":"数据可视化的发展经历了科学可视化、信息可视化、数据可视化三个阶段。人工智能可视化不属于可视化的发展阶段。"},{"id":"ai13011-pl-P5154962","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于数据清洗类可视化工具的有（ ）。","opts":["A. Data Wrangler","B. OpenRefine","C. D3.js","D. Gephi"],"ans":[0,1],"explain":"教材将Data Wrangler和OpenRefine归为数据清洗类工具。D3.js和Gephi属于可视化应用与服务类工具。"},{"id":"ai13011-pl-P5154963","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下属于可视化应用与服务类工具的有（ ）。","opts":["A. D3.js","B. Gephi","C. ECharts","D. Bonsaijs"],"ans":[0,1,2,3],"explain":"教材列举的可视化应用与服务类工具包括：D3.js、Gephi、ECharts、Bonsaijs等。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154964","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下关于D3.js的描述，正确的有（ ）。","opts":["A. D3是指数据驱动文档(Data-Driven Documents)","B. D3.js是一个JavaScript库","C. D3.js严格遵循Web标准","D. D3.js适合超大规模数据的展示"],"ans":[0,1,2,3],"explain":"A项正确：D3是指数据驱动文档。B项正确：D3.js是一个JavaScript库。C项正确：D3.js严格遵循Web标准。D项正确：D3.js尤其适合大数据量的展示和交互式动态效果的渲染。"},{"id":"ai13011-pl-P5154965","type":"mc","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"以下关于ECharts的描述，正确的有（ ）。","opts":["A. ECharts是百度团队开源的JS框架","B. ECharts底层依赖轻量级的Canvas类库ZRender","C. ECharts提供了丰富的图表类型","D. ECharts对超大规模数据的可视化能提供很好的支持"],"ans":[0,1,2],"explain":"A项正确：ECharts是百度团队开源的JS框架。B项正确：ECharts底层依赖轻量级的Canvas类库ZRender。C项正确：ECharts提供了丰富的图表类型。D项错误：ECharts是一款轻量级的工具，对超大规模数据的可视化不能提供很好的支持。"},{"id":"ai13011-pl-P5155040","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述大数据的4V特征及其含义。","opts":[],"ans":null,"explain":"教材明确指出大数据具有大容量(Volume)、多种类(Variety)、速度快(Velocity)、真实性(Veracity)四个特征，并对每个特征进行了详细解释。\n大数据的4V特征包括：（1）Volume（大容量）：数据体量巨大，已经超越EB级别；（2）Variety（多种类）：数据可被归类为结构化、半结构化和非结构化数据；（3）Velocity（速度快）：须用高效快速的处理方式对数据进行处理；（4）Veracity（真实性）：可靠的数据来源能够保障数据的真实性，只有根据真实可靠的数据才能制定确实可靠的决策。"},{"id":"ai13011-pl-P5155041","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述大数据分析信息时的三个转变。","opts":[],"ans":null,"explain":"这三个转变是初学者需要注意的核心概念，体现大数据思维方式的根本变化。\n大数据的精髓在于分析信息时的三个转变：（1）在大数据时代可以分析更多的数据，有时甚至可以处理和某个特别现象相关的所有数据，而不再依赖于随机采样；（2）研究数据量之多使人们不再热衷于追求精确度；（3）大数据侧重对相关关系的发掘而不再注重因果关系。"},{"id":"ai13011-pl-P5155042","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述人工智能三大派别（符号主义、连接主义、行为主义）的核心思想。","opts":[],"ans":null,"explain":"教材详细阐述了三大派别的起源、核心观点和研究角度，这是人工智能发展史上的重要分类。\n（1）符号主义（Symbolicism）：起源于数理逻辑，认为思维的基本单元是符号，认知的过程可以被建模为符号表示的运算，希望通过符号建模人类学习事物的过程。（2）连接主义（Connectionism）：从仿生学角度出发，通过算法模仿人类的神经元构建神经网络，强调复杂的智能活动是由大量简单单元并行运行的结果。（3）行为主义（Actionism）：从生物对环境的适应（控制论）角度出发，将生物的适应过程建模成基于“感知-行动”的方法，主要作用在于预见和控制行为。"},{"id":"ai13011-pl-P5155043","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述当前大数据与人工智能发展过程中面临的主要难题与挑战。","opts":[],"ans":null,"explain":"教材从五个方面系统阐述了大数据和人工智能在发展中面临的核心挑战。\n当前大数据与人工智能面临的主要难题包括：（1）机器翻译的歧义性问题：现有自然语言理解系统缺乏结合具体语境消除歧义的能力，学习深度不足；（2）自动定理证明的演绎局限：归结原理与人类自然演绎推理不同，将逻辑公式转化为子句集合时丧失了固有的逻辑蕴含语意；（3）模式识别与人脑机制的差距：模式识别的理论方法与人类认识外界的感官机制及形象思维能力相比仍有较大差距；（4）大数据的隐私与安全风险：数据爆炸式增长下，缺乏适当的安全基础结构会导致数据被滥用或泄露；（5）人工智能的偏见与安全性隐患：机器学习可能自主摄入性别或种族歧视，且易被恶意利用威胁安全。"},{"id":"ai13011-pl-P5155044","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述数据工程的一般流程。","opts":[],"ans":null,"explain":"教材系统列出了数据工程的七个核心流程，并解释了每个流程的基本含义。\n数据工程一般分为以下流程：数据获取（将不同数据源的数据自动收集到一个装置中）、数据存储（对采集到的数据进行持久化的保存）、数据清洗（把非格式化或“污染”的数据规范化为标准格式）、数据建模（定义支持商业流程所需要的数据要求的过程）、数据处理（对数据的采集、存储、检索、加工、变换和传输等操作）、数据分析（从海量数据中利用数据挖掘的方法获取有价值的信息）、数据可视化（把数据通过直观的可视化的方式展示给用户）。"},{"id":"ai13011-pl-P5155045","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述网络数据采集的基本步骤。","opts":[],"ans":null,"explain":"教材通过图2-2详细展示了Web数据采集和处理的完整流程。\n网络数据采集的基本步骤为：（1）将需要抓取数据网站的URL信息写入URL队列；（2）爬虫从URL队列中获取需要抓取数据网站的Site URL信息；（3）爬虫从Internet抓取对应网页内容，并抽取其特定属性的内容值；（4）爬虫将从网页中抽取的数据写入数据库；（5）DP(Data Process)读取Spider Data，并进行处理；（6）DP将处理后的数据写入数据库。"},{"id":"ai13011-pl-P5155046","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述数据仓库的核心特点。","opts":[],"ans":null,"explain":"教材从五个方面系统阐述了数据仓库的核心特点，帮助学生理解数据仓库与传统操作型数据库的区别。\n数据仓库具有以下核心特点：（1）面向主题：是数据仓库和操作型数据库的根本区别，数据仓库是为了对抽象出的主题（如用户、商品等）进行分析而建立；（2）集成性：会将来自不同源数据库中的数据进行整理、转换并汇总到一起；（3）企业范围：数据仓库内的数据面向企业全局，汇集全企业与该主题相关的全部信息；（4）历史性：保存的时间跨度长，通常能保存几年甚至几十年的历史数据；（5）时变性：包含时间范围内不同时间段的数据快照，可用于生成各历史阶段的数据分析报告。"},{"id":"ai13011-pl-P5155047","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述数据预处理的目的是什么？包括哪些主要方法？","opts":[],"ans":null,"explain":"教材阐述了数据预处理的必要性及其四大主要方法。\n数据预处理的目的是：现实世界中的数据大体上是不完整、不一致、含有噪声的，无法直接进行数据挖掘，或挖掘结果差强人意。没有高质量的数据，就没有高质量的挖掘结果。为了提高数据挖掘的质量，产生了数据的预处理技术。数据预处理主要包括以下方法：（1）数据清理：通过填写缺失的值、光滑噪声数据、识别或删除离群点并解决不一致性来“清理”数据；（2）数据集成：将多个数据源中的数据结合起来并统一存储；（3）数据变换：通过平滑、聚集、规范化等方法把原始数据转换成适合数据挖掘的形式；（4）数据归约：通过维归约、数值归约、数据压缩等方法得到数据集的归约表示。"},{"id":"ai13011-pl-P5155048","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述处理缺失值的常用方法。","opts":[],"ans":null,"explain":"教材列举了六种处理缺失值的常用方法，并对每种方法的适用场景进行了说明。\n处理缺失值的常用方法包括：（1）忽略元组：当挖掘任务涉及分类且缺少类标号时可用；（2）人工填写缺失值：缺失量大时不可行；（3）使用全局常量填充缺失值：简单但不可靠；（4）使用属性的均值填充缺失值：正常数据分布使用均值，倾斜数据分布使用中位数；（5）使用与给定元组属同一类的所有样本的属性均值；（6）使用最有可能的值填充缺失值：可以用回归、贝叶斯推理或决策树归纳确定，是最流行的数据处理方法。"},{"id":"ai13011-pl-P5155049","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述RMSE作为回归评价指标的主要缺点及改进方法。","opts":[],"ans":null,"explain":"RMSE对异常点敏感，并给出了两种改进方案。\nRMSE的主要缺点：RMSE在计算中依赖平均误差，而平均值对异常点极其敏感。如果回归模型对某个异常点的预测偏差极大，该偏差平方后会大幅拉高RMSE的数值，导致评价指标无法真实客观地反映模型在绝大多数正常样本上的拟合性能（即RMSE是非鲁棒的）。改进方法与替代指标：（1）使用误差的分位数（如中位数）替代平均数：如使用MAPE（相对误差的中位数），由于中位数不受极值变动的影响，具有较强的鲁棒性；（2）剔除异常点后计算误差：设定相对误差阈值，将超过该阈值的异常点直接剔除，然后再计算剩余正常样本的平均误差或中位数误差。"},{"id":"ai13011-pl-P5155030","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"某电商平台每日产生海量用户行为日志，包括浏览、点击、购买等行为数据。请结合大数据与人工智能的相关知识，回答以下问题：（1）请从大数据的4V特征角度，分析该平台日志数据的特点。（2）该平台希望利用这些数据预测用户的购买意向，应该采用什么类型的学习方法？请说明理由。（3）在数据预处理阶段，可能会遇到哪些数据质量问题？应如何处理？","opts":[],"ans":null,"explain":"本题综合考查大数据的4V特征理解、机器学习方法的选择以及数据预处理的实际应用能力，要求学生将理论知识与电商场景相结合。\n（1）大数据的4V特征分析：①Volume（大量）：电商平台每日用户行为日志数量巨大，达到TB甚至PB级别；②Variety（多样）：数据包含结构化数据（订单信息）、半结构化数据（日志文件）和非结构化数据（用户评论、图片）；③Velocity（高速）：用户行为实时产生，需要快速处理和分析；④Veracity（真实性）：需要确保数据来源真实可靠，排除爬虫、恶意点击等噪声数据。（2）应采用监督学习中的分类方法。理由：用户是否购买是一个二分类问题（购买/不购买），可以利用历史已标注数据（已知用户是否购买）作为训练集，提取用户行为特征（浏览时长、点击频次、加购行为等），训练分类模型（如逻辑斯蒂回归、决策树、随机森林等）来预测新用户的购买意向。（3）可能遇到的数据质量问题及处理方法：①缺失值：用户部分信息缺失，可采用均值填充、众数填充或使用最有可能的值填充；②噪声数据：存在爬虫访问或误点击，可采用分箱、回归或聚类方法进行数据光滑；③不一致数据：不同数据源的用户ID格式不统一，需要进行数据集成和模式匹配；④重复数据：同一用户多次记录，需要识别并去重。"},{"id":"ai13011-pl-P5155031","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"某银行希望构建一个信用评分系统，用于判断贷款申请人的信用风险等级（低风险、中风险、高风险）。请回答以下问题：（1）从数据工程的角度，该系统的数据获取、存储和清洗分别应考虑哪些问题？（2）若选用决策树作为分类模型，请简述决策树在该场景下的优势和训练过程中需要注意的问题。（3）如何评估该模型的分类效果？请列举至少两种评估指标并说明其含义。","opts":[],"ans":null,"explain":"本题综合考查数据工程全流程、决策树模型的特点与应用以及模型评估方法，要求学生具备从数据到模型再到评估的完整项目思维。\n（1）数据获取：应从内部系统（客户信息、历史贷款记录、还款记录）和外部数据源（征信机构、第三方数据）获取数据，注意数据合规性和隐私保护。数据存储：应采用数据仓库方式存储，面向客户信用这一主题进行组织，保留历史性数据以便进行时序分析。数据清洗：需要处理缺失值（如收入信息缺失）、异常值（如年龄异常）、不一致数据（如不同源地址信息不统一）等。（2）决策树的优势：①决策树模型具有可解释性，可以直观展示信用评分的决策规则，符合金融监管对模型可解释性的要求；②能够处理数值型（收入、年龄）和分类型（职业、学历）混合特征；③不需要对数据分布做严格假设。训练中需要注意的问题：①防止过拟合，需要采用预剪枝或后剪枝策略；②处理类别不平衡问题（高风险客户可能占比较少）；③连续特征需要选择合适的离散化分割点。（3）评估指标：①准确率（Accuracy）：预测正确的样本占总样本的比例，适用于类别平衡的场景；②精确率（Precision）和召回率（Recall）：精确率是预测为正例中实际为正例的比例，召回率是实际正例中被正确预测的比例，对于信用风险评估（高风险客户识别）尤为重要；③F1值：精确率和召回率的调和平均数，综合评估模型性能；④混淆矩阵：直观展示各类别的预测结果分布。此外还可使用AUC-ROC曲线评估模型的排序能力。"},{"id":"ai13011-pl-P5155039","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"某智慧城市项目需要采集和分析城市交通数据。请回答以下问题：（1）从数据来源的角度，城市交通数据可以来自哪些渠道？（2）这些数据具有什么格式特征？属于哪种数据类型？（3）若要实时处理这些交通数据进行拥堵预警，应选用什么大数据流处理框架？请说明理由。","opts":[],"ans":null,"explain":"本题综合考查数据来源多样性、数据格式特征以及流处理框架的选型能力。\n（1）城市交通数据来源：①路网摄像头/传感器：实时监测车流量、车速、车道占用率；②地面公交：公交车的GPS定位、到站信息、刷卡记录；③轨道交通：地铁闸机刷卡数据、列车运行位置；④出租车：浮动车GPS轨迹数据、运营数据；⑤手机定位数据：用户位置信息，可推断交通出行OD（起止点）分布；⑥高速ETC数据：高速公路出入口通行记录；⑦交通卡刷卡记录：公共交通支付数据；⑧问卷调查数据：居民出行调查。（2）数据格式特征和类型：①数据体量巨大，日均产生千万级记录（如每天2000万条浮动车数据、1900万条交通卡记录），属于大数据范畴；②数据格式多样，包含结构化数据（刷卡记录、ETC数据）、半结构化数据（GPS轨迹JSON/XML）和非结构化数据（视频监控）；（3）数据类型属于流式数据（连续实时产生）和时间序列数据（带时间戳），数据流动速度快（Velocity高）。（3）应选用Apache Flink作为流处理框架，理由：①Flink是专为分布式、高性能、低延迟的流处理设计的框架，支持毫秒级延迟，满足实时拥堵预警的时效性要求；②Flink同时支持高吞吐量和低延迟，能够在保证处理速度的同时处理大规模交通数据流；③Flink支持事件时间和处理时间两种时间语义，可灵活处理交通数据中的时间窗口统计（如5分钟平均车速）；④Flink具备自动反压机制，能应对交通高峰期的数据流量突发；⑤Flink与Hadoop生态集成良好，可将实时处理结果存入HDFS或HBase供后续分析。若需对流数据进行批处理混合分析，Spark Streaming也是备选，但Flink在纯流处理场景中延迟更低。"},{"id":"ai13011-pl-P5155080","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"“大数据”一词最早出现在20世纪90年代的__1__。","opts":[],"ans":["美国"],"explain":"“大数据”一词最早出现在20世纪90年代的美国，后来逐渐获得业界广泛关注。\n参考答案: A.美国"},{"id":"ai13011-pl-P5155081","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"谷歌的__1__和开源的Hadoop平台的出现使人们可以处理的数据量大大增加，从而提升了对大量数据的处理能力。","opts":[],"ans":["Map Reduce"],"explain":"谷歌的Map Reduce和开源的Hadoop平台的出现使人们可以处理的数据量大大增加。\n参考答案: A.Map Reduce"},{"id":"ai13011-pl-P5155082","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"2012年4月，第一家大数据公司__1__在纳斯达克上市。","opts":[],"ans":["Splunk"],"explain":"2012年4月，第一家大数据公司Splunk在纳斯达克上市。\n参考答案: A.Splunk"},{"id":"ai13011-pl-P5155083","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"2015年，__1__印发《促进大数据发展行动纲要》，明确提出要推动大数据的发展和应用。","opts":[],"ans":["国务院"],"explain":"2015年国务院印发《促进大数据发展行动纲要》，大数据正式进入我国国家发展战略。\n参考答案: A.国务院"},{"id":"ai13011-pl-P5155084","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"大数据特征中，Volume指的是__1__，Variety指的是__2__，Velocity指的是__3__，Veracity指的是__4__。","opts":[],"ans":["大容量（大量）B.多种类（多样）C.速度快（高速）D.真实性"],"explain":"教材明确指出大数据的4V特征包括：Volume（大容量）、Variety（多种类）、Velocity（速度快）、Veracity（真实性）。\n参考答案: A.大容量（大量）B.多种类（多样）C.速度快（高速）D.真实性"},{"id":"ai13011-pl-P5155085","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"大数据特征中，在获得数据之前无法提前预知其结构，目前绝大多数数据是__1__数据或半结构化数据。","opts":[],"ans":["非结构化"],"explain":"非结构性是指在获得数据之前无法提前预知其结构，目前绝大多数数据是非结构化数据或半结构化数据。\n参考答案: A.非结构化"},{"id":"ai13011-pl-P5155086","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"大数据的核心功能是__1__，通过将数学算法运用到海量的数据上来预测事情发生的可能性。","opts":[],"ans":["预测"],"explain":"大数据的核心功能是预测。\n参考答案: A.预测"},{"id":"ai13011-pl-P5155087","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"人工智能(AI)最初是在1956年的__1__学会上提出的。","opts":[],"ans":["Dartmouth（达特茅斯）"],"explain":"人工智能最初是在1956年的Dartmouth学会上提出的。\n参考答案: A.Dartmouth（达特茅斯）"},{"id":"ai13011-pl-P5155088","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"人工智能的三大派别包括符号主义、__1__和行为主义。","opts":[],"ans":["连接主义"],"explain":"人工智能的派别分为三种，包括符号主义、连接主义和行为主义。\n参考答案: A.连接主义"},{"id":"ai13011-pl-P5155089","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"1986年，经典的反向传播算法(BP)被__1__等提出。","opts":[],"ans":["Rumelhart"],"explain":"1986年，经典的反向传播算法(BP)被Rumelhart等提出。\n参考答案: A.Rumelhart"},{"id":"ai13011-pl-P5155090","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"__1__是目前人工智能中成果最丰富的研究领域之一，也是研究人员最活跃的研究热点之一。","opts":[],"ans":["专家系统"],"explain":"专家系统是目前人工智能中成果最丰富的研究领域之一。\n参考答案: A.专家系统"},{"id":"ai13011-pl-P5155091","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"大数据和人工智能实际上相辅相成、互相促进发展。一方面，人工智能的决策和判断建立在大量__1__基础上；另一方面，人工智能为大数据提供了技术支持。","opts":[],"ans":["数据"],"explain":"人工智能的决策和判断是建立在大量数据的基础上，只有通过大量的数据进行训练、预测、验证，人工智能才能发挥出真正的威力。\n参考答案: A.数据"},{"id":"ai13011-pl-P5155092","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在机器翻译中，要想消除歧义，正确解释句子语意必须结合具体__1__。","opts":[],"ans":["语境"],"explain":"要想消除歧义，正确解释句子语意必须结合具体语境。\n参考答案: A.语境"},{"id":"ai13011-pl-P5155093","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"数据工程一般分为：数据获取、数据存储、__1__、数据建模、数据处理、数据分析、数据可视化等若干个流程。","opts":[],"ans":["数据清洗"],"explain":"数据工程一般分为：数据获取、数据存储、数据清洗、数据建模、数据处理、数据分析、数据可视化等若干个流程。\n参考答案: A.数据清洗"},{"id":"ai13011-pl-P5155094","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在基于网络爬虫的数据采集和处理过程中，第一步是将需要抓取数据网站的__1__信息写入队列。","opts":[],"ans":["URL"],"explain":"Web数据采集和处理的第一步是将需要抓取数据网站的URL信息写入URL队列。\n参考答案: A.URL"},{"id":"ai13011-pl-P5155095","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"Splunk是一个分布式的机器数据平台，在其架构的三个核心角色中，负责数据的收集、清洗、变形，并将处理后的数据发送给Indexer的角色是__1__。","opts":[],"ans":["Forwarder"],"explain":"Splunk架构中，Forwarder负责数据的收集、清洗、变形，并发送给Indexer。\n参考答案: A.Forwarder"},{"id":"ai13011-pl-P5155096","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"数据存储方式有三种：文件、__1__、网络。","opts":[],"ans":["数据库"],"explain":"数据存储方式有三种：文件、数据库、网络。\n参考答案: A.数据库"},{"id":"ai13011-pl-P5155097","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"数据仓库强调利用某些特殊资料存储方式，使所包含的资料有利于__1__，以产生有价值的资讯并依此做决策。","opts":[],"ans":["分析处理"],"explain":"数据仓库强调利用某些特殊资料存储方式，使所包含的资料有利于分析处理，以产生有价值的资讯并依此做决策。\n参考答案: A.分析处理"},{"id":"ai13011-pl-P5155098","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"数据预处理主要包括数据清理、数据集成、__1__、数据归约四种方法。","opts":[],"ans":["数据变换"],"explain":"数据预处理主要包括数据清理、数据集成、数据变换、数据归约四种方法。\n参考答案: A.数据变换"},{"id":"ai13011-pl-P5155099","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在数据集成过程中，检测不同属性间是否存在冗余时，对于标称数据通常使用__1__检验。","opts":[],"ans":["卡方"],"explain":"对于标称数据，使用卡方检验检测冗余。\n参考答案: A.卡方"},{"id":"ai13011-pl-P5155100","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在数据变换的规范化方法中，最小-最大规范化的公式为$v&#039; = [(v - min)/(max - min)] \\times (new\\_max - new\\_min) +$ __1__。","opts":[],"ans":["new_min"],"explain":"教材给出的最小-最大规范化公式为$v&#039; = [(v - min)/(max - min)] \\times (new\\_max - new\\_min) + new\\_min$。\n参考答案: A.new_min"},{"id":"ai13011-pl-P5155101","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"数据归约策略包括__1__、数值归约、数据压缩。","opts":[],"ans":["维归约"],"explain":"数据归约策略包括维归约、数值归约、数据压缩。\n参考答案: A.维归约"},{"id":"ai13011-pl-P5155102","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"回归模型中最常用的评价模型是__1__，又被称为RMSD。","opts":[],"ans":["RMSE（平方根误差）"],"explain":"回归模型中最常用的评价模型是平方根误差(RMSE)，又被称为RMSD。\n参考答案: A.RMSE（平方根误差）"},{"id":"ai13011-pl-P5155103","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"数据可视化领域的起源可以追溯到20世纪50年代__1__的早期。","opts":[],"ans":["计算机图形学"],"explain":"数据可视化领域的起源可以追溯到20世纪50年代计算机图形学的早期。\n参考答案: A.计算机图形学"},{"id":"ai13011-pl-P5154703","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Hadoop的开源起源于Google早期发表的三篇关键技术论文。其中，Hadoop的分布式文件系统HDFS主要是受到Google哪项技术的启发而提出的？","opts":["A. Bigtable","B. GFS","C. Google Map Reduce","D. PageRank"],"ans":1,"explain":"GFS（Google File System）主要解决如何以文件形式存储大规模数据的问题，Hadoop的分布式文件系统HDFS正是受GFS的启发而提出的。"},{"id":"ai13011-pl-P5154704","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Hadoop是开源项目Nutch搜索引擎开发者（ ）在受到Google的启发后提出的。","opts":["A. Doug Cutting","B. Larry Page","C. Sergey Brin","D. Mark Zuckerberg"],"ans":0,"explain":"Hadoop是开源项目Nutch搜索引擎开发者Doug Cutting在受到Google Map Reduce和GFS的启发后所提出的。"},{"id":"ai13011-pl-P5154705","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Hadoop作为一个主流的大数据分布式并行化处理框架，其两大核心部分分别负责分布式存储与分析处理。其中负责实现数据分析处理的核心组件是（ ）。","opts":["A. HDFS","B. HBase","C. Hive","D. Map Reduce"],"ans":3,"explain":"Hadoop提供了可靠的共享存储和分析系统。其中，HDFS实现数据的分布式存储，而Map Reduce实现数据的分析处理，这两部分是Hadoop框架最核心的部分。"},{"id":"ai13011-pl-P5154706","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Hadoop的主要优势中，将数据分布到由廉价PC机组成的集群中进行处理，从而大幅降低硬件成本，这体现了Hadoop的哪项优势？","opts":["A. 可扩展性","B. 经济性","C. 有效性","D. 可靠性"],"ans":1,"explain":"经济性是指Hadoop将数据分布到由廉价PC机组成的集群中进行处理，这些集群可以由很多个节点组成，大幅降低了硬件成本。"},{"id":"ai13011-pl-P5154707","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"关于HDFS名字节点(NameNode)及其元数据的描述，下列说法正确的是（ ）。","opts":["A. NameNode的元信息中永久持久化保存了每个数据块的精确位置信息","B. 假设块大小一定，文件越小，存储同等大小文件所需要的元信息越少","C. NameNode元信息中保存了文件名、目录名及层级关系、文件权限以及块名称和组成等","D. 实际文件数据的保存与操作是由NameNode负责的"],"ans":2,"explain":"NameNode元信息并不包含每个块的位置信息，位置信息在NameNode启动时从各个DataNode获取并保存在内存中；文件越小，存储同等大小文件所需要的元信息越多；实际文件数据的保存与操作由DataNode负责。因此选项C正确。"},{"id":"ai13011-pl-P5154708","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在HDFS中，NameNode元信息不包含以下哪项内容？","opts":["A. 文件名、目录名及它们之间的层级关系","B. 文件目录的所有者及其权限","C. 每个文件块的位置信息","D. 每个文件块的名称及文件由哪些块组成"],"ans":2,"explain":"NameNode元信息并不包含每个块的位置信息，位置信息在NameNode启动时从各个DataNode获取并保存在内存中。"},{"id":"ai13011-pl-P5154709","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Hadoop 0.21.0版本之后，SecondaryNameNode的概念被（ ）所取代。","opts":["A. CheckpointNode","B. BackupNode","C. DataNode","D. NameNode"],"ans":0,"explain":"在Hadoop 0.21.0版本之后，SecondaryNameNode的概念被CheckpointNode所取代。"},{"id":"ai13011-pl-P5154710","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"HDFS读取数据时，客户端首先与哪个组件交互获取文件块的位置信息？","opts":["A. DataNode","B. NameNode","C. SecondaryNameNode","D. JobTracker"],"ans":1,"explain":"HDFS通过远程调用NameNode获取文件块的位置信息，对于文件的每一个块，NameNode会返回含有该块副本的DataNode地址。"},{"id":"ai13011-pl-P5154711","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Map Reduce运行框架中，主要负责协调Map Reduce作业执行的主控节点是（ ）。","opts":["A. JobClient","B. JobTracker","C. TaskTracker","D. DataNode"],"ans":1,"explain":"JobTracker负责协调Map Reduce作业的执行，是Map Reduce运行的主控节点。"},{"id":"ai13011-pl-P5154712","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Map Reduce作业的运行流程中，第1阶段是（ ）。","opts":["A. 作业初始化阶段","B. 任务分配阶段","C. 作业提交阶段","D. 任务执行阶段"],"ans":2,"explain":"Map Reduce作业运行流程的第1阶段为作业提交阶段，包含用户创建JobClient实例、请求JobId、复制资源到HDFS、告知JobTracker准备执行等过程。"},{"id":"ai13011-pl-P5154713","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Hadoop 2.0版本以后引入了YARN计算框架，其核心目标是将原有Map Reduce中JobTracker的两个最主要功能进行拆分，独立到两个进程中。这两个最主要功能是（ ）。","opts":["A. 文件存储与数据备份","B. 资源管理与作业调度","C. 任务分配与日志收集","D. 进程监控与状态同步"],"ans":1,"explain":"Hadoop 2.0版本以后引入了YARN计算框架，核心目标是将JobTracker的资源管理和作业调度两个最主要功能进行拆分，独立到两个进程中。"},{"id":"ai13011-pl-P5154714","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"YARN框架中，负责管理每个计算节点上资源的使用情况并对调度器进行报告的组件是（ ）。","opts":["A. 资源管理器","B. 应用管理器","C. 调度器","D. 节点管理器"],"ans":3,"explain":"节点管理器运行在每个计算节点上，监控资源的使用情况并且对调度器进行报告。"},{"id":"ai13011-pl-P5154715","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"以下哪个是用于Hadoop系统与传统数据库间进行数据交互的工具？","opts":["A. Hive","B. Pig","C. Sqoop","D. ZooKeeper"],"ans":2,"explain":"Sqoop是用于Hadoop系统与传统数据库间进行数据交互的工具。"},{"id":"ai13011-pl-P5154716","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Hadoop相关技术中，ZooKeeper的作用是（ ）。","opts":["A. 数据仓库管理工具","B. 分布式应用程序协调服务器","C. 大数据分析工具","D. 分布式文件系统"],"ans":1,"explain":"ZooKeeper是分布式应用程序协调服务器。"},{"id":"ai13011-pl-P5154717","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Hadoop的运行模式中，不使用HDFS也不加载任何Hadoop守护进程的模式是（ ）。","opts":["A. 单机模式","B. 伪分布式模式","C. 完全分布式模式","D. 集群模式"],"ans":0,"explain":"单机模式是Hadoop的默认模式，不使用HDFS，也不加载任何Hadoop的守护进程，主要用于开发调试Map Reduce程序的应用逻辑。"},{"id":"ai13011-pl-P5154718","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Ubuntu系统中安装Hadoop时，SSH的主要作用是（ ）。","opts":["A. 进行数据加密存储","B. 为Hadoop各节点间提供安全的远程登录和通信服务","C. 提供图形界面操作","D. 管理Hadoop的配置文件"],"ans":1,"explain":"Hadoop用SSH通信，SSH是专为远程登录会话和其他网络服务提供安全性的协议。因此SSH的作用是提供安全的通信服务。"},{"id":"ai13011-pl-P5154719","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Map Reduce编程模型将数据的计算分为三个过程，其正确顺序是（ ）。","opts":["A. Reduce → Shuffle → Map","B. Map → Reduce → Shuffle","C. Map → Shuffle → Reduce","D. Shuffle → Map → Reduce"],"ans":2,"explain":"Map Reduce编程模型将数据的计算分为三个过程：Map、Shuffle和Reduce。Map过程对原始数据进行处理，Shuffle过程对数据进行梳理和排序，Reduce过程对数据进行最终计算。"},{"id":"ai13011-pl-P5154720","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在WordCount示例中，Map过程的输出是（ ）。","opts":["A. &lt;文件名, 文件内容&gt;","B. &lt;单词, 1&gt;","C. &lt;单词, 出现次数&gt;","D. &lt;文件行号, 行内容&gt;"],"ans":1,"explain":"在WordCount示例中，Map过程将&lt;key, value&gt;对中的key置为Split中的单词，value置为1，输出&lt;word, 1&gt;。"},{"id":"ai13011-pl-P5154721","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Map Reduce中，大多数Split与HDFS中的block大小相同，都为（ ）。","opts":["A. 32MB","B. 64MB","C. 128MB","D. 256MB"],"ans":1,"explain":"大多数的Split与HDFS中的block大小相同，都为64MB。"},{"id":"ai13011-pl-P5154722","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Map Reduce的Shuffle阶段中，Partition（分区）过程的主要作用是（ ）。","opts":["A. 将输入的原始文本文件按64MB大小切割为多个物理切片","B. 将来自不同Mapper输出的中间结果文件合并为同一个大文件","C. 根据key的不同将数据分发给不同的Reducer，确保同一个key的数据被分发到同一个Reducer","D. 继承org.apache.hadoop.Map Reduce.Mapper类并重写map()方法"],"ans":2,"explain":"Shuffle阶段包含Partition和Merge等过程。Partition的主要作用是根据key的不同（常用Hash方法）将数据分开并分发给不同的Reducer，保证相同key的唯一性并分到同一个Reducer进行计算。"},{"id":"ai13011-pl-P5154723","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在WordCount示例的Reduce阶段，Reduce函数接收的输入是（ ）。","opts":["A. &lt;单词, 1&gt;","B. &lt;单词, [1,1,1...]&gt;","C. &lt;单词, 出现总次数&gt;","D. &lt;文件名, 内容&gt;"],"ans":1,"explain":"Reduce方法完成的任务是将Shuffle过程得到的&lt;key, value1, value2,..., valuen&gt;中的value值相加。在WordCount中，输入为&lt;word, [1,1,1...]&gt;。"},{"id":"ai13011-pl-P5154724","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"相较于Hadoop Map Reduce框架，Spark在处理需要多次迭代的算法时能够显著提升计算效率，其核心原因在于（ ）。","opts":["A. 废除了主从架构，改用对等架构","B. 放弃了数据分片与并行计算机制，采用单机处理","C. 将部分数据集缓存在内存中并采用有向无环图进行任务调度","D. 只能在Linux环境下运行"],"ans":2,"explain":"Spark采用将部分数据集缓存在内存中以减小频繁I/O操作的影响，同时采用有向无环图(DAG)进行任务调度，从而减少了资源消耗与开销。"},{"id":"ai13011-pl-P5154725","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Spark中最核心的数据结构抽象被称为（ ）。","opts":["A. 弹性分布式数据集(RDD)","B. 数据帧(DataFrame)","C. 数据集(DataSet)","D. 弹性数据流(RDS)"],"ans":0,"explain":"RDD是Spark最核心的内容，它表示已被分区、不可变的并能够被并行操作的数据集合。"},{"id":"ai13011-pl-P5154726","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Spark算子中，会提交作业并触发作业执行的算子类型是（ ）。","opts":["A. 创建算子","B. 变换/转换算子","C. 缓存算子","D. 行动算子"],"ans":3,"explain":"行动(Action)算子会提交作业，触发作业的执行，然后将RDD保存为Scala变量，保存到外部文件或数据库中。"},{"id":"ai13011-pl-P5154727","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Spark生态系统中，提供机器学习功能的系统是（ ）。","opts":["A. Spark SQL","B. Spark Streaming","C. MLlib","D. GraphX"],"ans":2,"explain":"MLlib是底层的分布式机器学习库，提供机器学习功能。"},{"id":"ai13011-pl-P5154728","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Spark SQL在整个Spark生态系统中定位为（ ）。","opts":["A. 流计算框架","B. 分析工具","C. 资源调度层","D. 文件存储层"],"ans":1,"explain":"Spark SQL提供在大数据上的SQL查询功能，在整个生态系统的角色定位为分析工具。"},{"id":"ai13011-pl-P5154729","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Spark架构采用了分布式计算中的主从模型，其中Master节点上运行的进程是（ ）。","opts":["A. Worker","B. Executor","C. Master","D. Client"],"ans":2,"explain":"Master是集群中含有Master进程的节点，负责整个集群的正常运行。"},{"id":"ai13011-pl-P5154730","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Windows环境下安装Spark时，解决Windows下Spark某些环境缺失问题需要下载的文件是（ ）。","opts":["A. winutils.exe","B. hadoop.dll","C. sparkenv.sh","D. java.exe"],"ans":0,"explain":"为了解决Windows下Spark某些环境缺失的问题，需要下载winutils.exe。"},{"id":"ai13011-pl-P5154731","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Spark安装时，Scala程序需要在什么环境下运行？","opts":["A. .NET Framework","B. JVM","C. Node.js","D. Python解释器"],"ans":1,"explain":"Spark的编程语言采用Scala，而Scala程序在JVM环境下才能运行。"},{"id":"ai13011-pl-P5154732","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Storm是由（ ）公司开发，后被Twitter收购并开源的实时处理系统。","opts":["A. BackType","B. Facebook","C. Google","D. Amazon"],"ans":0,"explain":"Storm是由BackType公司开发的实时处理系统，2011年被Twitter收购并开源。"},{"id":"ai13011-pl-P5154733","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"以下哪个不是Apache Storm的优势？","opts":["A. 支持任何编程语言","B. 具有很高的延迟","C. 容错的、灵活的、可靠的","D. 允许实时流处理"],"ans":1,"explain":"Storm具有非常低的延迟，可以在几秒或几分钟内执行数据刷新。高延迟不是Storm的特点。"},{"id":"ai13011-pl-P5154734","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Apache Storm的核心概念中，作为数据流(Stream)的源，负责从外部数据源接收输入数据并将数据进一步发射到逻辑处理单元的组件是（ ）。","opts":["A. Tuple","B. Bolt","C. Spout","D. Supervisor"],"ans":2,"explain":"Spout是Stream的源，通常从原始数据源接收输入数据，通过产生新的输出流将数据传递给逻辑处理单元Bolt。"},{"id":"ai13011-pl-P5154735","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Storm集群中，负责在所有工作节点之间分发数据、向工作节点分配任务和监视故障的主节点是（ ）。","opts":["A. Supervisor","B. Nimbus","C. Worker Process","D. Executor"],"ans":1,"explain":"Nimbus是Storm集群的主节点，负责在所有工作节点之间分发数据，向工作节点分配任务和监视故障。"},{"id":"ai13011-pl-P5154736","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"以下哪个不属于Storm的主要应用场景？","opts":["A. 流处理(Stream Processing)","B. 持续计算(Continuous Computation)","C. 批量数据离线分析(Batch Analysis)","D. 分布式远程程序调用(DRPC)"],"ans":2,"explain":"教材列举的Storm应用场景包括流处理、持续计算、分布式远程程序调用。Storm是实时流处理系统，批量数据离线分析不属于其主要应用场景。"},{"id":"ai13011-pl-P5154737","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Apache Storm安装的三个步骤中，不包括以下哪项？","opts":["A. 安装Java","B. 安装ZooKeeper框架","C. 安装Apache Storm框架","D. 安装MySQL数据库"],"ans":3,"explain":"Apache Storm安装三个步骤：安装Java、安装ZooKeeper框架、安装Apache Storm框架。MySQL不属于Storm安装步骤。"},{"id":"ai13011-pl-P5154738","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Storm安装过程中，启动Storm用户界面应用程序后，在浏览器中输入（ ）可以查看Storm集群信息及其运行的拓扑。","opts":["A. http://localhost:8080","B. http://localhost:8088","C. http://localhost:50070","D. http://localhost:9870"],"ans":0,"explain":"启动Storm用户界面应用程序后，在浏览器中输入http://localhost:8080就可以看到Storm集群信息及其运行的拓扑。"},{"id":"ai13011-pl-P5154739","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Apache Flink起源于（ ）项目，于2014年12月成为Apache软件基金会的顶级项目。","opts":["A. Stratosphere","B. Blink","C. Mesos","D. YARN"],"ans":0,"explain":"Flink起源于Stratosphere项目，2014年4月代码被捐赠给Apache软件基金会，2014年12月成为Apache顶级项目。"},{"id":"ai13011-pl-P5154740","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"阿里巴巴在其基础上进行了大规模改进，并于2019年正式开源的实时计算分支是（ ）。","opts":["A. Flink Core","B. Blink","C. Spark Streaming","D. Storm Trident"],"ans":1,"explain":"阿里巴巴实时计算团队建立了Flink分支Blink，用于支撑内部核心实时业务，并于2019年1月正式开源。"},{"id":"ai13011-pl-P5154741","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Apache Flink的运行时架构中，作为控制应用程序执行的主进程，负责接收应用程序并向资源管理器申请任务执行所需Slot资源的组件是（ ）。","opts":["A. TaskManager","B. JobManager","C. Dispatcher","D. ResourceManager"],"ans":1,"explain":"JobManager控制应用程序执行的主进程，接收应用程序并向ResourceManager请求执行任务所需的Slot。"},{"id":"ai13011-pl-P5154742","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Flink运行时四大组件中，真正执行任务的地方是（ ）。","opts":["A. JobManager","B. ResourceManager","C. Dispatcher","D. TaskManager"],"ans":3,"explain":"TaskManager是真正执行任务的地方。"},{"id":"ai13011-pl-P5154743","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Flink的应用场景中，能从一个或多个事件流提取数据，并根据到来的事件触发计算、状态更新或其他外部动作的应用类型是（ ）。","opts":["A. 数据分析应用","B. 事件驱动型应用","C. 数据管道应用","D. 批处理应用"],"ans":1,"explain":"事件驱动型应用是一类具有状态的应用，能从一个或多个事件流提取数据，并根据到来的事件触发计算、状态更新或其他外部动作。"},{"id":"ai13011-pl-P5154744","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Flink安装后，可以通过访问（ ）来查看Web前端界面。","opts":["A. http://localhost:8080","B. http://localhost:8081","C. http://localhost:50070","D. http://localhost:8042"],"ans":1,"explain":"JobManager在8081端口上启动一个Web前端，通过http://localhost:8081来访问。"},{"id":"ai13011-pl-P5154890","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Hadoop的HBase组件对应Google的（ ）技术。","opts":["A. GFS","B. Map Reduce","C. Bigtable","D. PageRank"],"ans":2,"explain":"Hadoop核心组件中的HBase对应Google的Bigtable技术。"},{"id":"ai13011-pl-P5154891","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Hadoop中，通过数据分发在不同节点上并行处理数据，这体现了Hadoop的（ ）优势。","opts":["A. 可扩展性","B. 经济性","C. 有效性","D. 可靠性"],"ans":2,"explain":"有效性是指通过数据分发，Hadoop可以在不同的节点上并行处理数据，使数据处理过程大大提速。"},{"id":"ai13011-pl-P5154892","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"HDFS中，NameNode维护着文件系统命名空间，其元信息中不包括（ ）。","opts":["A. 文件名和目录名","B. 文件目录的所有者及其权限","C. 每个文件块在DataNode上的精确物理存储位置","D. 每个文件块的名称及文件由哪些块组成"],"ans":2,"explain":"NameNode元信息并不包含每个块的位置信息，位置信息在NameNode启动时从各个DataNode获取并保存在内存中。"},{"id":"ai13011-pl-P5154893","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"HDFS写入数据时，数据分组以（ ）的形式被写入和备份到所有DataNode节点。","opts":["A. 并行广播","B. 流水线","C. 批量传输","D. 随机分发"],"ans":1,"explain":"数据分组以流水线的形式被写入和备份到所有DataNode节点。"},{"id":"ai13011-pl-P5154894","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Map Reduce作业运行流程中，TaskTracker定期发送心跳给JobTracker的作用是（ ）。","opts":["A. 传输数据","B. 告知自己还活着以及是否可以接受新的任务","C. 请求新的数据分片","D. 汇报计算结果"],"ans":1,"explain":"每个TaskTracker定期发送心跳给JobTracker，告知自己还活着、是否可以接受新的任务。"},{"id":"ai13011-pl-P5154895","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Hadoop相关技术中，用于安装管理监控Hadoop集群的Web管理工具是（ ）。","opts":["A. Ambari","B. ZooKeeper","C. Hive","D. Pig"],"ans":0,"explain":"Ambari是安装管理监控Hadoop集群的Web管理工具。"},{"id":"ai13011-pl-P5154896","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"在Ubuntu系统中安装Hadoop时，生成SSH免密码登录需要将公钥追加到（ ）文件中。","opts":["A. id_rsa","B. id_rsa.pub","C. authorized_keys","D. known_hosts"],"ans":2,"explain":"将公钥追加到authorized_keys中，用于保存所有允许以当前用户身份登录到SSH客户端用户的公钥内容。"},{"id":"ai13011-pl-P5154897","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Map Reduce编程模型中，Map过程的输入Split与HDFS中的block大小相同的目的是（ ）。","opts":["A. 减少网络传输","B. 增加数据冗余","C. 使Map可以在存储有当前数据的节点上运行本地任务","D. 提高数据压缩率"],"ans":2,"explain":"大多数的Split与HDFS中的block大小相同，这样，Map可以在存储有当前数据的节点上运行本地的任务，而不需要通过网络进行跨节点的任务调度。"},{"id":"ai13011-pl-P5154898","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Shuffle阶段中，保证相同key的数据被分到同一个Reducer的机制是（ ）。","opts":["A. Merge","B. Partition","C. Sort","D. Combine"],"ans":1,"explain":"Partition过程的主要作用是根据key的不同将数据分发给不同的Reducer，保证相同key的唯一性并分到同一个Reducer进行计算。"},{"id":"ai13011-pl-P5154899","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Spark中，用于将内存中的集合或外部文件创建为RDD对象的算子属于（ ）。","opts":["A. 变换算子","B. 行动算子","C. 创建算子","D. 缓存算子"],"ans":2,"explain":"Spark算子分为四类：创建算子用于创建RDD对象；变换算子用于将RDD转换为新的RDD；缓存算子用于将RDD缓存在磁盘或内存中；行动算子会提交作业触发执行。"},{"id":"ai13011-pl-P5154900","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Spark中，关于Job的描述，正确的是（ ）。","opts":["A. Spark中一个Job只有一个Map和Reduce两个阶段","B. Spark中一个Job只能包含一个RDD操作","C. Spark中一个Job可以包含RDD的多个转换操作，在调度时可以生成多个Stage","D. Spark中Job之间的依赖关系需要开发者手动管理"],"ans":2,"explain":"Spark中一个Job可以包含RDD的多个转换操作，在调度时可以生成多个阶段，而且如果多个Map操作的RDD的分区不变，可以放在同一个Task中进行。"},{"id":"ai13011-pl-P5154901","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Spark生态系统中，用于流数据处理的组件是（ ）。","opts":["A. Spark SQL","B. Spark Streaming","C. MLlib","D. GraphX"],"ans":1,"explain":"Spark Streaming通过将流数据按指定时间片累积为RDD，然后将每个RDD进行批处理，进而实现大规模的流数据处理。"},{"id":"ai13011-pl-P5154902","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Apache Storm的核心概念中，元组(Tuple)是（ ）。","opts":["A. 数据流的源","B. 有序元素的列表，是Storm中的主要数据结构","C. 逻辑处理单元","D. 集群的主节点"],"ans":1,"explain":"Tuple是Storm中的主要数据结构，为有序元素的列表。"},{"id":"ai13011-pl-P5154903","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Storm中，工作进程(Worker Process)的作用是（ ）。","opts":["A. 管理集群中的所有节点","B. 执行与特定拓扑相关的任务，创建Executor并要求它们执行特定的任务","C. 接收从外部数据源输入的数据","D. 负责数据存储"],"ans":1,"explain":"Worker Process执行与特定拓扑相关的任务，它不会自己运行任务，而是创建Executor并要求它们执行特定的任务。"},{"id":"ai13011-pl-P5154904","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Flink支持的不同时间语义下灵活的窗口机制，其时间语义不包括（ ）。","opts":["A. 事件时间","B. 处理时间","C. 摄入时间","D. 会话时间"],"ans":2,"explain":"Flink在不同的时间语义(事件时间、处理时间)下支持灵活的窗口(时间、计数、会话、自定义触发器)。摄入时间(Ingestion Time)在教材中未列为Flink的窗口时间语义。"},{"id":"ai13011-pl-P5154905","type":"sc","tier":"基础","conf":"adapt","chap":"第3章","q":"Flink的Standalone模式任务提交流程中，负责将应用移交给JobManager的组件是（ ）。","opts":["A. ResourceManager","B. TaskManager","C. Dispatcher","D. Client"],"ans":2,"explain":"Dispatcher为应用提供REST接口。当应用被提交执行时，Dispatcher将应用移交给JobManager。"},{"id":"ai13011-pl-P5154966","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"Hadoop的主要优势包括（ ）。","opts":["A. 可扩展性","B. 经济性","C. 有效性","D. 可靠性"],"ans":[0,1,2,3],"explain":"Hadoop的主要优势包括：可扩展性、经济性、有效性、可靠性。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154967","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"HDFS的主要组成部分包括（ ）。","opts":["A. NameNode","B. SecondaryNameNode","C. DataNode","D. JobTracker"],"ans":[0,1,2],"explain":"HDFS主要由3个组件构成：NameNode、SecondaryNameNode和DataNode。JobTracker属于Map Reduce运行框架中的组件，不属于HDFS的组成部分。"},{"id":"ai13011-pl-P5154968","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"以下关于HDFS中NameNode的描述，正确的有（ ）。","opts":["A. NameNode管理着文件系统命名空间","B. NameNode维护着文件系统树及树中的所有文件和目录","C. NameNode负责实际文件数据的保存与操作","D. NameNode元信息不包含每个块的位置信息"],"ans":[0,1,3],"explain":"A项正确：NameNode管理着文件系统命名空间。B项正确：NameNode维护着文件系统树及树中的所有文件和目录。C项错误：实际文件数据的保存与操作是由DataNode负责的。D项正确：NameNode元信息并不包含每个块的位置信息。"},{"id":"ai13011-pl-P5154969","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"Map Reduce运行框架中包含的主要组件有（ ）。","opts":["A. JobClient","B. JobTracker","C. TaskTracker","D. NameNode"],"ans":[0,1,2],"explain":"Map Reduce运行框架中主要包含JobClient、JobTracker和TaskTracker。NameNode属于HDFS组件，不属于Map Reduce运行框架。"},{"id":"ai13011-pl-P5154970","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"YARN计算框架中，资源管理器由哪两部分构成？（ ）","opts":["A. 应用管理器","B. 调度器","C. 节点管理器","D. TaskTracker"],"ans":[0,1],"explain":"资源管理器由应用管理器和调度器两部分构成。节点管理器运行在每个计算节点上，不属于资源管理器的组成部分。TaskTracker是原Map Reduce框架中的组件。"},{"id":"ai13011-pl-P5154971","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"以下属于Hadoop相关技术组件的有（ ）。","opts":["A. ZooKeeper","B. Hive","C. Pig","D. Sqoop"],"ans":[0,1,2,3],"explain":"教材列举的Hadoop相关组件包括：Ambari、ZooKeeper、Hive、Pig、Map Reduce、HDFS、YARN、HBase、Hcatalog、Sqoop、Chukwa等。A、B、C、D均属于Hadoop相关技术组件。"},{"id":"ai13011-pl-P5154972","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"Hadoop的运行模式包括（ ）。","opts":["A. 单机模式","B. 伪分布式模式","C. 完全分布式模式","D. 云模式"],"ans":[0,1,2],"explain":"Hadoop的运行模式分为单机模式、伪分布式模式和完全分布式模式。云模式不属于Hadoop的运行模式分类。"},{"id":"ai13011-pl-P5154973","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"Map Reduce编程模型中，Shuffle阶段包括（ ）。","opts":["A. Partition","B. Merge","C. Sort","D. Split"],"ans":[0,1,2],"explain":"Shuffle阶段包括Partition、Merge等，对数据进行梳理和排序。Split属于Map阶段之前的步骤，不属于Shuffle阶段。"},{"id":"ai13011-pl-P5154974","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"以下关于Spark基本概念RDD的描述，正确的有（ ）。","opts":["A. RDD是Spark最核心的内容","B. RDD表示已被分区、不可变的并能够被并行操作的数据集合","C. RDD可以缓存到内存中","D. RDD必须是可序列化的"],"ans":[0,1,2,3],"explain":"A项正确：RDD是Spark最核心的内容。B项正确：RDD表示已被分区、不可变的并能够被并行操作的数据集合。C项正确：RDD可以缓存到内存中。D项正确：RDD必须是可序列化的。"},{"id":"ai13011-pl-P5154975","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"Spark算子大致可以分为以下哪些类别？（ ）","opts":["A. 创建算子","B. 变换/转换算子","C. 缓存算子","D. 行动算子"],"ans":[0,1,2,3],"explain":"Spark算子大致可以分为四类：创建算子、变换/转换算子、缓存算子、行动算子。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154976","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"以下属于Spark生态系统的组件有（ ）。","opts":["A. Spark SQL","B. Spark Streaming","C. MLlib","D. GraphX"],"ans":[0,1,2,3],"explain":"Spark生态系统的组件包括：Spark SQL、Spark Streaming、MLlib、GraphX等。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154977","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"Spark架构中，Worker的作用包括（ ）。","opts":["A. 接收主节点命令","B. 进行状态汇报","C. 负责任务的执行","D. 负责整个集群的正常运行"],"ans":[0,1,2],"explain":"Worker相当于计算节点，接收主节点命令与进行状态汇报，Executor负责任务的执行。Master负责整个集群的正常运行，而非Worker。"},{"id":"ai13011-pl-P5154978","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"以下关于Apache Storm优势的描述，正确的有（ ）。","opts":["A. Storm是开源的、强大的、用户友好的","B. Storm是容错的、灵活的、可靠的","C. Storm具有非常低的延迟","D. Storm可以通过线性增加资源来保持性能"],"ans":[0,1,2,3],"explain":"教材列举的Storm优势包括：开源友好、容错灵活可靠、实时流处理、处理速度快、高度可扩展性、低延迟、保证数据处理等。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154979","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"Storm的核心概念组件包括（ ）。","opts":["A. Tuple","B. Stream","C. Spout","D. Bolt"],"ans":[0,1,2,3],"explain":"Storm的核心概念组件主要有Tuple、Stream、Spout、Bolt。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154980","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"Storm集群架构中的组件包括（ ）。","opts":["A. Nimbus","B. Supervisor","C. Worker Process","D. ZooKeeper Framework"],"ans":[0,1,2,3],"explain":"Storm的集群架构组件主要有Nimbus、Supervisor、Worker Process、Executor、Task、ZooKeeper Framework。A、B、C、D均正确。"},{"id":"ai13011-pl-P5154981","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"以下关于Apache Flink的描述，正确的有（ ）。","opts":["A. Flink起源于Stratosphere项目","B. Flink在德语中表示快速和灵巧","C. Flink于2014年12月成为Apache顶级项目","D. 阿里巴巴在Flink基础上建立了Blink分支"],"ans":[0,1,2,3],"explain":"A项正确：Flink起源于Stratosphere项目。B项正确：Flink在德语中表示快速和灵巧。C项正确：2014年12月Flink成为Apache顶级项目。D项正确：阿里巴巴建立了Flink分支Blink。"},{"id":"ai13011-pl-P5154982","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"以下关于Flink运行时组件的描述，正确的有（ ）。","opts":["A. JobManager控制应用程序执行的主进程","B. TaskManager是真正执行任务的地方","C. ResourceManager管理TaskManager上的Slot","D. Dispatcher为应用提供REST接口"],"ans":[0,1,2,3],"explain":"A项正确：JobManager控制应用程序执行的主进程。B项正确：TaskManager是真正执行任务的地方。C项正确：ResourceManager负责管理TaskManager上的Slot。D项正确：Dispatcher为应用提供REST接口。"},{"id":"ai13011-pl-P5154983","type":"mc","tier":"拔高","conf":"adapt","chap":"第3章","q":"Flink的应用场景包括（ ）。","opts":["A. 事件驱动型应用","B. 数据分析应用","C. 数据管道应用","D. 批量离线计算"],"ans":[0,1,2],"explain":"Flink的应用场景包括事件驱动型应用、数据分析应用、数据管道应用。批量离线计算不是Flink的主要应用场景，Flink主打流处理。"},{"id":"ai13011-pl-P5155050","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"简述Hadoop的主要优势。","opts":[],"ans":null,"explain":"教材从四个方面阐述了Hadoop的核心优势。\nHadoop的主要优势包括：（1）可扩展性：可以可靠地存储和处理Petabyte级别的数据，并且方便地进行拓展；（2）经济性：将数据分布到由廉价PC机组成的集群中进行处理，大幅降低硬件成本；（3）有效性：通过数据分发，可以在不同的节点上并行处理数据，使数据处理过程大大提速；（4）可靠性：自动维护一份数据的多个复制，并自动将失败的计算任务进行重新部署。"},{"id":"ai13011-pl-P5155051","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"简述HDFS中SecondaryNameNode的作用和工作原理。","opts":[],"ans":null,"explain":"教材详细描述了SecondaryNameNode的工作流程及其在HDFS架构中的重要作用。\nSecondaryNameNode的作用是定期地合并Edits和Fsimage文件，解决NameNode重启时合并过程影响重启速度的问题。合并步骤如下：（1）合并之前告知NameNode把所有的操作写到新的Edits文件并命名为edits.new；（2）SecondaryNameNode使用HTTP GET接口从NameNode请求Fsimage和Edits文件；（3）SecondaryNameNode把Fsimage和Edits文件合并成新的Fsimage文件；（4）NameNode从SecondaryNameNode获取合并后的新的Fsimage文件且将旧的替换掉，并把edits.new文件替换掉；（5）更新Fstime文件中的检查点。"},{"id":"ai13011-pl-P5155052","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"简述YARN计算框架的设计目标及其核心组件。","opts":[],"ans":null,"explain":"教材阐述了YARN的设计初衷及其核心组件分工。\nYARN计算框架的核心目标是将JobTracker的资源管理和作业调度两个最主要功能进行拆分，独立到两个进程中。YARN框架的核心组件包括：（1）资源管理器（ResourceManager）：由应用管理器和调度器两部分构成，应用管理器负责客户端对作业的提交，调度器根据CPU和内存等资源进行资源调度；（2）节点管理器（NodeManager）：运行在每个计算节点上，监控资源的使用情况并且对调度器进行报告。YARN相对于原Map Reduce框架降低了主节点的资源消耗，更好地进行资源的调度，提高资源利用率。"},{"id":"ai13011-pl-P5155053","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"简述Map Reduce编程模型中Map、Shuffle和Reduce三个核心阶段的主要作用。","opts":[],"ans":null,"explain":"教材详细阐述了Map Reduce三个核心阶段的作用及键值对的转化过程。\nMap阶段：对原始切片数据进行处理，将其解析并转换为中间键值对&lt;k1,v1&gt;（在WordCount中key为单词，value为1）。Shuffle阶段：对Map阶段输出的&lt;k1,v1&gt;数据进行分区（Partition）、合并（Merge）和排序，将相同key的数据归并到一起，整理为&lt;k2,list(v2)&gt;格式（如&lt;word,[1,1,1...]&gt;），分发给对应的Reducer。Reduce阶段：接收Shuffle阶段输出的&lt;k2,list(v2)&gt;数据，遍历列表中的value并进行聚合计算（如求和），最终输出需要的计算结果&lt;k3,v3&gt;（如&lt;word,total_count&gt;）。"},{"id":"ai13011-pl-P5155054","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"简述Spark的核心概念RDD（弹性分布式数据集）及其主要特点。","opts":[],"ans":null,"explain":"教材从多个维度全面介绍了RDD的定义、性质和优势。\nRDD是Spark最核心的内容，它表示已被分区、不可变的并能够被并行操作的数据集合。RDD的主要特点包括：（1）容错的、并行的数据结构，可以让用户显式地将大的数据分布式存储到集群服务器的内存或硬盘中；（2）不同的数据集格式对应不同的RDD实现；（3）RDD必须是可序列化的；（4）大的数据集合被分成具有标识索引的数组，可以通过记录分块信息的元数据对数据块进行管理；（5）RDD可以缓存到内存中，每次对RDD数据集操作之后的结果都可以存放到内存中，下一个操作可以直接从内存中输入，节省大量磁盘IO操作；（6）提供了一组丰富的变换算子来操作这些数据。"},{"id":"ai13011-pl-P5155055","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"简述Apache Storm的核心概念组件及其作用。","opts":[],"ans":null,"explain":"教材清晰定义了Storm的四个核心概念组件及其在数据流处理中的角色。\nStorm的核心概念组件主要有：（1）Tuple：是Storm中的主要数据结构，为有序元素的列表；（2）Stream：是元组的无序序列；（3）Spout：是Stream的源，从原始数据源接收输入数据，通过产生新的输出流将数据进一步传递到逻辑处理单元Bolt；（4）Bolt：可以执行过滤、聚合、加入、与数据源和数据库交互的操作，接收数据并发射到一个或多个Bolt。"},{"id":"ai13011-pl-P5155056","type":"sa","tier":"创新","conf":"adapt","chap":"第3章","q":"简述Apache Flink的运行时四大组件及其分工。","opts":[],"ans":null,"explain":"教材阐述了Flink运行时四大组件的职责分工及其协作关系。\nFlink在运行时的四大组件为：（1）JobManager（作业管理器）：控制应用程序执行的主进程，接收需要执行的应用程序，并向ResourceManager请求执行任务必要的资源，即TaskManager上的Slot；（2）TaskManager（任务管理器）：是真正执行任务的地方；（3）ResourceManager（资源管理器）：负责管理TaskManager上的Slot；（4）Dispatcher（分发器）：为应用提供REST接口，当应用被提交执行时，将应用移交给JobManager。"},{"id":"ai13011-pl-P5155032","type":"calc","tier":"创新","conf":"adapt","chap":"第3章","q":"某互联网公司拥有海量用户社交网络数据，需要对这些数据进行分析和处理。请回答以下问题：（1）该公司选择Hadoop作为大数据处理平台。请简述Hadoop的核心架构及其主要优势。（2）若需要对用户数据进行分布式存储，HDFS的写入流程是怎样的？（3）该公司计划对用户社交关系网络进行可视化分析，应选择什么类型的可视化工具？请说明理由。","opts":[],"ans":null,"explain":"本题综合考查Hadoop架构原理、HDFS写入流程和可视化工具选型，要求学生理解大数据处理全链路。\n（1）Hadoop的核心架构由HDFS（分布式文件系统）和Map Reduce（分布式计算框架）两部分组成。HDFS实现数据的分布式存储，Map Reduce实现分布式分析处理。Hadoop的主要优势：①可扩展性：可存储和处理Petabyte级别的数据；②经济性：使用廉价PC机组成的集群；③有效性：在不同节点上并行处理数据；④可靠性：自动维护数据多副本，自动重新部署失败任务。（2）HDFS写入流程：①客户端在向NameNode请求之前先将文件数据写入本地临时文件；②待临时文件达到块大小时向NameNode请求DataNode信息，NameNode返回数据块和对应DataNode地址列表（含副本存放地址）；③数据以流水线形式写入：第一个DataNode接收数据包并写入本地磁盘，同时向第二个DataNode传送数据，依此类推；④传送管道中的每个DataNode收到数据后向前一个DataNode发送ACK确认；⑤客户端收到数据块确认后，向NameNode发送确认，文件关闭后在HDFS中可见。（3）应选择Gephi作为可视化工具。理由：①社交网络数据属于典型的复杂网络数据，Gephi专门用于复杂网络和社交网络分析；②Gephi基于Java开发，使用OpenGL作为可视化引擎，能处理大规模节点和边；③Gephi是开源免费工具，功能强大，支持动态和分层图的交互可视化与探测；④支持探索性数据分析、链接分析和社交网络分析等高级功能。若需要前端Web展示，也可结合D3.js进行交互式网络可视化。"},{"id":"ai13011-pl-P5155104","type":"fill","tier":"拔高","conf":"adapt","chap":"第3章","q":"Hadoop是开源项目Nutch搜索引擎开发者__1__在受到Google的启发后提","opts":[],"ans":["Doug Cutting"],"explain":"Hadoop是开源项目Nutch搜索引擎开发者Doug Cutting在受到Google的启发后提出的。\n参考答案: A.Doug Cutting"},{"id":"ai13011-pl-P5155105","type":"fill","tier":"拔高","conf":"adapt","chap":"第3章","q":"Hadoop核心组件中的分布式文件系统HDFS对应Google的__1__技术。","opts":[],"ans":["GFS（Google File System）"],"explain":"HDFS对应Google的GFS（Google File System）。\n参考答案: A.GFS（Google File System）"},{"id":"ai13011-pl-P5155106","type":"fill","tier":"拔高","conf":"adapt","chap":"第3章","q":"HDFS主要由3个组件构成，分别是名字节点(NameNode)、__1__和数据节点(DataNode)。","opts":[],"ans":["第二名字节点(SecondaryNameNode)"],"explain":"HDFS主要由3个组件构成，分别是NameNode、SecondaryNameNode和DataNode。\n参考答案: A.第二名字节点(SecondaryNameNode)"},{"id":"ai13011-pl-P5155107","type":"fill","tier":"拔高","conf":"adapt","chap":"第3章","q":"在Hadoop 0.21.0版本之后，SecondaryNameNode的概念被__1__所取代。","opts":[],"ans":["CheckpointNode"],"explain":"在Hadoop 0.21.0版本之后，SecondaryNameNode的概念被CheckpointNode所取代。\n参考答案: A.CheckpointNode"},{"id":"ai13011-pl-P5155108","type":"fill","tier":"拔高","conf":"adapt","chap":"第3章","q":"Hadoop 2.0版本以后引入了__1__计算框架，核心目标是将JobTracker的资源管理和作业调度两个最主要功能进行拆分。","opts":[],"ans":["YARN"],"explain":"Hadoop 2.0版本以后引入了YARN计算框架。\n参考答案: A.YARN"},{"id":"ai13011-pl-P5155109","type":"fill","tier":"拔高","conf":"adapt","chap":"第3章","q":"在Spark生态系统中，提供机器学习功能的系统是__1__。","opts":[],"ans":["MLlib"],"explain":"MLlib是底层的分布式机器学习库，提供机器学习功能。\n参考答案: A.MLlib"},{"id":"ai13011-pl-P5155110","type":"fill","tier":"拔高","conf":"adapt","chap":"第3章","q":"Storm是由__1__公司开发的实时处理系统，后被Twitter收购并开源。","opts":[],"ans":["BackType"],"explain":"Storm是由BackType公司开发的实时处理系统。\n参考答案: A.BackType"},{"id":"ai13011-pl-P5155111","type":"fill","tier":"拔高","conf":"adapt","chap":"第3章","q":"Apache Flink起源于__1__项目，于2014年12月成为Apache软件基金会的顶级项目。","opts":[],"ans":["Stratosphere"],"explain":"Flink起源于Stratosphere项目，2014年12月成为Apache顶级项目。\n参考答案: A.Stratosphere"},{"id":"ai13011-pl-P5154745","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在机器学习中，预测目标变量$y$为离散取值的分类问题中，若类别标签只有“正”和“反”两个选项（如$y \\in \\{0,1\\}$），这类问题被称为（ ）。","opts":["A. 回归问题","B. 二分类问题","C. 多分类问题","D. 聚类问题"],"ans":1,"explain":"预测目标取值离散且仅有两个选项的问题被称为二分类问题。"},{"id":"ai13011-pl-P5154746","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"从无标记的数据中学习被称为（ ）。","opts":["A. 监督学习","B. 无监督学习","C. 半监督学习","D. 强化学习"],"ans":1,"explain":"从无标记的数据中学习被称为无监督学习。"},{"id":"ai13011-pl-P5154747","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"半监督学习依据少量带有标注的训练样本来构造初始模型，然后利用（ ）对模型进行优化。","opts":["A. 无标注的数据","B. 更多的标注数据","C. 测试集","D. 验证集"],"ans":0,"explain":"半监督学习依据少量带有标注的训练样本来构造一个初始的模型，然后利用无标注的数据对模型进行优化。"},{"id":"ai13011-pl-P5154748","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"模型对未知样本进行预测的能力被称为（ ）。","opts":["A. 拟合能力","B. 泛化能力","C. 分类能力","D. 回归能力"],"ans":1,"explain":"模型对未知样本进行预测的能力被称为“泛化”能力。"},{"id":"ai13011-pl-P5154749","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"如果模型只在训练样本上表现得很好而不能对新的数据样本做出很好的预测，则称为（ ）。","opts":["A. 欠拟合","B. 过拟合","C. 欠训练","D. 过训练"],"ans":1,"explain":"如果模型只在训练样本上表现得很好而不能对于新的数据样本做出很好的预测，则称为模型过拟合。"},{"id":"ai13011-pl-P5154750","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"训练集的选取方法中，以重复采样为基础，对包含N个样本的数据集进行有放回采样的方法是（ ）。","opts":["A. 留出法","B. 交叉验证法","C. 自助法","D. 分层采样法"],"ans":2,"explain":"自助法以重复采样为基础，对包含N个样本的数据集进行有放回的采样。"},{"id":"ai13011-pl-P5154751","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"机器学习领域著名的“奥卡姆剃刀”原理是指（ ）。","opts":["A. 模型越复杂越好","B. 如果几种假设能很好地解释已知事实，则倾向于选择简单的","C. 数据集越大越好","D. 算法运行时间越短越好"],"ans":1,"explain":"奥卡姆剃刀原理即“如无必要，勿增实体”，如果几种假设/猜想/模型能够对已知的事实进行很好的解释，则趋向于选择简单的。"},{"id":"ai13011-pl-P5154752","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"机器学习领域的no free lunch定理可描述为（ ）。","opts":["A. 存在一种算法能在所有分类问题中性能均为最优","B. 不存在能够在所有可能的分类问题中性能均为最优的算法","C. 免费算法没有午餐","D. 所有算法在所有问题上的性能都相同"],"ans":1,"explain":"no free lunch定理可描述为：不存在能够在所有可能的分类问题中性能均为最优的算法。"},{"id":"ai13011-pl-P5154753","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在几何模型中，如果存在某个线性决策面能够将两类样本分离，则称所给数据集是（ ）。","opts":["A. 线性可分的","B. 非线性可分的","C. 线性不可分的","D. 完全可分的"],"ans":0,"explain":"如果存在某个线性决策面能够将两类样本分离，则称所给数据集是线性可分的。"},{"id":"ai13011-pl-P5154754","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在概率模型中，依据已知的x对Y进行概率估计的条件概率$P(Y|x)$被称为（ ）。","opts":["A. 先验概率","B. 后验概率","C. 似然函数","D. 类条件概率"],"ans":1,"explain":"依据已知的x对Y进行概率估计的条件概率$P(Y|x)$被称为后验概率。"},{"id":"ai13011-pl-P5154755","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"关于决策树模型的结构，下列说法错误的是（ ）。","opts":["A. 根节点和内部节点通常对应样本的一个特征或属性","B. 叶子节点代表最终的决策分类结果","C. 决策树的构造需要样本集来进行训练","D. 决策树中每个内部节点可以有任意多个子节点，没有限制"],"ans":3,"explain":"决策树中每个内部节点对应一个特征的取值分支，子节点数量取决于该特征的取值个数，并非“任意多个、没有限制”。其他选项均正确。"},{"id":"ai13011-pl-P5154756","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在决策树模型中，用决策树进行分类时，从（ ）开始对实例的某一特征进行测试。","opts":["A. 叶子节点","B. 内部节点","C. 根节点","D. 任意节点"],"ans":2,"explain":"用决策树分类时，从根节点开始对实例的某一特征进行测试，根据测试结果将实例分配到其子节点。"},{"id":"ai13011-pl-P5154757","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在决策树训练中，用于衡量样本集纯度的指标是（ ）。","opts":["A. 信息增益","B. 信息熵","C. 基尼指数","D. 均方误差"],"ans":1,"explain":"信息熵用于衡量样本集的不确定性或纯度。对于二分类问题，当两类概率相等时信息熵取得最大值。"},{"id":"ai13011-pl-P5154758","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"决策树的属性划分以（ ）为准则，选择使该值最大的属性进行划分。","opts":["A. 信息熵","B. 信息增益","C. 基尼系数","D. 准确率"],"ans":1,"explain":"决策树的属性划分是以信息增益为准则的，选择信息增益最大的属性来生成树。"},{"id":"ai13011-pl-P5154759","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在决策树剪枝策略中，在决策树的生成过程中进行剪枝处理，从根节点向下判断是否过拟合的策略是（ ）。","opts":["A. 预剪枝","B. 后剪枝","C. 随机剪枝","D. 深度剪枝"],"ans":0,"explain":"预剪枝是在决策树的生成过程中进行剪枝处理，从根节点向下。"},{"id":"ai13011-pl-P5154760","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"对于连续取值的特征，在决策树中将其离散化的方法是（ ）。","opts":["A. 随机赋值","B. 计算所有可能分割点的信息增益，选取使信息增益最大的分割点","C. 直接丢弃该特征","D. 使用均值替代"],"ans":1,"explain":"对于连续取值的特征，需要确定一个分割值将连续取值分为两部分，候选值集合为相邻值的中点，选取使信息增益最大的t值作为划分标准。"},{"id":"ai13011-pl-P5154761","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"后剪枝相对于预剪枝的主要优点是（ ）。","opts":["A. 训练速度更快","B. 泛化能力通常更强","C. 不需要测试集","D. 不会出现过拟合"],"ans":1,"explain":"后剪枝通常比预剪枝保留更多的分支，欠拟合风险小，模型的“泛化”性能往往优于预剪枝。"},{"id":"ai13011-pl-P5154762","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"朴素贝叶斯分类器在计算复杂的条件概率分布时，为了简化计算而采用的核心假设是（ ）。","opts":["A. 样本空间服从均匀分布","B. 所有特征与类别标签之间存在线性相关关系","C. 对已知类别，假设所有特征相互独立","D. 训练集中的特征向量维度必须严格小于样本数量"],"ans":2,"explain":"朴素贝叶斯分类器的核心思想在于采用了属性条件独立性假设，即对已知类别，假设所有特征相互独立。"},{"id":"ai13011-pl-P5154763","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在利用朴素贝叶斯分类器估计概率时，若因训练集规模有限导致某个特征取值在某类样本中的计数为零，为了避免“零概率”现象，通常对概率估计进行（ ）。","opts":["A. 归一化处理","B. 标准化处理","C. 拉普拉斯修正","D. 正则化处理"],"ans":2,"explain":"当训练集大小有限导致子集为空时，概率估计值为0，会导致整体预测结果直接被置零。为了避免这一问题，通常使用拉普拉斯修正方法。"},{"id":"ai13011-pl-P5154764","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"线性回归在估计参数时，通常采用（ ），即通过最小化预测值与真实值之间的差距来求解参数。","opts":["A. 极大似然估计","B. 最小二乘法","C. 梯度上升法","D. 贝叶斯估计"],"ans":1,"explain":"线性回归采用最小二乘法估计参数，通过最小化均方误差来求解。"},{"id":"ai13011-pl-P5154765","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在线性回归模型的矩阵求解过程中，当矩阵$X^TX$为奇异矩阵时，为解决这一问题并防止模型过拟合，常用的处理方法是（ ）。","opts":["A. 减少训练集中的样本数量","B. 将连续数值特征全部离散化","C. 在损失函数中引入正则化项","D. 放弃参数化拟合，改用非监督聚类算法"],"ans":2,"explain":"当$X^TX$为奇异矩阵时，矩阵不可逆，直接求解会导致存在多个解。通过在均方误差损失函数中加入正则化项，可以保证方程拥有唯一解。"},{"id":"ai13011-pl-P5154766","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"关于二分类逻辑斯蒂回归的模型特点，下列说法错误的是（ ）。","opts":["A. 逻辑斯蒂回归虽然名称中包含“回归”，但本质上是一种分类算法","B. 逻辑斯蒂回归采用对率函数(Sigmoid)作为激活函数","C. 逻辑斯蒂回归模型要求样本特征必须严格服从高斯分布","D. 逻辑斯蒂回归直接对分类的可能性进行建模，无须事先假设数据分布"],"ans":2,"explain":"逻辑斯蒂回归的优点之一是直接对分类的可能性进行建模，无须事先假设数据分布，从而避免了假设分布不准确所带来的问题。因此选项C说法错误。"},{"id":"ai13011-pl-P5154767","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在逻辑斯蒂回归模型的参数优化过程中，每条记录都更新参数的优化方法是（ ）。","opts":["A. 批量梯度下降(BGD)","B. 随机梯度下降(SGD)","C. 牛顿法","D. 拟牛顿法"],"ans":1,"explain":"每计算一个记录的代价就更新参数值称为随机梯度下降(SGD)，是一种在线学习方法。"},{"id":"ai13011-pl-P5154768","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"Softmax分类器是二分类逻辑斯蒂回归在（ ）上的推广。","opts":["A. 二分类任务","B. 多分类任务","C. 回归任务","D. 聚类任务"],"ans":1,"explain":"二分类逻辑斯蒂回归可以推广到多分类逻辑斯蒂回归，这就是softmax分类器。"},{"id":"ai13011-pl-P5154769","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"逻辑斯蒂回归和softmax回归虽然被称为“回归”，但实际上是一种（ ）。","opts":["A. 聚类学习方法","B. 分类学习方法","C. 降维方法","D. 回归方法"],"ans":1,"explain":"逻辑斯蒂回归和softmax回归虽然被称为“回归”，但它实际上是一种分类学习方法。"},{"id":"ai13011-pl-P5154770","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"支持向量机中用距离分类超平面的距离来代表（ ）。","opts":["A. 分类错误率","B. 确信度","C. 计算复杂度","D. 模型复杂度"],"ans":1,"explain":"支持向量机是用距离分类超平面的距离来代表“确信度”。"},{"id":"ai13011-pl-P5154771","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在软间隔支持向量机中，惩罚系数$C$较大时（ ）。","opts":["A. 模型将强行要求所有样本点必须严格线性可分","B. 模型对误分类点的惩罚变重，会优先使误分类点个数减小，导致分类间隔缩小","C. 模型倾向于拉大分类间隔，容忍更多的误分类点","D. 惩罚系数对分类间隔和误分类点无影响"],"ans":1,"explain":"当C较大时，模型对松弛变量$\\xi_i$（误分类点）的惩罚加大，将优先保证误分类点个数减小，代价是分类间隔会相应缩小。"},{"id":"ai13011-pl-P5154772","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"线性支持向量机通过对偶问题求解后，最终的模型决策仅依赖于拉格朗日乘子$\\alpha_i &gt; 0$所对应的样本点，这些样本点被称为（ ）。","opts":["A. 核心点","B. 支持向量","C. 边界点","D. 噪声点"],"ans":1,"explain":"$\\alpha_i &gt; 0$的样本为支持向量，模型只依赖于支持向量。"},{"id":"ai13011-pl-P5154773","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"高斯核函数能将输入空间映射到（ ）维的特征空间。","opts":["A. 有限维","B. 无穷维","C. 一维","D. 二维"],"ans":1,"explain":"高斯核能将输入空间映射到无穷维的特征空间。"},{"id":"ai13011-pl-P5154774","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在利用支持向量机解决$k$分类问题时，若采用“投票法”（一对一），共需要训练（ ）个二分类SVM模型。","opts":["A. $k$","B. $k 1$","C. $\\frac{k(k 1)}{2}$","D. $2^k$"],"ans":2,"explain":"对于k分类问题，两两类别训练一个支持向量机模型，共需要$\\frac{k(k 1)}{2}$个模型。"},{"id":"ai13011-pl-P5154775","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"Python的sklearn库中，用于支持向量机分类的类是（ ）。","opts":["A. sklearn.svm.SVR","B. sklearn.svm.SVC","C. sklearn.svm.LinearSVR","D. sklearn.svm.NuSVR"],"ans":1,"explain":"sklearn.svm.SVC用于分类，而sklearn.svm.SVR用于回归。"},{"id":"ai13011-pl-P5154776","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"关于集成学习的基本概念与核心假设，下列说法错误的是（ ）。","opts":["A. 若集成模型中的所有个体学习器都是同一种类型，称为“同质”集成","B. Boosting算法的个体学习器之间存在强依赖关系，必须串行生成","C. 当个体学习器的预测准确率低于0.5时，随着集成个体数量增加，整体模型的预测准确率会稳步提升","D. Bagging的个体学习器之间不存在强依赖关系，可以并行化实现"],"ans":2,"explain":"集成学习发挥作用有两个关键前提：个体学习器误差相互独立，且性能优于随机猜测（准确率大于0.5）。当个体学习器准确率低于0.5时，随着数量增加，整体预测准确率反而下降。"},{"id":"ai13011-pl-P5154777","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"Adaboost算法中，提高被前一轮分类器错误分类样本的权值，降低正确分类样本的权值，这种做法使得（ ）。","opts":["A. 简单易分的样本在后一个分类器中获得更多关注","B. 比较难分且容易出错的样本在后一个分类器中获得更多关注","C. 所有样本的权值保持不变","D. 错误分类样本被完全忽略"],"ans":1,"explain":"Adaboost的做法是提高被前一轮分类器错误分类样本的权值，降低正确分类样本的权值，使比较难分且容易出错的样本在后一个分类器中被赋予更多的关注。"},{"id":"ai13011-pl-P5154778","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在Adaboost算法中，基分类器的系数$\\alpha_m$的计算公式为（ ）。","opts":["A. $\\alpha_m = \\frac{1}{2}\\log\\frac{1 e_m}{e_m}$","B. $\\alpha_m = \\frac{1}{2}\\log\\frac{e_m}{1 e_m}$","C. $\\alpha_m = e_m$","D. $\\alpha_m = 1 e_m$"],"ans":0,"explain":"教材给出的Adaboost基分类器系数计算公式为$\\alpha_m = \\frac{1}{2}\\log\\frac{1 e_m}{e_m}$。"},{"id":"ai13011-pl-P5154779","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"随机森林算法中，从n个特征中选择k个(k&lt;&lt;n)进行学习，这种做法称为（ ）。","opts":["A. 行采样","B. 列采样（特征随机采样）","C. 完全分裂","D. 剪枝"],"ans":1,"explain":"随机森林不仅要进行行采样（样本采样），还要进行列采样，即进行特征的随机采样，从n个特征中选择k个。"},{"id":"ai13011-pl-P5154780","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"随机森林算法中，每一轮有放回的行采样，将有（ ）的数据样本被选中。","opts":["A. 50%","B. 63.2%","C. 80%","D. 100%"],"ans":1,"explain":"每一轮有放回的行采样，将有63.2%的数据样本被选中。"},{"id":"ai13011-pl-P5154781","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"以下哪个不是随机森林算法的优点？","opts":["A. 在数据集上表现良好，很难过拟合","B. 能够处理很高维度的数据，不用做特征选择","C. 每个基学习器特征较多，模型非常复杂","D. 可并行化实现，训练速度快"],"ans":2,"explain":"随机森林的优点包括：表现良好难过拟合、能处理高维数据、可分析特征重要性、可并行化训练速度快。随机森林每个基学习器特征较少，而不是较多。"},{"id":"ai13011-pl-P5154782","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在Stacking集成学习框架中，用于组合个体学习器输出结果的模型被称为（ ）。","opts":["A. 初级学习器","B. 次级学习器","C. 基学习器","D. 弱学习器"],"ans":1,"explain":"个体学习器被称为初级学习器，把用于组合初级学习器的模型称为次级学习器。"},{"id":"ai13011-pl-P5154783","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"为缓解Stacking容易发生的过拟合问题，通常采用（ ）来生成次级学习器的训练数据。","opts":["A. 留出法","B. 自助法","C. 交叉验证法","D. 随机采样法"],"ans":2,"explain":"为缓解过拟合，常用交叉验证法产生次级学习器的训练数据。"},{"id":"ai13011-pl-P5154784","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"1943年，McCulloch和Pitts提出的MP神经元模型是根据（ ）提炼出来的简化数学模型。","opts":["A. 计算机逻辑门","B. 生物神经元","C. 遗传算法","D. 模糊系统"],"ans":1,"explain":"1943年McCulloch和Pitts将生物神经元模型抽象为人工神经元模型，即MP神经元模型。"},{"id":"ai13011-pl-P5154785","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在人工神经元中，神经元的输出$y$可表示为（ ）。","opts":["A. $y = \\sum_{i=1}^{n}w_i x_i \\theta$","B. $y = f(\\sum_{i=1}^{n}w_i x_i \\theta)$","C. $y = \\sum_{i=1}^{n}w_i x_i + \\theta$","D. $y = f(\\sum_{i=1}^{n}w_i x_i + \\theta)$"],"ans":1,"explain":"神经元输出为$y = f(\\sum_{i=1}^{n}w_i x_i \\theta)$，其中$f(.)$为激活函数，$\\theta$为阈值。"},{"id":"ai13011-pl-P5154786","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"感知机是一个具有（ ）计算单元的人工神经网络。","opts":["A. 单层","B. 两层","C. 三层","D. 多层"],"ans":0,"explain":"感知机是一个具有单层计算单元的人工神经网络。"},{"id":"ai13011-pl-P5154787","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"根据感知机收敛性定理，若训练样本是（ ），则感知器训练算法在有限次迭代后可以收敛到正确的解向量。","opts":["A. 线性可分的","B. 线性不可分的","C. 非线性可分的","D. 任意分布的"],"ans":0,"explain":"感知机模型的收敛性定理为：若训练样本是线性可分的，则感知器训练算法在有限次迭代后可以收敛到正确的解向量。"},{"id":"ai13011-pl-P5154788","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"BP神经网络中，误差反向传播过程的目的是（ ）。","opts":["A. 将样本数据从输入层传到输出层","B. 计算各单元的误差并修正前一层的权值","C. 初始化网络参数","D. 停止网络训练"],"ans":1,"explain":"BP算法的反向阶段是计算各输出单元的误差，并逐层向前计算各隐层单元的误差，并采用此误差来修正前一层的权值。"},{"id":"ai13011-pl-P5154789","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"BP神经网络在参数更新时，控制算法每一轮迭代更新步长的参数是（ ）。","opts":["A. 学习率$\\eta$","B. 正则化系数$\\lambda$","C. 隐藏层神经元数量","D. 迭代次数"],"ans":0,"explain":"$\\eta \\in (0,1)$为学习率，控制算法每一轮迭代的更新步长。"},{"id":"ai13011-pl-P5154790","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在BP神经网络中，可以采用（ ）或（ ）的方法来缓解过拟合现象。","opts":["A. 早停；正则化","B. 增加隐藏层；增加训练数据","C. 减少输入特征；增加迭代次数","D. 随机初始化；批量梯度下降"],"ans":0,"explain":"过拟合问题是BP网络不可忽视的一个问题，可以采用“早停”或“正则化”的方法来缓解过拟合现象。"},{"id":"ai13011-pl-P5154791","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"Sklearn中用于多层神经网络分类操作的类是（ ）。","opts":["A. sklearn.neural_network.MLPRegressor","B. sklearn.neural_network.MLPClassifier","C. sklearn.linear_model.LogisticRegression","D. sklearn.svm.SVC"],"ans":1,"explain":"sklearn.neural_network.MLPClassifier可以进行多层神经网络分类操作。"},{"id":"ai13011-pl-P5154792","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"聚类算法属于（ ）的代表算法。","opts":["A. 监督学习","B. 非监督学习","C. 半监督学习","D. 强化学习"],"ans":1,"explain":"聚类算法是非监督学习的代表算法。"},{"id":"ai13011-pl-P5154793","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"对于聚类结果而言，同一簇内记录的相似度应尽量（ ），不同簇内记录的相似度应尽量（ ）。","opts":["A. 高；高","B. 高；低","C. 低；高","D. 低；低"],"ans":1,"explain":"簇内相似度是指同一簇内记录的相似度应尽量高；簇间相似度是指不同簇内记录的相似度尽量低。"},{"id":"ai13011-pl-P5154794","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"对于两个n维数据点，各维度坐标差的绝对值之和被称为（ ）。","opts":["A. 欧几里得距离","B. 曼哈顿距离","C. 切比雪夫距离","D. 马氏距离"],"ans":1,"explain":"曼哈顿距离的计算公式为$\\sum_{k=1}^{n}|x_i^k x_j^k|$，即各维度坐标差的绝对值之和。"},{"id":"ai13011-pl-P5154795","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"Kmeans聚类算法中，以下哪个不是该算法的缺点？","opts":["A. 必须事先给出要生成的类的数目k","B. 对初值敏感，不同初始值可能导致不同聚类结果","C. 对“噪声”和孤立点数据敏感","D. 算法框架复杂，难以理解"],"ans":3,"explain":"Kmeans算法的优点包括算法框架清晰、简单、容易理解。因此D项“算法框架复杂，难以理解”不是Kmeans的缺点。"},{"id":"ai13011-pl-P5154796","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"Kmeans算法中，目标是最小化（ ）。","opts":["A. 簇间距离","B. 平均误差准则函数J","C. 簇内样本数量","D. 迭代次数"],"ans":1,"explain":"kmeans算法以最小化“平均误差准则函数J”为目标。"},{"id":"ai13011-pl-P5154797","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"DBSCAN算法中，如果一个对象的ε邻域至少包含最小数目MinPts个对象，则称该对象为（ ）。","opts":["A. 边界点","B. 核心对象","C. 噪声点","D. 离群点"],"ans":1,"explain":"核心对象是指如果一个对象的ε邻域至少包含最小数目MinPts个对象，则称该对象为核心对象。"},{"id":"ai13011-pl-P5154798","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"DBSCAN算法中，既不是核心对象也不是边界点的对象被称为（ ）。","opts":["A. 核心对象","B. 边界点","C. 噪声点","D. 密度可达点"],"ans":2,"explain":"噪声点是除核心对象和边界点之外的点。"},{"id":"ai13011-pl-P5154799","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"层次聚类最大的优点是（ ）。","opts":["A. 计算量小","B. 一次性地得到整个聚类的过程，改变cluster数目不需要再次计算数据点的归属","C. 总能得到全局最优解","D. 对噪声不敏感"],"ans":1,"explain":"层次聚类最大的优点是一次性地得到了整个聚类的过程，要分多少个cluster都可以直接根据树结构来得到结果，改变cluster数目不需要再次计算数据点的归属。"},{"id":"ai13011-pl-P5154800","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"Sklearn中用于Kmeans聚类的类是（ ）。","opts":["A. sklearn.cluster.DBSCAN","B. sklearn.cluster.KMeans","C. sklearn.cluster.AffinityPropagation","D. sklearn.cluster.SpectralClustering"],"ans":1,"explain":"sklearn.cluster.KMeans可以用来进行kmeans聚类。"},{"id":"ai13011-pl-P5154801","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"高维情况下出现的数据样本稀疏、距离计算困难等问题，被称为（ ）。","opts":["A. 过拟合","B. 欠拟合","C. 维数灾难","D. 维度爆炸"],"ans":2,"explain":"高维情况下出现的数据样本稀疏、距离计算困难等问题，是所有机器学习方法共同面临的，被称为“维数灾难”。"},{"id":"ai13011-pl-P5154802","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"主成分分析(PCA)是一种（ ）的线性降维方法。","opts":["A. 监督","B. 非监督","C. 半监督","D. 强化"],"ans":1,"explain":"PCA是一种非监督线性的降维方法，它基于重构的思想对数据进行降维。"},{"id":"ai13011-pl-P5154803","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"线性判别分析(LDA)是一种（ ）的线性降维方法。","opts":["A. 监督","B. 非监督","C. 半监督","D. 强化"],"ans":0,"explain":"LDA是一种监督线性的降维方法，它基于分类的思想对数据进行降维。"},{"id":"ai13011-pl-P5154804","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"PCA和LDA的优化求解过程均可归结为（ ）的计算问题。","opts":["A. 特征值与特征向量","B. 均值与方差","C. 协方差与相关系数","D. 信息增益与信息熵"],"ans":0,"explain":"PCA和LDA均可归结为求解特征值和特征向量的问题，实现简单且无须迭代即可达到全局最优解。"},{"id":"ai13011-pl-P5154805","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在特征选择中，先对数据集进行特征选择，再训练学习器的方法称为（ ）。","opts":["A. 过滤式","B. 包裹式","C. 嵌入式","D. 混合式"],"ans":0,"explain":"过滤式方法先对数据集进行特征选择，再训练学习器，不需要考虑后续学习器的选择。"},{"id":"ai13011-pl-P5154806","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"特征选择中，直接将最终将要使用的学习器性能作为特征子集的评价准则的方法称为（ ）。","opts":["A. 过滤式","B. 包裹式","C. 嵌入式","D. 混合式"],"ans":1,"explain":"包裹式特征选择直接把最终将要使用的学习器性能作为特征子集的评价准则。"},{"id":"ai13011-pl-P5154807","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"Sklearn中用于PCA降维的类是（ ）。","opts":["A. sklearn.decomposition.PCA","B. sklearn.decomposition.KernelPCA","C. sklearn.feature_selection.SelectKBest","D. sklearn.manifold.TSNE"],"ans":0,"explain":"sklearn.decomposition.PCA可以用来进行PCA降维。"},{"id":"ai13011-pl-P5154906","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"特征向量$X=(x^1,x^2,...,x^n)$中，$n$称为（ ）。","opts":["A. 特征数量","B. 特征向量的维度","C. 样本数量","D. 类别数量"],"ans":1,"explain":"$X=(x^1,x^2,...,x^n)$表示含有$n$个特征的特征向量，其中$n$称为特征向量的维度。"},{"id":"ai13011-pl-P5154907","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"如果模型在训练集和测试集上的预测性能均较差，这种现象被称为（ ）。","opts":["A. 过拟合","B. 欠拟合","C. 欠训练","D. 过训练"],"ans":1,"explain":"欠拟合是由于数据集太小导致模型不能预测整个样本空间，在训练集和测试集上表现均较差。"},{"id":"ai13011-pl-P5154908","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在概率模型中，$P(x|Y)$被称为（ ）。","opts":["A. 先验概率","B. 后验概率","C. 似然函数","D. 边缘概率"],"ans":2,"explain":"条件概率$P(x|Y)$被称为似然函数（或者叫作类条件概率）。"},{"id":"ai13011-pl-P5154909","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在决策树训练中，对于连续取值的特征，划分点$t$的选取准则是（ ）。","opts":["A. $t = \\arg\\max_t G(D, C, t)$","B. $t = \\arg\\min_t G(D, C, t)$","C. $t = \\arg\\max_t E(D)$","D. $t = \\arg\\min_t E(D)$"],"ans":0,"explain":"分割值$t$的选取要使信息增益$G(D,C,t)$最大，即$t = \\arg\\max_{t \\in T} G(D,C,t)$。"},{"id":"ai13011-pl-P5154910","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在朴素贝叶斯分类器中，对于连续特征，通常假设其条件概率服从（ ）。","opts":["A. 均匀分布","B. 高斯分布","C. 泊松分布","D. 指数分布"],"ans":1,"explain":"对于连续特征，假定$P(X^j=x^j|Y=c_i) \\sim N(\\mu_{c_i,j}, \\sigma^2_{c_i,j})$服从高斯分布。"},{"id":"ai13011-pl-P5154911","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"线性回归中，当矩阵$XX^T$为奇异矩阵时，引入正则化项$\\lambda\\|\\tilde{w}\\|^2$的作用是（ ）。","opts":["A. 降低模型复杂度","B. 使方程有唯一解","C. 提高模型精度","D. 减少训练时间"],"ans":1,"explain":"当$XX^T$是奇异矩阵时，可以得出多个解。引入正则化项后，只需要调整系数$\\lambda$，必能让式(443)有唯一解。"},{"id":"ai13011-pl-P5154912","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"逻辑斯蒂回归中，对率概率函数$g(x)=1/(1+e^{x})$的值域为（ ）。","opts":["A. $[1, 1]$","B. $(0, 1)$","C. $[0, 1]$","D. $(\\infty, +\\infty)$"],"ans":1,"explain":"对率概率函数的自变量在实数R范围内，因变量在区间(0,1)内。"},{"id":"ai13011-pl-P5154913","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"支持向量机中，对于线性不可分的数据，引入松弛变量$\\xi_i$的作用是（ ）。","opts":["A. 增加模型复杂度","B. 反映对不可分点的妥协代价","C. 减少训练时间","D. 增加分类间隔"],"ans":1,"explain":"$\\xi_i$为松弛变量，反映的是对不可分点的妥协代价。"},{"id":"ai13011-pl-P5154914","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"核方法的关键思想是（ ）。","opts":["A. 将数据从高维空间映射到低维空间","B. 将低维空间中线性不可分的样本点映射到高维空间使其线性可分","C. 减少数据维度","D. 增加数据样本数量"],"ans":1,"explain":"核技巧的关键是等价地把一些在低维空间中线性不可分的样本点映射到特定高维空间，这样，样本点变得几乎线性可分。"},{"id":"ai13011-pl-P5154915","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"集成学习中，个体学习器的误差相互独立是集成学习的（ ）。","opts":["A. 充分条件","B. 必要条件","C. 关键假设之一","D. 次要条件"],"ans":2,"explain":"集成学习有一个关键假设——各个体学习器的误差相互独立。"},{"id":"ai13011-pl-P5154916","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"GBDT（梯度提升决策树）中，当损失函数是平方误差时，每一步需要拟合的是（ ）。","opts":["A. 真实值","B. 预测值","C. 当前模型的残差","D. 梯度值"],"ans":2,"explain":"对回归问题的GBDT算法而言，只需要简单地拟合当前模型的残差。"},{"id":"ai13011-pl-P5154917","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"BP神经网络中，隐藏层神经元的激活函数通常使用（ ）。","opts":["A. 线性函数","B. 阈值函数","C. sigmoid函数","D. 阶跃函数"],"ans":2,"explain":"各个神经元的激活函数均为sigmoid函数。"},{"id":"ai13011-pl-P5154918","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"在DBSCAN密度聚类中，如果一个对象的ε邻域内包含的核心对象数量不足MinPts，但该对象在某个核心对象的ε邻域内，则该对象被称为（ ）。","opts":["A. 核心对象","B. 边界点","C. 噪声点","D. 离群点"],"ans":1,"explain":"如果一个对象是非核心对象，但它的邻域中有核心对象，则称该对象为边界点。"},{"id":"ai13011-pl-P5154919","type":"sc","tier":"基础","conf":"adapt","chap":"第4章","q":"关于特征选择中的包裹式(Wrapper)方法，以下说法正确的是（ ）。","opts":["A. 特征选择过程独立于后续学习器","B. 直接将最终将要使用的学习器性能作为特征子集的评价准则","C. 计算开销比过滤式小","D. 将特征选择过程和机器训练过程融为一体"],"ans":1,"explain":"包裹式特征选择直接把最终将要使用的学习器性能作为特征子集的评价准则，其开销比过滤式大，但最终学习器性能更好。"},{"id":"ai13011-pl-P5154984","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于机器学习中基本概念的描述，正确的有（ ）。","opts":["A. 数据集中的每个样本包含属性或特征","B. 特征向量用$X=(x^1,x^2,...,x^n)$表示","C. 输出取值离散的问题被称为分类问题","D. 输出取值连续的问题被称为回归问题"],"ans":[0,1,2,3],"explain":"A项正确：数据集中每部手机都有品牌、屏幕尺寸等属性或特征。B项正确：特征向量用$X=(x^1,x^2,...,x^n)$表示。C项正确：输出取值离散的问题被称为分类问题。D项正确：输出取值连续的问题被称为回归问题。"},{"id":"ai13011-pl-P5154985","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下属于机器学习学习方式的有（ ）。","opts":["A. 监督学习","B. 无监督学习","C. 半监督学习","D. 强化学习"],"ans":[0,1,2],"explain":"监督学习、无监督学习和半监督学习是机器学习的主要学习方式。强化学习在后续章节单独介绍，本节主要讨论前三种。但根据教材内容，A、B、C均正确。"},{"id":"ai13011-pl-P5154986","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于训练集选取方法的描述，正确的有（ ）。","opts":["A. 留出法是从数据集中划分一部分出来作为测试集","B. 交叉验证法将数据随机均分为多份，轮流作为测试集","C. 自助法以重复采样为基础，进行有放回的采样","D. 自助法在数据集较小时效果很好"],"ans":[0,1,2,3],"explain":"A项正确：留出法是从数据集中划分一部分出来作为测试集。B项正确：交叉验证法将数据随机均分为多份，轮流作为测试集。C项正确：自助法以重复采样为基础，进行有放回的采样。D项正确：自助法在数据集较小、难以有效划分训练/测试集时效果很好。"},{"id":"ai13011-pl-P5154987","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于过拟合和欠拟合的描述，正确的有（ ）。","opts":["A. 过拟合是指模型只在训练样本上表现很好，但对新数据预测效果差","B. 欠拟合是指模型在训练集和测试集上的预测性能均较差","C. 过拟合是把训练集的某些特殊的特征当成了样本空间的特征","D. 欠拟合是由于数据集太小导致模型不能预测整个样本空间"],"ans":[0,1,2,3],"explain":"A项正确：过拟合是模型只在训练样本上表现得很好而不能对新的数据样本做出很好的预测。B项正确：欠拟合是由于数据集太小导致模型不能预测整个样本空间。C项正确：过拟合把训练集的某些特殊的特征当成了训练集所在的样本空间的特征。D项正确：欠拟合是由于数据集太小导致模型不能预测整个样本空间。"},{"id":"ai13011-pl-P5154988","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下属于机器学习几何模型相关概念的有（ ）。","opts":["A. 线性可分","B. 超平面","C. 核方法","D. 贝叶斯公式"],"ans":[0,1,2],"explain":"几何模型相关概念包括线性可分、超平面、核方法等。贝叶斯公式属于概率模型的内容，不属于几何模型。"},{"id":"ai13011-pl-P5154989","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于决策树模型的描述，正确的有（ ）。","opts":["A. 决策树由节点和有向边组成","B. 根节点和内部节点表示一个特征或属性","C. 叶子节点代表一个划分的类，即决策结果","D. 决策树的构造需要样本集来进行训练"],"ans":[0,1,2,3],"explain":"A项正确：决策树由节点和有向边组成。B项正确：根节点和内部节点表示一个特征或属性。C项正确：叶子节点代表一个划分的类，即决策结果。D项正确：机器学习需要样本集来进行训练，决策树的构造离不开样本集。"},{"id":"ai13011-pl-P5154990","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于决策树训练中信息增益的描述，正确的有（ ）。","opts":["A. 决策树的属性划分是以信息增益为准则的","B. 信息增益越大，说明该属性对分类越有用","C. 信息增益的计算基于信息熵","D. 连续取值的特征需要离散化后才能计算信息增益"],"ans":[0,1,2,3],"explain":"A项正确：决策树的属性划分是以信息增益为准则的。B项正确：选择信息增益最大的属性来生成树，说明信息增益越大越有用。C项正确：信息增益的计算基于信息熵。D项正确：连续取值的特征需要确定分割值转变为离散特征。"},{"id":"ai13011-pl-P5154991","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于决策树剪枝策略的描述，正确的有（ ）。","opts":["A. 预剪枝是在决策树的生成过程中进行剪枝处理","B. 后剪枝是在一棵树生成以后再从叶子节点开始逐步考察","C. 后剪枝的训练时间开销通常比预剪枝大","D. 预剪枝的泛化能力通常强于后剪枝"],"ans":[0,1,2],"explain":"A项正确：预剪枝是在决策树的生成过程中进行剪枝处理。B项正确：后剪枝是在一棵树生成以后再从叶子节点开始逐步考察。C项正确：后剪枝需要先全部计算出节点，在分支庞大时很费时，时间开销大。D项错误：后剪枝的泛化能力通常强于预剪枝。"},{"id":"ai13011-pl-P5154992","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于朴素贝叶斯分类器的描述，正确的有（ ）。","opts":["A. 朴素贝叶斯分类器采用特征条件独立性假设","B. 条件独立假设使朴素贝叶斯方法变得简单，在数据较少的情况下很有效","C. 在现实任务中所有特征相互独立的假设很难成立","D. 拉普拉斯修正可以避免概率估计值为零的情况"],"ans":[0,1,2,3],"explain":"A项正确：朴素贝叶斯分类器采用特征条件独立性假设。B项正确：条件独立假设使朴素贝叶斯方法变得简单，在数据较少的情况下很有效。C项正确：在现实任务中所有特征相互独立的假设很难成立。D项正确：拉普拉斯修正可以避免计算结果为0的情况。"},{"id":"ai13011-pl-P5154993","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于线性回归的描述，正确的有（ ）。","opts":["A. 线性回归的任务是通过训练集来学习得到参数$w$和$c$","B. 线性回归使用最小二乘法来估计参数","C. 均方误差适合描述多个样本预测情况的好坏","D. 当矩阵$XX^T$为奇异矩阵时，可以引入正则化项解决"],"ans":[0,1,2,3],"explain":"A项正确：线性回归的任务就是通过训练集来学习得到参数$w$和$c$。B项正确：线性回归使用最小二乘法来估计参数。C项正确：均方误差适合描述多个样本预测情况的好坏。D项正确：当$XX^T$为奇异矩阵时，引入正则化项可以使方程有唯一解。"},{"id":"ai13011-pl-P5154994","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于逻辑斯蒂回归的描述，正确的有（ ）。","opts":["A. 逻辑斯蒂回归是一种分类学习方法","B. 逻辑斯蒂回归直接对分类的可能性进行建模，无须事先假设数据分布","C. 对率概率函数是一种典型的sigmoid函数","D. 逻辑斯蒂回归的代价函数是凸函数"],"ans":[0,1,2,3],"explain":"A项正确：逻辑斯蒂回归是一种分类学习方法。B项正确：逻辑斯蒂回归直接对分类的可能性进行建模，无须事先假设数据分布。C项正确：对率概率函数是一种典型的sigmoid函数。D项正确：二项逻辑斯蒂回归的代价函数是凸函数。"},{"id":"ai13011-pl-P5154995","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于逻辑斯蒂回归训练的描述，正确的有（ ）。","opts":["A. 可以使用极大似然估计法估计模型参数","B. 梯度下降法可用于求解逻辑斯蒂回归的参数","C. 在使用逻辑斯蒂回归前需要对数据的每一个特征进行归一化","D. 逻辑斯蒂回归的代价函数是交叉熵的一种特例"],"ans":[0,1,2,3],"explain":"A项正确：二分类逻辑斯蒂回归可以应用极大似然估计法估计模型参数。B项正确：梯度下降法、牛顿法、拟牛顿法等方法可用于求解。C项正确：使用逻辑斯蒂回归前必须对数据的每一个特征进行归一化。D项正确：二分类的逻辑斯蒂回归的代价函数是交叉熵的一种特例。"},{"id":"ai13011-pl-P5154996","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于支持向量机的描述，正确的有（ ）。","opts":["A. 支持向量机用距离分类超平面的距离来代表确信度","B. 支持向量机的目标是使分类间隔最大","C. 线性可分支持向量机中，支持向量是距离分类超平面最近的样本","D. 支持向量到超平面之间是“空的”"],"ans":[0,1,2,3],"explain":"A项正确：支持向量机是用距离分类超平面的距离来代表“确信度”。B项正确：最优分类线要求分类线不但能将两类正确分开，而且使分类间隔最大。C项正确：支持向量是距离分类超平面最近的样本。D项正确：支持向量到超平面之间是“空的”。"},{"id":"ai13011-pl-P5154997","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于支持向量机核函数的描述，正确的有（ ）。","opts":["A. 多项式核在线性核的情况下(d=0,p=1)等同于线性核","B. 高斯核能将输入空间映射到无穷维的特征空间","C. 高斯核是使用最广泛的核函数之一","D. 核函数选择是支持向量机的最大变数"],"ans":[0,1,2,3],"explain":"A项正确：不引入核函数的情况实际上是多项式核的一个特例(d=0,p=1)，又称为线性核。B项正确：高斯核能将输入空间映射到无穷维的特征空间。C项正确：高斯核是使用最广泛的核函数之一。D项正确：核函数选择是支持向量机的最大变数。"},{"id":"ai13011-pl-P5154998","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于集成学习基础概念的描述，正确的有（ ）。","opts":["A. Boosting的个体学习器之间存在强依赖关系","B. Bagging的个体学习器之间不存在强依赖关系，可以并行化实现","C. Stacking是分层结构，由初级学习器和次级学习器组成","D. 集成学习的关键假设是各个体学习器的误差相互独立"],"ans":[0,1,2,3],"explain":"A项正确：Boosting的个体学习器之间存在强依赖关系，必须串行生成。B项正确：Bagging的个体学习器之间不存在强依赖关系，可以并行化实现。C项正确：Stacking是分层结构，由初级学习器和次级学习器组成。D项正确：集成学习有一个关键假设——各个体学习器的误差相互独立。"},{"id":"ai13011-pl-P5154999","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于Adaboost算法的描述，正确的有（ ）。","opts":["A. Adaboost适用于二分类的情形","B. Adaboost提高被前一轮分类器错误分类样本的权值","C. Adaboost的损失函数是指数损失函数","D. Adaboost是典型的加法模型"],"ans":[0,1,2,3],"explain":"A项正确：Adaboost适用于二分类的情形。B项正确：Adaboost提高被前一轮分类器错误分类样本的权值。C项正确：Adaboost的损失函数是指数损失函数。D项正确：Adaboost是一种典型的加法模型。"},{"id":"ai13011-pl-P5155000","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于随机森林算法的描述，正确的有（ ）。","opts":["A. 随机森林是一种典型的Bagging算法","B. 随机森林采用行采样和列采样两种随机采样方式","C. 随机森林的每一棵决策树之间是没有关联的","D. 随机森林可并行化实现，训练速度快"],"ans":[0,1,2,3],"explain":"A项正确：随机森林算法是一种典型的Bagging算法。B项正确：随机森林采用行采样和列采样两种随机采样方式。C项正确：随机森林中每一棵决策树之间是没有关联的。D项正确：随机森林可并行化实现，训练速度快。"},{"id":"ai13011-pl-P5155001","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于神经网络的描述，正确的有（ ）。","opts":["A. 1943年McCulloch和Pitts提出了人工神经元M-P数学模型","B. 1957年Rosenblatt提出了感知机模型","C. 1986年Rumelhart提出了BP算法","D. 感知机是一个具有单层计算单元的人工神经网络"],"ans":[0,1,2,3],"explain":"A项正确：1943年McCulloch和Pitts提出M-P数学模型。B项正确：1957年Rosenblatt提出感知机模型。C项正确：1986年Rumelhart提出BP算法。D项正确：感知机是一个具有单层计算单元的人工神经网络。"},{"id":"ai13011-pl-P5155002","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下属于常用神经元激活函数的有（ ）。","opts":["A. 线性型函数","B. 阈值型函数","C. Sigmoid函数","D. ReLu函数"],"ans":[0,1,2,3],"explain":"教材列举的常用激活函数包括：线性型函数、阈值型函数、Sigmoid函数、Tan函数、ReLu函数。A、B、C、D均正确。"},{"id":"ai13011-pl-P5155003","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于感知机的描述，正确的有（ ）。","opts":["A. 感知机是一种二分类的线性分类模型","B. 感知机是神经网络和支持向量机的基础","C. 感知机学习的目标是找到一个将训练集正负实例点完全正确分开的分离超平面","D. 若训练样本是线性可分的，感知机训练算法在有限次迭代后可以收敛"],"ans":[0,1,2,3],"explain":"A项正确：感知机是一种二分类的线性分类模型。B项正确：感知机是神经网络和支持向量机的基础。C项正确：感知机学习的目标是找到一个将训练集正负实例点完全正确分开的分离超平面。D项正确：若训练样本是线性可分的，感知机训练算法在有限次迭代后可以收敛。"},{"id":"ai13011-pl-P5155004","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于BP神经网络的描述，正确的有（ ）。","opts":["A. BP神经网络在感知机的基础上加入了一个隐藏层","B. BP神经网络的学习过程由信息的正向传播和误差的反向传播组成","C. BP算法分为正向阶段和反向阶段","D. 过拟合是BP网络不可忽视的问题"],"ans":[0,1,2,3],"explain":"A项正确：BP神经网络在感知机的基础上加入了一个隐藏层。B项正确：BP神经网络的学习过程由信息的正向传播和误差的反向传播组成。C项正确：BP算法分为正向阶段和反向阶段。D项正确：过拟合问题是BP网络不可忽视的一个问题。"},{"id":"ai13011-pl-P5155005","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于聚类算法的描述，正确的有（ ）。","opts":["A. 聚类算法是非监督学习的代表算法","B. 聚类算法不需要使用训练集事先训练","C. 聚类算法利用数据本身的距离关系自动聚类出几个簇","D. 好的聚类需要满足簇内相似度高、簇间相似度低"],"ans":[0,1,2,3],"explain":"A项正确：聚类算法是非监督学习的代表算法。B项正确：聚类算法不需要使用训练集事先训练。C项正确：聚类算法利用数据本身的距离关系自动聚类出几个簇。D项正确：好的聚类需要满足簇内相似度高、簇间相似度低。"},{"id":"ai13011-pl-P5155006","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下属于常用距离计算方式的有（ ）。","opts":["A. 欧几里得距离","B. 曼哈顿距离","C. 切比雪夫距离","D. 余弦相似度"],"ans":[0,1],"explain":"衡量聚类距离的常用方式有欧几里得距离和曼哈顿距离两种。切比雪夫距离和余弦相似度在教材中未作为聚类距离的常用方式介绍。"},{"id":"ai13011-pl-P5155007","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于K-means聚类算法的描述，正确的有（ ）。","opts":["A. K-means是原型聚类的一种","B. K-means以最小化平均误差准则函数J为目标","C. K-means必须事先给出要生成的类的数目k","D. K-means对初值敏感"],"ans":[0,1,2,3],"explain":"A项正确：K-means是原型聚类的一种。B项正确：K-means以最小化“平均误差准则函数J”为目标。C项正确：K-means必须事先给出要生成的类的数目k。D项正确：K-means对初值敏感。"},{"id":"ai13011-pl-P5155008","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于DBSCAN密度聚类的描述，正确的有（ ）。","opts":["A. DBSCAN寻找密度相连的点的集合","B. DBSCAN的主要思想是寻找被低密度区域分离的高密度区域","C. 核心对象是指ε邻域至少包含MinPts个对象","D. 边界点是非核心对象但邻域中有核心对象"],"ans":[0,1,2,3],"explain":"A项正确：DBSCAN寻找密度相连的点的集合。B项正确：DBSCAN的主要思想是寻找被低密度区域分离的高密度区域。C项正确：核心对象是指ε邻域至少包含MinPts个对象。D项正确：边界点是非核心对象但邻域中有核心对象。"},{"id":"ai13011-pl-P5155009","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于层次聚类的描述，正确的有（ ）。","opts":["A. 层次聚类可以是从下而上地把小的cluster合并聚集","B. 层次聚类也可以是从上而下地将大的cluster进行分割","C. 层次聚类最大的优点是一次性地得到了整个聚类的过程","D. 层次聚类使用的是贪心算法，得到的只是局域最优"],"ans":[0,1,2,3],"explain":"A项正确：层次聚类可以是从下而上地把小的cluster合并聚集。B项正确：层次聚类也可以是从上而下地将大的cluster进行分割。C项正确：层次聚类最大的优点是一次性地得到了整个聚类的过程。D项正确：层次聚类使用的是贪心算法，得到的只是局域最优。"},{"id":"ai13011-pl-P5155010","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于降维目的的描述，正确的有（ ）。","opts":["A. 压缩数据以减少存储量","B. 去除噪声影响","C. 从数据中提取特征以便进行分类","D. 将数据投影到低维可视空间"],"ans":[0,1,2,3],"explain":"数据降维主要有以下目的：压缩数据以减少存储量、去除噪声影响、从数据中提取特征以便进行分类、将数据投影到低维可视空间以便于看清数据的分布。A、B、C、D均正确。"},{"id":"ai13011-pl-P5155011","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下属于线性降维技术代表方法的有（ ）。","opts":["A. 主成分分析(PCA)","B. 线性判别分析(LDA)","C. 核PCA","D. t-SNE"],"ans":[0,1],"explain":"线性降维技术的代表方法有主成分分析(PCA)、线性判别分析(LDA)等。核PCA是非线性降维方法，t-SNE属于流形学习方法，不属于线性降维技术。"},{"id":"ai13011-pl-P5155012","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于PCA和LDA的描述，正确的有（ ）。","opts":["A. PCA是一种非监督线性的降维方法","B. LDA是一种监督线性的降维方法","C. PCA选择使投影后方差最大的方向对数据进行投影","D. LDA使投影后两类样本的均值之差与投影样本的总类散度的比值最大"],"ans":[0,1,2,3],"explain":"A项正确：PCA是一种非监督线性的降维方法。B项正确：LDA是一种监督线性的降维方法。C项正确：PCA选择使投影后方差最大的方向对数据进行投影。D项正确：LDA使投影后两类样本的均值之差与投影样本的总类散度的比值最大。"},{"id":"ai13011-pl-P5155013","type":"mc","tier":"拔高","conf":"adapt","chap":"第4章","q":"以下关于特征选择方法的描述，正确的有（ ）。","opts":["A. 过滤式方法先对数据集进行特征选择，再训练学习器","B. 包裹式方法直接把最终将要使用的学习器性能作为特征子集的评价准则","C. 嵌入式方法将特征选择过程和机器训练过程融为一体","D. 包裹式方法的计算开销比过滤式小"],"ans":[0,1,2],"explain":"A项正确：过滤式方法先对数据集进行特征选择，再训练学习器。B项正确：包裹式方法直接把学习器性能作为特征子集的评价准则。C项正确：嵌入式方法将特征选择过程和机器训练过程融为一体。D项错误：包裹式方法的计算开销比过滤式大。"},{"id":"ai13011-pl-P5155057","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述机器学习中“过拟合”与“欠拟合”的概念及其主要原因。","opts":[],"ans":null,"explain":"教材用学生做训练题的生动比喻解释了过拟合和欠拟合的概念及成因。\n过拟合（Overfitting）：指模型只在训练样本上表现很好，但在未知的新数据（测试集）上预测效果很差的现象（即泛化能力差）。原因：由于模型过度学习或过于复杂，把训练集中某些局部的、特殊的特征或噪声当成了整个样本空间的通用特征。欠拟合（Underfitting）：指模型在训练集和测试集上的预测性能均较差的现象。原因：通常是由于训练数据集太小或模型结构过于简单，导致模型未能学习到样本数据中蕴含的基本规律和分布特征。"},{"id":"ai13011-pl-P5155058","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述决策树模型中属性划分时信息增益的计算思路及选择原则。","opts":[],"ans":null,"explain":"教材通过公式推导和实例计算详细说明了信息增益的计算方法和属性选择原则。\n决策树以信息增益为准则进行属性划分。计算思路为：首先计算数据集D的信息熵E(D)= -Σp_i lb p_i，然后计算按特征C划分后的条件熵Σ(|D^i|/|D|)E(D^i)，信息增益G(D,C)=E(D)-Σ(|D^i|/|D|)E(D^i)。选择原则：选择信息增益最大的属性作为划分属性。对于连续取值的特征，需要将所有取值按升序排列，取相邻值的中点作为候选分割点，分别计算信息增益，选取使信息增益最大的分割点。"},{"id":"ai13011-pl-P5155059","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述决策树剪枝策略中“预剪枝”与“后剪枝”的基本原理及优缺点对比。","opts":[],"ans":null,"explain":"教材系统对比了两种剪枝策略的原理、优缺点及适用场景。\n预剪枝（Pre-pruning）：原理是在决策树的生成过程中进行剪枝。在对每个节点进行划分前先进行评估，若当前节点的划分不能带来泛化性能的提升（如测试集准确率），则停止划分并将当前节点标记为叶节点。优缺点：降低了过拟合风险，并显著减少了决策树的训练时间与存储开销；但存在“欠拟合”风险，可能因为贪心策略切断后续潜在的优良分支。后剪枝（Post-pruning）：原理是先利用训练集生成一棵完整的决策树，然后自底向上地考察非叶节点，若将该节点对应的子树替换为叶节点能够提升模型的泛化能力，则进行剪枝。优缺点：通常比预剪枝保留更多的分支，欠拟合风险小，泛化性能往往优于预剪枝；但训练时间开销较大。"},{"id":"ai13011-pl-P5155060","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述朴素贝叶斯分类器的基本思想及其核心假设。","opts":[],"ans":null,"explain":"教材从数学推导角度阐述了朴素贝叶斯分类器的原理和核心假设。\n朴素贝叶斯分类器的基本思想：基于贝叶斯公式，通过学习先验概率P(Y=c_i)和条件概率P(X=x|Y=c_i)，计算后验概率P(Y=c_i|X=x)，将后验概率最大的类别作为预测结果。其核心假设是特征条件独立性假设：对已知类别，假设所有特征相互独立，即P(X=x|Y=c_i)=∏_{j=1}^n P(X^j=x^j|Y=c_i)。这使得计算大大简化，在数据较少的情况下很有效，可用于处理多类别问题。但在现实任务中，所有特征相互独立的假设很难完全成立，有时会牺牲一定的分类准确率。"},{"id":"ai13011-pl-P5155061","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述线性回归中最小二乘法的基本原理及当矩阵奇异时的处理方法。","opts":[],"ans":null,"explain":"教材从数学推导角度说明了最小二乘法的原理及正则化处理的必要性。\n最小二乘法的基本原理：通过最小化均方误差E=Σ(f(x_i)-y_i)^2来求解参数w和c，使预测值尽可能接近真实值。对于单特征情况，分别对w和c求偏导并令其为零，联立可解得参数。当矩阵XX^T为奇异矩阵时（即列相关），存在多个解。处理方法是在损失函数中引入正则化项（L2范数罚项），即E(\\tilde{w})=( \\tilde{w}^T X - y)( \\tilde{w}^T X - y)^T + λ||\\tilde{w}||^2。引入正则化后，只需调整系数λ，就能使(XX^T+λI)为非奇异矩阵，保证方程有唯一解。"},{"id":"ai13011-pl-P5155062","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述逻辑斯蒂回归与Softmax回归的关系及其主要优点。","opts":[],"ans":null,"explain":"教材阐明了逻辑斯蒂回归与Softmax的关系，并归纳了它们的主要优势。\n逻辑斯蒂回归是二分类模型，Softmax回归是其多分类的推广。当分类类别K=2时，Softmax回归退化为二分类逻辑斯蒂回归。它们的主要优点包括：（1）直接对分类的可能性进行建模，无须事先假设数据分布，避免了假设分布不准确带来的问题；（2）不是仅预测出“类别”，而是可得到近似概率预测，对需利用概率辅助决策的任务很有用；（3）Softmax回归是多层神经网络的重要组成部分，深度神经网络也需通过Softmax回归实现特征到最后类别的映射。"},{"id":"ai13011-pl-P5155063","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述支持向量机中“间隔”（Margin）的概念及其在模型中的作用。","opts":[],"ans":null,"explain":"教材从几何直观角度解释了间隔的概念及其在SVM中的核心地位。\n在支持向量机中，“间隔”是指各类中离分类线最近的样本且平行于分类线的直线之间的距离。最优分类线要求分类线不但能将两类正确分开，而且使分类间隔最大。支持向量机用距离分类超平面的距离来代表“确信度”——距离分类线越远的点，它分类正确的确信度越高。样本点到超平面的函数间隔为γ_i = y_i(w/||w||·x_i + b/||w||)，整个数据集的函数间隔是所有样本函数间隔的最小值。支持向量机就是使分类间隔最大，即γ_i &gt; γ对所有样本成立。"},{"id":"ai13011-pl-P5155064","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述支持向量机中核函数的作用及常用的核函数类型。","opts":[],"ans":null,"explain":"教材阐述了核函数的核心思想及两种常用核函数的特点。\n核函数的作用：将低维空间中线性不可分的样本点映射到高维空间使其线性可分，同时避免直接计算高维映射的内积，解决了映射后特征空间维数高、计算耗时的问题。常用核函数类型：（1）多项式核κ(x_i,x_j)=(x_i·x_j+d)^p，不引入核函数是d=0,p=1的特例（线性核）；（2）高斯核κ(x_i,x_j)=exp(-||x_i-x_j||²/(2σ²))，能将输入空间映射到无穷维特征空间，是使用最广泛的核函数之一。"},{"id":"ai13011-pl-P5155065","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述集成学习的基本思想及其三个关键假设。","opts":[],"ans":null,"explain":"教材用股市评论员投票的生动例子说明了集成学习的原理和关键假设。\n集成学习的基本思想：按照一定规则产生一组个体学习器，再按照一定策略将这些学习器结合起来，在测试时样本的预测结果由所有个体学习器共同得出。集成学习的关键假设：（1）各个体学习器的误差相互独立——这是集成学习能够通过多数表决等方式提升整体性能的理论基础；（2）个体学习器比随机猜测性能优——个体学习器的准确率应大于0.5，否则集成反而会降低性能。集成学习的核心问题是产生并结合“好而不同”的个体学习器，但准确性与多样性经常相互矛盾。"},{"id":"ai13011-pl-P5155066","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述Boosting和Bagging两种集成学习方法的主要区别。","opts":[],"ans":null,"explain":"教材从依赖关系、结合策略等多个维度对比了两种集成方法。\nBoosting与Bagging的主要区别：（1）个体学习器依赖关系不同：Boosting的个体学习器之间存在强依赖关系，必须串行生成，后一个学习器的输入依赖于前面学习器的输出；Bagging的个体学习器之间不存在强依赖关系，可以同时生成，并行化实现；（2）结合策略不同：Boosting通过加权求和结合各学习器（如Adaboost的系数α_m）；Bagging采用简单投票法或平均法；（3）侧重点不同：Boosting关注降低偏差，通过不断纠正前一轮的错误来提升性能；Bagging关注降低方差，通过样本扰动增加多样性来提升泛化能力。"},{"id":"ai13011-pl-P5155067","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述BP神经网络中“正向传播”与“反向传播”两个阶段的基本工作流程。","opts":[],"ans":null,"explain":"教材详细描述了BP算法的两阶段工作流程及参数更新公式。\n正向传播阶段：训练样本数据从输入层输入，经过隐藏层神经元的加权求和与激活函数变换，逐层向前计算，最终在输出层向外界输出预测结果。反向传播阶段：计算输出层预测值与真实值之间的误差，将误差逐层向前逆向传递给各隐藏层，并采用梯度下降策略修正各层神经元之间的连接权值与阈值，以最小化累积误差。具体地，通过计算输出层误差g_j和隐层误差e_h，更新权重Δw_hj=ηg_jb_h和Δv_ih=ηe_hx_i，以及阈值Δθ_j=-ηg_j和Δγ_h=-ηe_h。"},{"id":"ai13011-pl-P5155068","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述K-means聚类算法的基本原理和主要优缺点。","opts":[],"ans":null,"explain":"教材全面介绍了K-means的数学原理、算法步骤和优缺点分析。\nK-means算法的基本原理：以最小化平均误差准则函数J=Σ_{n=1}^NΣ_{k=1}^K r_{nk}||x_n-μ_k||²为目标，迭代地将所有数据样本划分为不同的类别。算法步骤为：选择k个初始聚类中心；将样本按最小距离分配到最邻近聚类；使用每个聚类中的样本均值作为新的聚类中心；重复直到聚类中心不再变化。主要优点：算法框架清晰简单易理解；处理大数据集时相对可伸缩且高效；当结果类密集且类间区别明显时效果最好。主要缺点：必须事先给出k值；对初值敏感；对“噪声”和孤立点数据敏感。"},{"id":"ai13011-pl-P5155069","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述DBSCAN密度聚类算法的基本思想和核心概念。","opts":[],"ans":null,"explain":"教材系统介绍了DBSCAN的核心概念和算法思想。\nDBSCAN的基本思想：寻找被低密度区域分离的高密度区域，即将密度大的“一团”数据看成一个类。其核心概念包括：（1）ε邻域：对于一个样本点，与其距离不大于ε的点的集合；（2）MinPts：密度阈值，用于衡量核心对象；（3）核心对象：如果一个对象的ε邻域至少包含MinPts个对象；（4）边界点：非核心对象但邻域中有核心对象；（5）噪声点：除核心对象和边界点之外的点；（6）密度可达：若p在q的ε邻域内，则p从q直接密度可达；密度可达性的传递闭包；（7）密度相连：若存在对象o使p和q从o密度可达，则p和q密度相连。"},{"id":"ai13011-pl-P5155070","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述PCA主成分分析的降维原理和算法步骤。","opts":[],"ans":null,"explain":"教材详细阐述了PCA的数学原理和算法步骤。\nPCA的降维原理：将数据从原坐标系转换到新坐标系，第一个新坐标轴选定在原始数据中方差最大的方向（第一主成分），第二个新坐标轴选择和第一个新坐标轴正交且有最大方差的方向（第二主成分），依此类推。PCA的目标是寻找能够保持采样数据方差的最佳投影子空间，是一种非监督线性的降维方法。算法步骤：（1）去除平均值；（2）计算协方差矩阵；（3）计算协方差矩阵的特征值和特征向量；（4）将特征值从小到大排序；（5）保留最上面的N个特征向量；（6）将数据转换到上述N个特征向量构建的新空间中。"},{"id":"ai13011-pl-P5155071","type":"sa","tier":"创新","conf":"adapt","chap":"第4章","q":"简述PCA与LDA两种降维方法的主要区别。","opts":[],"ans":null,"explain":"教材从多个维度对比了两种经典降维方法的核心差异。\nPCA与LDA的主要区别：（1）监督性不同：PCA是一种非监督线性的降维方法，不利用类别标签；LDA是一种监督线性的降维方法，利用类别标签信息；（2）优化目标不同：PCA基于重构的思想，选择使投影后方差最大的方向对数据进行投影，希望尽可能保留数据的信息；LDA基于分类的思想，寻找能使投影后样本具有“最大类间距离和最小类内距离”的最佳鉴别矢量空间；（3）应用场景不同：PCA在无监督场景下适用；LDA在分类任务中通常比PCA效果更好；（4）两者均可归结为特征值和特征向量的求解问题，实现简单且无须迭代即可达到全局最优解。"},{"id":"ai13011-pl-P5155033","type":"calc","tier":"创新","conf":"adapt","chap":"第4章","q":"某企业需要对海量文本数据进行情感分析，判断用户评论的情感倾向（正面/负面）。请回答以下问题：（1）从特征表示的角度，应如何将文本数据转换为机器学习模型可以处理的数值特征？（2）若使用朴素贝叶斯分类器进行情感分类，请简述其工作原理并说明为什么适用于文本分类任务。（3）如果数据量进一步增大，需要分布式处理，可以选用哪些大数据框架来实现？","opts":[],"ans":null,"explain":"本题综合考查文本特征表示方法、朴素贝叶斯分类器原理以及大数据框架选型能力。\n（1）文本转换为数值特征的方法：①词袋模型（Bag-of-Words）：将文本表示为词汇表中单词出现频次的向量；②TF-IDF：考虑词频和逆文档频率，降低常见词的权重，提高区分度；③Word2Vec或GloVe：将单词映射为稠密的低维向量，保留语义信息；④N-gram特征：考虑相邻词组的共现信息，捕获局部上下文。在实际应用中，需要对文本进行预处理（分词、去停用词、词干还原等），然后选择合适的特征表示方法。（2）朴素贝叶斯分类器的工作原理：基于贝叶斯公式P(Y|x)=P(x|Y)P(Y)/P(x)，在特征条件独立假设下，计算P(Y=c_i)∏_{j=1}^n P(x^j|Y=c_i)，选择后验概率最大的类别作为预测结果。适用于文本分类的原因：①文本数据中单词之间满足“条件独立性”的近似假设，朴素贝叶斯在此假设下表现良好；②模型简单、训练速度快，适合大规模文本数据；③对于高维稀疏的文本特征，朴素贝叶斯具有较好的鲁棒性；④能够输出概率值，便于后续决策。（3）可选的大数据框架：①Spark：提供MLlib机器学习库，支持分布式文本处理（如Word2Vec、TF-IDF）和分类算法（如朴素贝叶斯、逻辑斯蒂回归），适合批处理和迭代计算；②Flink：支持流式文本处理，适合实时情感分析场景；③Hadoop Map Reduce：可实现分布式文本处理和模型训练，但迭代效率较低。综合考虑，Spark最为合适，其内存计算和丰富的MLlib库能显著提升处理效率。"},{"id":"ai13011-pl-P5155034","type":"calc","tier":"创新","conf":"adapt","chap":"第4章","q":"某数据科学团队需要对一组客户数据进行聚类分析，以发现不同的客户群体特征。请回答以下问题：（1）简述K-means聚类算法的基本原理和步骤。（2）K-means聚类存在哪些缺点？如何选择合适的聚类数k？（3）如果数据分布呈现不规则的形状（如环形或S形），K-means的效果可能不佳。此时应选择什么聚类算法？请说明理由。","opts":[],"ans":null,"explain":"本题综合考查K-means算法原理、优缺点、参数选择方法以及替代算法（DBSCAN）的选择理由。\n（1）K-means算法的基本原理：以最小化平均误差准则函数J=Σ_{n=1}^NΣ_{k=1}^K r_{nk}||x_n-μ_k||²为目标，迭代将数据划分为K个簇。算法步骤：Step1选择K个初始聚类中心；Step2将样本按最小距离分配到最邻近聚类；Step3使用每个聚类中的样本均值作为新的聚类中心；Step4重复Step2和Step3直到聚类中心不再变化；Step5输出K个聚类簇。（2）K-means的缺点：①必须事先给出k值；②对初值敏感，不同初始值可能导致不同结果；③对噪声和孤立点敏感；④不适合发现非凸形状的簇。选择聚类数k的方法：①肘部法则（Elbow Method）：计算不同k值下的SSE（误差平方和），选择SSE下降拐点对应的k值；②轮廓系数（Silhouette Coefficient）：计算样本与同类簇的相似度与异类簇的差异，选择轮廓系数最大的k值；③结合业务需求确定合理的客户群体数量。（3）应选择DBSCAN密度聚类算法。理由：①DBSCAN能够发现任意形状的簇，包括环形、S形等不规则形状；②DBSCAN不需要预先指定簇的数量；③DBSCAN对噪声和离群点具有鲁棒性，能自动识别噪声点；④DBSCAN基于密度相连的思想，能将高密度区域聚为一类，非常适合处理形状不规则的聚类问题。"},{"id":"ai13011-pl-P5155038","type":"calc","tier":"创新","conf":"adapt","chap":"第4章","q":"某气象部门希望利用历史气象数据预测未来24小时的降雨概率。请回答以下问题：（1）这是一个什么类型的机器学习问题？应该选择什么模型进行预测？（2）请简述逻辑斯蒂回归在该场景中的应用原理，并说明为什么要对特征进行归一化处理。（3）如果降雨数据存在严重的类别不平衡（晴天远多于雨天），应该如何解决？","opts":[],"ans":null,"explain":"本题综合考查问题类型判断、逻辑斯蒂回归原理与特征归一化、类别不平衡处理策略。\n（1）这是一个二分类问题（降雨/不降雨），属于监督学习中的分类任务。可选择的模型：①逻辑斯蒂回归：简单高效，可输出概率值，具有良好的可解释性；②决策树/随机森林：能够处理特征间的非线性关系，可解释性强；③支持向量机：在高维特征空间中有良好表现；④梯度提升树（XGBoost/LightGBM）：处理表格数据效果优异，能自动处理缺失值。由于气象特征维度适中且需要概率输出，逻辑斯蒂回归和随机森林是较为合适的选择。（2）逻辑斯蒂回归的应用原理：将降雨概率表示为p(y=1|x)=1/(1+e^{-(w^T x+b)})，通过对数几率ln(p/(1-p))=w^T x+b建立线性关系，训练时使用极大似然估计最大化对数似然函数，采用梯度下降法求解参数。特征归一化的原因：①逻辑斯蒂回归的梯度大小受特征取值影响，取值较大的特征维度梯度较大，会导致参数更新不均匀，收敛缓慢；②归一化后各特征处于同一量级，梯度更新更加均衡，加速收敛；③对于使用正则化项的逻辑斯蒂回归，归一化能确保正则化对各个特征的惩罚公平。（3）类别不平衡的解决方法：①数据层面：欠采样（减少多数类样本数量）、过采样（复制少数类或使用SMOTE合成新样本）；②算法层面：调整决策阈值（如将默认的0.5阈值降低）；③代价敏感学习：给少数类错误预测设置更高的惩罚权重，在逻辑斯蒂回归中可使用class_weight参数；④评估指标选择：不使用准确率，改用精确率-召回率或F1值，或使用AUC-ROC曲线；⑤集成方法：使用Bagging或Boosting结合欠采样技术。"},{"id":"ai13011-pl-P5155112","type":"fill","tier":"拔高","conf":"adapt","chap":"第4章","q":"在机器学习中，预测目标变量$y$为离散取值的分类问题中，若类别标签只有“正”和“反”两个选项，这类问题被称为__1__问题。","opts":[],"ans":["二分类"],"explain":"预测目标取值离散且仅有两个选项的问题被称为二分类问题。\n参考答案: A.二分类"},{"id":"ai13011-pl-P5155113","type":"fill","tier":"拔高","conf":"adapt","chap":"第4章","q":"模型对未知样本进行预测的能力被称为__1__能力。","opts":[],"ans":["泛化"],"explain":"模型对未知样本进行预测的能力被称为“泛化”能力。\n参考答案: A.泛化"},{"id":"ai13011-pl-P5155114","type":"fill","tier":"拔高","conf":"adapt","chap":"第4章","q":"如果模型只在训练样本上表现得很好而不能对于新的数据样本做出很好的预测，则称为__1__。","opts":[],"ans":["过拟合(Overfitting)"],"explain":"如果模型只在训练样本上表现得很好而不能对于新的数据样本做出很好的预测，则称为模型过拟合。\n参考答案: A.过拟合(Overfitting)"},{"id":"ai13011-pl-P5155115","type":"fill","tier":"拔高","conf":"adapt","chap":"第4章","q":"在概率模型中，依据已知的$x$对$Y$进行概率估计的条件概率$P(Y|x)$被称为__1__。","opts":[],"ans":["后验概率"],"explain":"依据已知的$x$对$Y$进行概率估计的条件概率$P(Y|x)$被称为后验概率。\n参考答案: A.后验概率"},{"id":"ai13011-pl-P5155116","type":"fill","tier":"拔高","conf":"adapt","chap":"第4章","q":"决策树的属性划分是以__1__为准则的，选择使该值最大的属性进行划分。","opts":[],"ans":["信息增益"],"explain":"决策树的属性划分是以信息增益为准则的。\n参考答案: A.信息增益"},{"id":"ai13011-pl-P5155117","type":"fill","tier":"拔高","conf":"adapt","chap":"第4章","q":"在利用朴素贝叶斯分类器估计概率时，若因训练集规模有限导致某个特征取值在某类样本中的计数为零，为了避免“零概率”现象，通常对概率估计进行__1__修正。","opts":[],"ans":["拉普拉斯(Laplacian)"],"explain":"为避免概率估计值为零导致预测结果被置零，通常使用拉普拉斯修正方法。\n参考答案: A.拉普拉斯(Laplacian)"},{"id":"ai13011-pl-P5155118","type":"fill","tier":"拔高","conf":"adapt","chap":"第4章","q":"线性回归使用__1__来估计参数，通过最小化均方误差来求解。","opts":[],"ans":["最小二乘法"],"explain":"线性回归采用最小二乘法估计参数。\n参考答案: A.最小二乘法"},{"id":"ai13011-pl-P5155119","type":"fill","tier":"拔高","conf":"adapt","chap":"第4章","q":"二分类逻辑斯蒂回归可以推广到多分类逻辑斯蒂回归，这就是__1__分类器。","opts":[],"ans":["Softmax"],"explain":"二分类逻辑斯蒂回归可以推广到多分类逻辑斯蒂回归，这就是softmax分类器。\n参考答案: A.Softmax"},{"id":"ai13011-pl-P5155120","type":"fill","tier":"拔高","conf":"adapt","chap":"第4章","q":"支持向量机中用距离分类超平面的距离来代表__1__。","opts":[],"ans":["确信度"],"explain":"支持向量机是用距离分类超平面的距离来代表“确信度”。\n参考答案: A.确信度"},{"id":"ai13011-pl-P5155121","type":"fill","tier":"拔高","conf":"adapt","chap":"第4章","q":"线性支持向量机通过对偶问题求解后，最终的模型决策仅依赖于拉格朗日乘子$\\alpha_i &gt; 0$所对应的样本点，这些样本点被称为__1__。","opts":[],"ans":["支持向量"],"explain":"$\\alpha_i &gt; 0$的样本为支持向量，模型只依赖于支持向量。\n参考答案: A.支持向量"},{"id":"ai13011-pl-P5155122","type":"fill","tier":"拔高","conf":"adapt","chap":"第4章","q":"Python的sklearn库中，用于支持向量机分类的类是__1__。","opts":[],"ans":["sklearn.svm.SVC"],"explain":"sklearn.svm.SVC用于分类。\n参考答案: A.sklearn.svm.SVC"},{"id":"ai13011-pl-P5155123","type":"fill","tier":"拔高","conf":"adapt","chap":"第4章","q":"聚类算法属于__1__学习的代表算法。","opts":[],"ans":["非监督（无监督）"],"explain":"聚类算法是非监督学习的代表算法。\n参考答案: A.非监督（无监督）"},{"id":"ai13011-pl-P5155124","type":"fill","tier":"拔高","conf":"adapt","chap":"第4章","q":"高维情况下出现的数据样本稀疏、距离计算困难等问题，被称为__1__。","opts":[],"ans":["维数灾难"],"explain":"高维情况下出现的数据样本稀疏、距离计算困难等问题，被称为“维数灾难”。\n参考答案: A.维数灾难"},{"id":"ai13011-pl-P5155125","type":"fill","tier":"拔高","conf":"adapt","chap":"第4章","q":"主成分分析(PCA)是一种__1__线性的降维方法。","opts":[],"ans":["非监督（无监督）"],"explain":"PCA是一种非监督线性的降维方法。\n参考答案: A.非监督（无监督）"},{"id":"ai13011-pl-P5154808","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"AlphaGo围棋程序中，用于估计当前局面是白胜还是黑胜的网络是（ ）。","opts":["A. 走棋网络(Policy Network)","B. 快速走子(Fast Rollout)","C. 估值网络(Value Network)","D. 蒙特卡罗树搜索(MCTS)"],"ans":2,"explain":"估值网络(Value Network)负责给定当前局面，估计是白胜还是黑胜。"},{"id":"ai13011-pl-P5154809","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"2015年ILSVRC中，由微软亚洲研究院提出的（ ）将Top5错误率降到3.57%，超越了人类的识别能力。","opts":["A. AlexNet","B. GoogLeNet","C. ResNet","D. DenseNet"],"ans":2,"explain":"2015年由微软亚洲研究院提出的152层深度残差网络(ResNet)将Top5错误率进一步降到3.57%，超越了人类的识别能力。"},{"id":"ai13011-pl-P5154810","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"2017年，ILSVRC宣告正式结束，另一个注重图像学习和理解的赛事（ ）成为科研人员关注的新焦点。","opts":["A. COCO","B. WebVision","C. PASCAL VOC","D. ImageNet"],"ans":1,"explain":"2017年ILSVRC宣告正式结束，另一个注重图像学习和理解的赛事WebVision成为科研人员关注的新焦点。"},{"id":"ai13011-pl-P5154811","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在深度神经网络训练中，使用sigmoid或tanh激活函数时，反向传播的梯度传播至前面几层时衰减到极小甚至消失的现象被称为（ ）。","opts":["A. 梯度爆炸","B. 梯度消失","C. 过拟合","D. 欠拟合"],"ans":1,"explain":"在一个很深的神经网络中，对于像sigmoid或tanh这样的激活函数，很容易导致当反向传播的梯度传播至前面几层时，衰减到极小甚至消失，从而导致比较靠前的各层网络的参数难以训练，这就是梯度消失问题。"},{"id":"ai13011-pl-P5154812","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"卷积神经网络的诞生具有生物学基础，Hubel和Wiesel在研究猫脑皮层时发现视觉系统的浅层视觉细胞对特定的光线模式非常敏感，这为CNN提供了（ ）。","opts":["A. 数学理论基础","B. 生物学启发","C. 硬件设计方案","D. 训练算法"],"ans":1,"explain":"Hubel和Wiesel的研究对深度学习模型产生了深刻的影响，因此卷积神经网络的诞生具有一定的生物学的基础。"},{"id":"ai13011-pl-P5154813","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"卷积神经网络主要采用三种方法来减少网络中的参数数量，以下哪种不属于这三种方法？","opts":["A. 局部感知","B. 参数共享","C. 池化","D. 全连接"],"ans":3,"explain":"卷积神经网络主要采用三种方法减少参数数量：局部感知、参数共享和池化。全连接会增加参数数量。"},{"id":"ai13011-pl-P5154814","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在卷积神经网络中，同一卷积核的权值参数在整张图像的所有位置共享，这种机制称为（ ）。","opts":["A. 局部感知","B. 参数共享","C. 池化","D. 正则化"],"ans":1,"explain":"参数共享是指两层神经单元之间的连接参数在各个位置上共享，将神经网络中的参数大大减少。"},{"id":"ai13011-pl-P5154815","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"池化层中，输出某一邻域内最大值的池化方式被称为（ ）。","opts":["A. 最小池化","B. 平均池化","C. 最大池化","D. 随机池化"],"ans":2,"explain":"最大池化(Max Pooling)会输出某一邻域内的最大值。"},{"id":"ai13011-pl-P5154816","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在卷积神经网络中，LeNet5是用于（ ）的经典网络结构。","opts":["A. 自然语言处理","B. 手写数字识别","C. 语音识别","D. 机器翻译"],"ans":1,"explain":"LeNet5是用于手写数字识别的经典卷积神经网络。"},{"id":"ai13011-pl-P5154817","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"循环神经网络(RNN)之所以被称为“循环的”，是因为（ ）。","opts":["A. 网络的拓扑结构是环形的","B. 一个序列当前的输出与前面的输出有关，隐藏层之间的节点有连接","C. 网络的输入和输出是循环的","D. 网络只在循环结束后才输出结果"],"ans":1,"explain":"循环神经网络之所以被称为循环的，是因为一个序列当前的输出与前面的输出有关。具体的表现形式为隐藏层之间的节点不再是无连接的而是有连接的。"},{"id":"ai13011-pl-P5154818","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在RNN中，某一时刻的隐藏状态既取决于此时刻的输入，又取决于（ ）。","opts":["A. 上一时刻的输出","B. 上一时刻的隐藏状态","C. 下一时刻的输入","D. 所有时刻的输入"],"ans":1,"explain":"与传统的神经网络不同，某一时刻的隐藏状态既取决于此时刻的输入，又取决于上一时刻隐藏状态。"},{"id":"ai13011-pl-P5154819","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"RNN在不同时刻隐藏状态之间的连接矩阵以及输入与隐藏层之间的连接矩阵均采用了（ ），这使得模型可以处理不同长度的序列并把握语义的不变性。","opts":["A. 参数独立","B. 参数共享","C. 参数随机初始化","D. 参数固定"],"ans":1,"explain":"各个时刻隐藏状态之间的连接矩阵均为同一个矩阵，输入特征与隐藏层之间的连接矩阵也是同一个矩阵。这种参数共享机制使得模型可以处理不同长度的句子并把握语义不变性。"},{"id":"ai13011-pl-P5154820","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"生成对抗网络(GAN)由两个重要部分构成，分别是（ ）。","opts":["A. 编码器和解码器","B. 生成器和判别器","C. 卷积层和池化层","D. 输入层和输出层"],"ans":1,"explain":"生成对抗网络由两个重要的部分构成：生成器和判别器。"},{"id":"ai13011-pl-P5154821","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"GAN训练中，当生成器生成的假数据与真实数据分布几乎一致时，判别器将（ ）。","opts":["A. 能100%准确判断真假","B. 对所有输入给出相同的概率值","C. 完全无法工作","D. 只能判断假数据"],"ans":1,"explain":"假如生成器所生成的假数据与真实数据分布几乎一致，那么判别器就无法判断收到的数据是真数据还是假数据，从而只能对所有的输入给出相同的概率值。"},{"id":"ai13011-pl-P5154822","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在GAN的训练中，使用带步长的卷积和小步长卷积的网络架构族被称为（ ）。","opts":["A. LAPGAN","B. DCGAN","C. InfoGAN","D. ALI"],"ans":1,"explain":"Radford等提出了一种被称为DCGAN的网络架构族，它允许训练一对深度卷积生成器和判别器网络。"},{"id":"ai13011-pl-P5154823","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在GAN的变体中，将生成器和判别器改造成条件类，使其能够根据条件合成图像的GAN被称为（ ）。","opts":["A. DCGAN","B. InfoGAN","C. 条件GAN","D. ALI/BiGAN"],"ans":2,"explain":"通过将生成器和判别器改造成条件类，Mirza等将GAN框架成功扩展成了条件设置，即条件GAN。"},{"id":"ai13011-pl-P5154920","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在深度学习中，卷积神经网络(CNN)的核心思想不包括（ ）。","opts":["A. 局部感知","B. 参数共享","C. 池化","D. 循环连接"],"ans":3,"explain":"CNN的核心思想包括局部感知、参数共享和池化。循环连接是RNN（循环神经网络）的特点。"},{"id":"ai13011-pl-P5154922","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"GAN训练中，模式缺失(Mode Collapse)问题是指（ ）。","opts":["A. 生成器无法生成任何样本","B. 判别器无法正确判断","C. 生成器只能生成一种样本点而无法生成更多种类的样本点","D. 训练过程不收敛"],"ans":2,"explain":"模式缺失问题将导致生成器退化，使生成器只能生成一种样本点而无法生成更多种类的样本点，最终导致学习过程中断。"},{"id":"ai13011-pl-P5155014","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于AlphaGo的描述，正确的有（ ）。","opts":["A. AlphaGo是谷歌DeepMind公司开发的围棋程序","B. AlphaGo包含走棋网络、快速走子、估值网络和蒙特卡罗树搜索四个部分","C. 走棋网络和估值网络基于深度卷积神经网络","D. 2016年AlphaGo以4:1战胜围棋世界冠军李世石"],"ans":[0,1,2,3],"explain":"A项正确：AlphaGo是谷歌DeepMind公司开发的围棋程序。B项正确：AlphaGo包含四个部分：走棋网络、快速走子、估值网络和蒙特卡罗树搜索。C项正确：走棋网络和估值网络基于深度卷积神经网络。D项正确：2016年AlphaGo以4:1战胜李世石。"},{"id":"ai13011-pl-P5155015","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于深度神经网络困难的描述，正确的有（ ）。","opts":["A. 深层神经网络面临计算量巨大的问题","B. 梯度消失是深度神经网络训练中的难题","C. 梯度爆炸是深度神经网络训练中的难题","D. 单纯加深神经网络层数在实际上是不可行的"],"ans":[0,1,2,3],"explain":"A项正确：深层神经网络面临计算量巨大的问题。B项正确：梯度消失是深度神经网络训练中的难题。C项正确：梯度爆炸是深度神经网络训练中的难题。D项正确：单纯加深神经网络层数在实际上是不可行的。"},{"id":"ai13011-pl-P5155016","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"卷积神经网络主要采用的方法包括（ ）。","opts":["A. 局部感知","B. 参数共享","C. 池化","D. 全连接"],"ans":[0,1,2],"explain":"卷积神经网络主要采用三种方法：局部感知、参数共享、池化。全连接会增加参数数量，不是减少参数的方法。"},{"id":"ai13011-pl-P5155017","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于卷积神经网络的描述，正确的有（ ）。","opts":["A. 卷积神经网络的诞生具有生物学基础","B. 局部感知使神经网络模型可以感知图像的局部特性","C. 参数共享基于图像特征具有位置无关性的原理","D. 池化层使模型具有抵抗图像轻微位移的能力"],"ans":[0,1,2,3],"explain":"A项正确：卷积神经网络的诞生具有生物学基础。B项正确：局部感知使神经网络模型可以感知图像的局部特性。C项正确：参数共享基于图像特征具有位置无关性的原理。D项正确：池化层使模型具有抵抗图像轻微位移的能力。"},{"id":"ai13011-pl-P5155018","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于循环神经网络的描述，正确的有（ ）。","opts":["A. RNN常用于文本、语音等时间序列的处理","B. RNN中某一时刻的隐藏状态既取决于此时刻的输入，又取决于上一时刻的隐藏状态","C. RNN各个时刻隐藏状态之间的连接矩阵是同一个矩阵","D. RNN采用参数共享机制，可以处理不同长度的序列"],"ans":[0,1,2,3],"explain":"A项正确：RNN被广泛运用于文本、语音等时间序列的处理。B项正确：某一时刻的隐藏状态既取决于此时刻的输入，又取决于上一时刻的隐藏状态。C项正确：各个时刻隐藏状态之间的连接矩阵均为同一个矩阵W。D项正确：RNN采用参数共享机制，可以处理不同长度的序列。"},{"id":"ai13011-pl-P5155019","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于生成对抗网络的描述，正确的有（ ）。","opts":["A. GAN由生成器和判别器两个重要部分构成","B. 生成器的目标是生成可以“骗过”判别器的假数据","C. 判别器的目标是判断图像是真实的还是机器生成的","D. GAN的训练需要生成器和判别器交替训练"],"ans":[0,1,2,3],"explain":"A项正确：GAN由生成器和判别器两个重要部分构成。B项正确：生成器利用算法生成可以“骗过”判别器的假数据。C项正确：判别器判断图像是真实的还是机器生成的。D项正确：GAN通过生成器和判别器交替训练，使两者能力都越来越强。"},{"id":"ai13011-pl-P5155020","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于GAN优缺点的描述，正确的有（ ）。","opts":["A. GAN能更好地建模数据分布","B. GAN不再需要利用马尔可夫链进行反复采样","C. GAN训练不稳定是其主要缺陷之一","D. 模式缺失是GAN学习过程中可能出现的问题"],"ans":[0,1,2,3],"explain":"A项正确：GAN能更好地建模数据分布。B项正确：GAN不再需要利用马尔可夫链进行反复采样。C项正确：难训练、不稳定是GAN的主要缺陷之一。D项正确：模式缺失是GAN学习过程中可能出现的问题。"},{"id":"ai13011-pl-P5155021","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于GAN变体的描述，正确的有（ ）。","opts":["A. DCGAN在训练中使用带步长的卷积和小步长卷积","B. 条件GAN可以根据条件合成图像","C. ALI/BiGAN由编码器、解码器和判别器三个网络构成","D. InfoGAN可以在完全无监督学习中发现目标类"],"ans":[0,1,2,3],"explain":"A项正确：DCGAN在训练中使用带步长的卷积和小步长卷积。B项正确：条件GAN可以根据条件合成图像。C项正确：ALI/BiGAN由三个网络构成：判别器、解码器(G)、编码器(ε)。D项正确：InfoGAN可以在完全无监督学习中发现目标类。"},{"id":"ai13011-pl-P5155072","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"简述深度神经网络在实际训练中面临的主要困难。","opts":[],"ans":null,"explain":"教材从计算量和梯度传播两个角度阐述了深度神经网络的核心挑战。\n深度神经网络面临的主要困难包括：（1）计算量巨大：以图像处理为例，1000×1000的图像可表示为10⁶维向量，若隐藏层也是10⁶维，输入层到隐藏层的参数为10¹²，远超当前计算机的计算能力；（2）梯度消失：在深层网络中使用sigmoid或tanh激活函数时，反向传播的梯度传播至前面几层时衰减到极小甚至消失，导致浅层网络参数难以训练；（3）梯度爆炸：少数情况下，随着梯度反向传播，参数更新量没有衰减反而剧增，导致模型极度不稳定。由于这些问题，单纯加深神经网络层数在实际上是不可行的。"},{"id":"ai13011-pl-P5155073","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"简述卷积神经网络中“局部感知”、“参数共享”和“池化”三种机制的作用。","opts":[],"ans":null,"explain":"教材从原理和效果两方面阐述了CNN的三大核心机制。\n（1）局部感知：每个隐藏层神经元仅与输入图像的局部区域相连，利用图像局部像素相关性高的特点，大幅减少连接权值参数，使网络可以感知图像的局部特性；（2）参数共享：在卷积操作中，同一卷积核的权值参数在整张图像的所有位置共享，基于“图像特征具有位置无关性”的原理，将参数量缩减至仅与卷积核大小相关，大幅减少参数数量；（3）池化：通过池化方程（如最大池化、平均池化）整合相邻区域的统计特征，降低特征图的空间分辨率与维度，在减少计算量的同时，赋予模型抵抗图像轻微位移和旋转的能力，即模型更关心特征“是否出现”而非“出现在何处”。"},{"id":"ai13011-pl-P5155074","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"简述循环神经网络中采用参数共享机制的原因。","opts":[],"ans":null,"explain":"教材从序列长度适应性和语义不变性两个角度解释了RNN参数共享的必要性。\nRNN中各个时刻隐藏状态之间的连接矩阵均为同一个矩阵W，输入特征与隐藏层之间的连接矩阵也是同一个矩阵U。采用参数共享的原因有：（1）应对不同长度的序列需求：如果各个时刻的参数都是独特的，针对不同长度的句子需要建立不同的模型，测试时极易遇到未建模的序列长度。参数共享使得同一个模型可以处理任意长度的序列数据；（2）把握语义的不变性：句子中的某个成分可以出现在不同的位置（如“I went to Beijing in 2008”与“In 2008, I went to Beijing”表达相同意思）。当各个时间位置共享参数时，即便成分的位置发生改变，对应位置的参数依然保持一致，从而使模型能够准确把握这种语义不变性。"},{"id":"ai13011-pl-P5155075","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"简述生成对抗网络（GAN）的基本原理和训练过程。","opts":[],"ans":null,"explain":"教材用伪造者与调查者的类比生动解释了GAN的原理和训练过程。\nGAN由生成器（Generator）和判别器（Discriminator）两部分构成。生成器的目标是生成可以“骗过”判别器的假数据；判别器的目标是判断图像是真实的还是机器生成的。训练过程分为两个阶段交替进行：第一阶段固定判别器训练生成器——使用效果较好的D判断G生成的“假数据”，G逐渐完善直到D被完全骗过；第二阶段固定生成器训练判别器——D经过训练提高鉴别能力，最终能准确判断所有假图片。通过不断循环这两个阶段，G和D的能力都越来越强，最终获得效果非常好的G用于生成图片。"},{"id":"ai13011-pl-P5155035","type":"calc","tier":"创新","conf":"adapt","chap":"第5-7章","q":"某研究机构希望利用深度学习方法对手写数字进行识别。请回答以下问题：（1）与传统机器学习方法相比，深度学习在手写数字识别任务中有何优势？（2）请设计一个卷积神经网络（CNN）结构用于手写数字识别（MNIST数据集），并说明各层的设计理由。（3）在训练CNN时，可能会遇到哪些问题？如何解决？","opts":[],"ans":null,"explain":"本题综合考查深度学习的优势、CNN网络结构设计以及训练问题的解决方法，要求具备实际项目设计能力。\n（1）深度学习在手写数字识别中的优势：①自动特征提取：CNN能够自动从原始像素中学习边缘、角点等低层特征，并逐层组合为高层语义特征，无需人工设计特征（如HOG、SIFT）；②更强的泛化能力：深度网络能够学习更复杂的特征表示，在测试集上表现更好；③端到端学习：输入原始图像直接输出分类结果，减少了中间环节的误差累积；④鲁棒性：对图像的轻微位移、旋转和缩放具有较好的不变性。（2）CNN结构设计：①输入层：28×28×1的灰度图像；②卷积层1：使用32个3×3卷积核，提取局部特征（如边缘），激活函数使用ReLU（缓解梯度消失、加速收敛）；③卷积层2：使用32个3×3卷积核，进一步提取高层特征；④池化层：使用2×2最大池化，降低特征图维度，减少参数量，增强平移不变性；⑤Dropout层（0.25）：随机丢弃部分神经元，防止过拟合；⑥Flatten层：将多维特征图展平为一维向量；⑦全连接层（128个神经元）：综合所有特征进行分类决策；⑧Dropout层（0.5）：进一步正则化；⑨输出层（10个神经元，Softmax）：输出10个数字类别的概率分布。（3）训练中可能遇到的问题及解决方法：①过拟合：采用Dropout、早停（Early Stopping）、数据增强（旋转、平移、缩放）或L2正则化；②梯度消失：使用ReLU激活函数替代Sigmoid/Tanh，或采用批归一化（Batch Normalization）；③收敛慢：使用自适应学习率优化器（如Adam、Adadelta），或调整学习率；④训练不稳定：使用较小的学习率或学习率衰减策略；⑤数据不平衡：使用数据增强或类别权重调整。"},{"id":"ai13011-pl-P5155126","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"AlphaGo围棋程序中，用于估计当前局面是白胜还是黑胜的网络是__1__。","opts":[],"ans":["估值网络(Value Network)"],"explain":"估值网络(Value Network)负责给定当前局面，估计是白胜还是黑胜。\n参考答案: A.估值网络(Value Network)"},{"id":"ai13011-pl-P5154824","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"强化学习中，智能体的目标是（ ）。","opts":["A. 最大化即时奖励","B. 最大化长期累积奖励的期望值","C. 最小化错误次数","D. 最大化动作空间"],"ans":1,"explain":"智能体的目标就是最大化接收到奖励总量，这意味着不是最大化即时奖励，而是最大化长期的累积奖励。"},{"id":"ai13011-pl-P5154825","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"以下哪个是强化学习最重要的特征？","opts":["A. 有标签的数据和批量学习","B. 试错搜索和延迟奖励","C. 寻找隐藏的结构特征","D. 最小化经验风险"],"ans":1,"explain":"试错搜索和延迟奖励这两点是强化学习最重要的特征。"},{"id":"ai13011-pl-P5154826","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"强化学习与无监督学习的主要区别在于（ ）。","opts":["A. 强化学习需要标签数据","B. 强化学习的目标是最大化收益信号，而不是寻找隐藏的结构特征","C. 无监督学习需要与环境交互","D. 强化学习不需要奖励信号"],"ans":1,"explain":"无监督学习是寻找未标记数据中隐藏的结构特征，而强化学习的目标在于试图最大化收益信号。"},{"id":"ai13011-pl-P5154827","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在分幕式任务中，每个分幕都以（ ）的特殊状态终止。","opts":["A. 起始状态","B. 末状态","C. 任意状态","D. 奖励状态"],"ans":1,"explain":"每一个分幕都以末状态(Terminal State)的特殊状态终止。"},{"id":"ai13011-pl-P5154828","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"折扣率$\\gamma$越接近1，智能体的视野变得（ ）。","opts":["A. 越短视","B. 越长远","C. 不变","D. 越不稳定"],"ans":1,"explain":"当$\\gamma$接近于1时，回报的目标会更多地将未来奖励考虑在内，即智能体的视野变得更长远。"},{"id":"ai13011-pl-P5154829","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在强化学习中，策略是从状态到选择各个可能动作（ ）的映射。","opts":["A. 值函数","B. 概率","C. 奖励","D. 状态"],"ans":1,"explain":"策略是从状态到选择各个可能动作概率的映射。"},{"id":"ai13011-pl-P5154830","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在策略$\\pi$下状态$s$的值函数$V_{\\pi}(s)$定义为（ ）。","opts":["A. 从状态s开始采取动作a可以获得的期望回报","B. 从状态s开始并在之后遵循策略$\\pi$可以获得的期望回报","C. 从状态s开始采取动作a并在之后遵循策略$\\pi$可以获得的期望回报","D. 从初始状态开始遵循策略$\\pi$可以获得的期望回报"],"ans":1,"explain":"在策略$\\pi$下状态s的值函数$V_{\\pi}(s)$定义为从状态s开始，并在之后遵循策略$\\pi$，从而获得期望回报。"},{"id":"ai13011-pl-P5154831","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"Bellman最优方程中，$V_{}(s)$的最优值可表示为（ ）。","opts":["A. $V_{}(s) = \\sum_a \\pi(a|s)Q_{}(s,a)$","B. $V_{}(s) = \\max_a Q_{}(s,a)$","C. $V_{}(s) = \\max_a \\sum_{s&#039;} P(s&#039;|s,a)R(s,a,s&#039;)$","D. $V_{}(s) = \\sum_{s&#039;} P(s&#039;|s,\\pi(s))V_{}(s&#039;)$"],"ans":1,"explain":"Bellman最优方程为$V_{}(s) = \\max_a Q_{}(s,a)$。"},{"id":"ai13011-pl-P5154832","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"解决最优策略问题的两种基本算法是（ ）。","opts":["A. 梯度下降和随机梯度下降","B. 策略迭代和价值迭代","C. Q学习和Sarsa","D. 蒙特卡罗和时序差分"],"ans":1,"explain":"求取最优策略的两种方法：策略迭代（先评估策略再改进）和价值迭代（直接通过V值更新V值）。"},{"id":"ai13011-pl-P5154833","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"动态规划中，策略评估使用（ ）方程来迭代更新状态价值。","opts":["A. Bellman最优方程","B. Bellman期望方程","C. Bellman更新方程","D. Bellman差分方程"],"ans":1,"explain":"策略评估使用反向迭代采用Bellman期望方程来更新状态值函数。"},{"id":"ai13011-pl-P5154834","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在策略改进中，如果新策略在所有状态上的值函数满足（ ），则新策略优于旧策略。","opts":["A. $V_{\\pi&#039;}(s) &lt; V_{\\pi}(s)$","B. $V_{\\pi&#039;}(s) \\geq V_{\\pi}(s)$","C. $V_{\\pi&#039;}(s) = V_{\\pi}(s)$","D. $V_{\\pi&#039;}(s)$ 与 $V_{\\pi}(s)$ 无关"],"ans":1,"explain":"如果$V_{\\pi&#039;}(s) \\geq V_{\\pi}(s)$对所有状态成立，则新策略$\\pi&#039;$优于或等于旧策略$\\pi$。"},{"id":"ai13011-pl-P5154835","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"策略迭代算法的完整过程是（ ）。","opts":["A. 策略评估 → 策略改进 → 策略评估 → 策略改进 → ... → 最优策略","B. 策略改进 → 策略评估 → 策略改进 → 策略评估 → ... → 最优策略","C. 策略评估 → 策略评估 → 策略改进 → 策略改进 → ... → 最优策略","D. 策略改进 → 策略改进 → 策略评估 → 策略评估 → ... → 最优策略"],"ans":0,"explain":"策略迭代的过程为：$\\pi_0 \\overset{E}{\\rightarrow} V_{\\pi_0} \\overset{I}{\\rightarrow} \\pi_1 \\overset{E}{\\rightarrow} V_{\\pi_1} \\overset{I}{\\rightarrow} \\pi_2 \\overset{E}{\\rightarrow} \\ldots \\overset{I}{\\rightarrow} \\pi_{} \\overset{E}{\\rightarrow} V_{\\pi_{}}$，即先评估再改进，交替进行。"},{"id":"ai13011-pl-P5154836","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"价值迭代算法中，更新状态价值的公式为（ ）。","opts":["A. $V_{k+1}(s) = \\sum_a \\pi(a|s)\\sum_{s&#039;,r} P(s&#039;,r|s,a)[r + \\gamma V_k(s&#039;)]$","B. $V_{k+1}(s) = \\max_a \\sum_{s&#039;,r} P(s&#039;,r|s,a)[r + \\gamma V_k(s&#039;)]$","C. $V_{k+1}(s) = \\sum_a \\pi(a|s)Q_k(s,a)$","D. $V_{k+1}(s) = \\max_a Q_k(s,a)$"],"ans":1,"explain":"价值迭代的更新公式为$V_{k+1}(s) \\doteq \\max_a \\sum_{s&#039;,r} P(s&#039;,r|s,a)[r + \\gamma V_k(s&#039;)]$。"},{"id":"ai13011-pl-P5154837","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"价值迭代可以看作是对策略评估进行了（ ）。","opts":["A. 精确计算","B. 截断","C. 扩展","D. 忽略"],"ans":1,"explain":"价值迭代可以编写为一个特别简单的更新操作，其结合了策略改进和截断的策略评估步骤。"},{"id":"ai13011-pl-P5154838","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"时序差分学习(TD)是（ ）方法的结合。","opts":["A. 蒙特卡罗和动态规划","B. 蒙特卡罗和策略梯度","C. 动态规划和策略梯度","D. Q学习和Sarsa"],"ans":0,"explain":"时序差分学习是蒙特卡罗方法和动态规划方法的结合。"},{"id":"ai13011-pl-P5154839","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"蒙特卡罗方法更新值函数时，使用的目标是（ ）。","opts":["A. $R_{t+1} + \\gamma V(S_{t+1})$","B. $G_t$（实际回报）","C. $\\max_a Q(S_{t+1},a)$","D. $R_{t+1}$"],"ans":1,"explain":"蒙特卡罗方法需要等到当前访问状态之后的返回值$G_t$变成已知，然后用这个返回值作为$V(S_t)$的目标值。"},{"id":"ai13011-pl-P5154840","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"TD(0)方法更新值函数时，使用的目标是（ ）。","opts":["A. $G_t$（实际回报）","B. $R_{t+1} + \\gamma V(S_{t+1})$","C. $\\max_a Q(S_{t+1},a)$","D. $R_{t+1}$"],"ans":1,"explain":"TD方法更新的目标是$R_{t+1} + \\gamma V(S_{t+1})$，这种TD方法被称为onestep TD或TD(0)。"},{"id":"ai13011-pl-P5154841","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"Sarsa算法的名称来源于更新时使用的五元组（ ）。","opts":["A. $(S_t, A_t, R_{t+1}, S_{t+1}, A_{t+1})$","B. $(S_t, R_t, S_{t+1}, R_{t+1}, A_{t+1})$","C. $(S_t, A_t, S_{t+1}, A_{t+1}, R_t)$","D. $(S_t, R_t, A_t, S_{t+1}, A_{t+1})$"],"ans":0,"explain":"Sarsa规则使用了一个五元组$(S_t, A_t, S_{t+1}, R_{t+1}, A_{t+1})$，因此算法被命名为Sarsa。"},{"id":"ai13011-pl-P5154842","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"Q学习算法中，更新Q值的公式为（ ）。","opts":["A. $Q(S_t, A_t) \\leftarrow Q(S_t, A_t) + \\alpha[R_{t+1} + \\gamma Q(S_{t+1}, A_{t+1}) Q(S_t, A_t)]$","B. $Q(S_t, A_t) \\leftarrow Q(S_t, A_t) + \\alpha[R_{t+1} + \\gamma\\max_a Q(S_{t+1}, a) Q(S_t, A_t)]$","C. $Q(S_t, A_t) \\leftarrow Q(S_t, A_t) + \\alpha[G_t Q(S_t, A_t)]$","D. $Q(S_t, A_t) \\leftarrow Q(S_t, A_t) + \\alpha[R_{t+1} + \\gamma V(S_{t+1}) Q(S_t, A_t)]$"],"ans":1,"explain":"Q学习算法的更新公式为$Q(S_t, A_t) \\leftarrow Q(S_t, A_t) + \\alpha[R_{t+1} + \\gamma\\max_a Q(S_{t+1}, a) Q(S_t, A_t)]$。"},{"id":"ai13011-pl-P5154843","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"Q学习是一种（ ）的TD控制算法。","opts":["A. Onpolicy","B. Offpolicy","C. 同轨策略","D. 在线学习"],"ans":1,"explain":"Q学习是一种Offpolicy的TD控制算法，学习的动作值函数Q不依赖于其所遵循的策略而直接近似于最优动作值函数。"},{"id":"ai13011-pl-P5154844","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"Sarsa与Qlearning的主要区别在于（ ）。","opts":["A. Sarsa是Offpolicy，Qlearning是Onpolicy","B. Sarsa是Onpolicy，Qlearning是Offpolicy","C. 两者都是Onpolicy","D. 两者都是Offpolicy"],"ans":1,"explain":"Sarsa为Onpolicy学习，Qlearning为Offpolicy学习。"},{"id":"ai13011-pl-P5154845","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在策略梯度方法中，目标函数$J(\\theta)$对策略参数的梯度估计方法被称为（ ）。","opts":["A. 策略评估定理","B. 策略梯度定理","C. 策略改进定理","D. 策略收敛定理"],"ans":1,"explain":"策略梯度定理给出了性能指标对模型参数的梯度的解答。"},{"id":"ai13011-pl-P5154846","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"基于策略的学习相比基于价值函数的学习，其主要优点之一是（ ）。","opts":["A. 总能收敛到全局最优","B. 能够学到一些随机策略","C. 不需要与环境交互","D. 计算价值函数非常简单"],"ans":1,"explain":"基于策略的学习的优点包括：具有更好的收敛性、高效处理高维连续状态空间、能够学到一些随机策略等。"},{"id":"ai13011-pl-P5154847","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"REINFORCE算法属于（ ）策略梯度方法。","opts":["A. 蒙特卡罗","B. 时序差分","C. 动态规划","D. 价值迭代"],"ans":0,"explain":"REINFORCE算法使用从当前时刻到幕结束的完全回报，是一个蒙特卡罗算法，只有在分幕式情况下才能很好地定义。"},{"id":"ai13011-pl-P5154848","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"ActorCritic方法中，Critic部分的作用是（ ）。","opts":["A. 根据观察到的状态直接选择动作","B. 参数化行为价值函数，引导Actor更新策略参数","C. 与环境进行交互","D. 随机生成动作"],"ans":1,"explain":"Critic的作用是参数化行为价值函数$Q_w(s,a)$，按照得到的价值引导策略函数参数$\\theta$的更新。"},{"id":"ai13011-pl-P5154849","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"DQN对Qlearning的修改不包括以下哪项？","opts":["A. 利用深度卷积神经网络逼近值函数","B. 利用经验回放训练学习过程","C. 设置目标网络处理TD偏差","D. 使用线性函数逼近值函数"],"ans":3,"explain":"DQN对Qlearning的修改有三个方面：利用深度卷积神经网络逼近值函数、利用经验回放、设置目标网络。DQN使用的是非线性神经网络逼近，而非线性函数逼近。"},{"id":"ai13011-pl-P5154850","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"经验回放机制的主要作用是（ ）。","opts":["A. 减少存储空间","B. 打破数据之间的关联性，使网络训练更稳定","C. 增加训练速度","D. 减少计算复杂度"],"ans":1,"explain":"经验回放利用随机采样的方法从数据库中抽取数据，打破了数据之间的关联性，使网络训练更稳定。"},{"id":"ai13011-pl-P5154851","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"DQN中设置目标网络的目的是（ ）。","opts":["A. 减少网络参数","B. 单独处理TD偏差，消除数据间的关联性，使训练更稳定","C. 增加网络层数","D. 减少训练时间"],"ans":1,"explain":"设置目标网络来单独处理时间差分算法中的TD偏差，可以消除数据间的关联性，使训练更加稳定。"},{"id":"ai13011-pl-P5154852","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"深度确定性策略梯度(DDPG)主要解决的问题是（ ）。","opts":["A. 高维状态空间的学习","B. 连续动作空间上的强化学习问题","C. 离散动作空间的探索","D. 多智能体协作问题"],"ans":1,"explain":"DQN在连续动作空间上无法针对每一个动作输出动作值函数，对这类连续动作空间的问题无能为力。DDPG采用ActorCritic方法解决了这一问题。"},{"id":"ai13011-pl-P5154853","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"DDPG采用的核心方法框架是（ ）。","opts":["A. Qlearning","B. ActorCritic","C. 策略迭代","D. 价值迭代"],"ans":1,"explain":"DDPG采用ActorCritic方法，由Actor负责输出动作，Critic负责对Actor输出的动作进行打分。"},{"id":"ai13011-pl-P5154923","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"强化学习中，$Q_{\\pi}(s,a)$表示（ ）。","opts":["A. 在状态s下遵循策略$\\pi$可以获得的期望回报","B. 从状态s开始采取动作a，并在之后遵循策略$\\pi$可以获得的期望回报","C. 在状态s下采取最优动作可以获得的期望回报","D. 从初始状态开始遵循策略$\\pi$可以获得的期望回报"],"ans":1,"explain":"$Q_{\\pi}(s,a)$定义为从状态s开始，采取动作a，并在之后遵循策略$\\pi$可以获得的期望回报。"},{"id":"ai13011-pl-P5154924","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在动态规划的策略迭代中，策略改进是通过（ ）方式实现的。","opts":["A. 随机选择动作","B. 贪婪地选择使$Q_{\\pi}(s,a)$最大的动作","C. 降低学习率","D. 增加探索概率"],"ans":1,"explain":"策略改进是在当前策略基础上，贪婪地选取行为，即$\\pi&#039;(s) \\doteq \\arg\\max_a Q_{\\pi}(s,a)$。"},{"id":"ai13011-pl-P5154925","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在SARSA算法中，如果$S_t$是终止状态，则$Q(S_t, A_t)$被定义为（ ）。","opts":["A. 0","B. 1","C. 1","D. 保持上一次的值"],"ans":0,"explain":"如果$S_t$是终止状态，那么$Q(S_t, A_t)$被定义为0。"},{"id":"ai13011-pl-P5154926","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"策略梯度方法中，ActorCritic方法的优势之一是（ ）。","opts":["A. 完全避免了方差问题","B. 可以实现单步增量式的在线学习","C. 不需要价值函数估计","D. 只能用于分幕式任务"],"ans":1,"explain":"ActorCritic是一个在线实时算法，针对每一步进行更新，不需要等到Episode结束。"},{"id":"ai13011-pl-P5154927","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"深度Q网络(DQN)中，目标网络$\\theta^{}$的作用是（ ）。","opts":["A. 减少网络参数量","B. 提供稳定的TD目标值，使训练更加稳定","C. 增加网络复杂度","D. 替代经验回放"],"ans":1,"explain":"设置目标网络来单独处理时间差分算法中的TD偏差，可以消除数据间的关联性，使训练更加稳定。"},{"id":"ai13011-pl-P5155022","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于强化学习基本概念的描述，正确的有（ ）。","opts":["A. 强化学习中智能体的目标是最大化长期累积奖励的期望值","B. 试错搜索和延迟奖励是强化学习最重要的特征","C. 强化学习不同于监督学习，它不需要带标签的数据","D. 强化学习不同于无监督学习，它试图最大化收益信号而不是寻找隐藏结构"],"ans":[0,1,2,3],"explain":"A项正确：智能体的目标就是最大化长期累积奖励。B项正确：试错搜索和延迟奖励是强化学习最重要的特征。C项正确：强化学习不同于监督学习，它不需要带标签的样本。D项正确：强化学习的目标在于最大化收益信号，而不是寻找隐藏结构。"},{"id":"ai13011-pl-P5155023","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于强化学习中回报和折扣率的描述，正确的有（ ）。","opts":["A. 折扣率$\\gamma$决定了未来奖励的当前价值","B. 当$\\gamma=0$时，智能体变得“短视”，只关心最大化立即奖励","C. 当$\\gamma$接近于1时，智能体的视野变得更长远","D. 在分幕式任务中，回报是奖励序列的和"],"ans":[0,1,2,3],"explain":"A项正确：折扣率决定了未来奖励的当前值。B项正确：当$\\gamma=0$时，智能体仅关心最大化立即奖励。C项正确：当$\\gamma$接近于1时，智能体的视野变得更长远。D项正确：在分幕式任务中，回报就是奖励的和。"},{"id":"ai13011-pl-P5155024","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于动态规划中策略迭代和价值迭代的描述，正确的有（ ）。","opts":["A. 策略迭代由策略评估和策略改进交替进行","B. 价值迭代可以看作是对策略评估进行了截断","C. 策略迭代在有限次迭代内收敛到最优策略","D. 价值迭代在中间过程中不会给出明确的策略"],"ans":[0,1,2,3],"explain":"A项正确：策略迭代由策略评估和策略改进交替进行。B项正确：价值迭代可以看作是对策略评估进行了截断。C项正确：有限MDP只有有限数量的策略，策略迭代在有限次迭代内收敛到最优策略。D项正确：价值迭代在中间过程中不会给出明确的策略。"},{"id":"ai13011-pl-P5155025","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于时序差分学习的描述，正确的有（ ）。","opts":["A. TD学习是蒙特卡罗方法和动态规划方法的结合","B. TD方法可以直接从经验中学习，无须了解环境模型","C. TD方法基于其他已知的估计更新估计，而不等待最终结果","D. TD(0)更新的目标是$R_{t+1}+\\gamma V(S_{t+1})$"],"ans":[0,1,2,3],"explain":"A项正确：TD学习是蒙特卡罗方法和动态规划方法的结合。B项正确：TD可以直接从经验中学习，无须了解环境模型。C项正确：TD方法基于其他已知的估计更新估计，而不等待最终结果。D项正确：TD(0)方法更新的目标是$R_{t+1}+\\gamma V(S_{t+1})$。"},{"id":"ai13011-pl-P5155026","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于Sarsa和Q-learning算法的描述，正确的有（ ）。","opts":["A. Sarsa是On-policy方法","B. Q-learning是Off-policy方法","C. Sarsa更新时使用五元组$(S_t,A_t,R_{t+1},S_{t+1},A_{t+1})$","D. Q-learning更新时使用$\\max_a Q(S_{t+1},a)$"],"ans":[0,1,2,3],"explain":"A项正确：Sarsa是On-policy方法。B项正确：Q-learning是Off-policy方法。C项正确：Sarsa规则使用五元组$(S_t,A_t,S_{t+1},R_{t+1},A_{t+1})$。D项正确：Q-learning更新时使用$\\gamma\\max_a Q(S_{t+1},a)$。"},{"id":"ai13011-pl-P5155027","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于策略梯度方法的描述，正确的有（ ）。","opts":["A. 基于策略的学习具有更好的收敛性","B. 基于策略的学习可以学到一些随机策略","C. REINFORCE算法是一种蒙特卡罗策略梯度方法","D. Actor-Critic方法可以实现单步增量式的在线学习"],"ans":[0,1,2,3],"explain":"A项正确：基于策略的学习具有更好的收敛性。B项正确：基于策略的学习能够学到一些随机策略。C项正确：REINFORCE是一个蒙特卡罗算法。D项正确：Actor-Critic是一个在线实时算法，针对每一步进行更新。"},{"id":"ai13011-pl-P5155028","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于深度Q-learning(DQN)的描述，正确的有（ ）。","opts":["A. DQN利用深度卷积神经网络逼近值函数","B. DQN利用经验回放训练强化学习的学习过程","C. DQN设置目标网络来单独处理TD偏差","D. 经验回放打破了数据之间的关联性"],"ans":[0,1,2,3],"explain":"A项正确：DQN利用深度卷积神经网络逼近值函数。B项正确：DQN利用经验回放训练强化学习的学习过程。C项正确：DQN设置目标网络来单独处理TD偏差。D项正确：经验回放利用随机采样打破了数据之间的关联性。"},{"id":"ai13011-pl-P5155029","type":"mc","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"以下关于深度确定性策略梯度(DDPG)的描述，正确的有（ ）。","opts":["A. DDPG采用Actor-Critic方法","B. Actor网络负责根据观察到的环境信息输出动作","C. Critic网络负责对Actor输出的动作进行打分","D. DDPG适用于连续动作空间的问题"],"ans":[0,1,2,3],"explain":"A项正确：DDPG采用Actor-Critic方法。B项正确：Actor负责根据观察到的环境信息输出动作。C项正确：Critic负责对Actor输出的动作进行打分。D项正确：DDPG解决了DQN在连续动作空间上无法处理的问题。"},{"id":"ai13011-pl-P5155076","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"简述强化学习与监督学习、无监督学习的主要区别。","opts":[],"ans":null,"explain":"教材从学习方式和目标两个维度对比了强化学习与其他学习范式。\n强化学习与监督学习的区别：监督学习依靠带标签的数据集进行集中学习，无法从交互中自动探索；而强化学习没有预先给出的正确行为标签，智能体必须在与环境的交互和试错中自行学习。强化学习与无监督学习的区别：无监督学习的核心目标是寻找未标记数据中的隐藏结构特征；而强化学习的核心目标是最大化环境反馈的累积奖励信号，发现数据的隐藏结构仅是实现该目标的潜在辅助手段。试错搜索和延迟奖励是强化学习最重要的两个特征。"},{"id":"ai13011-pl-P5155077","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"简述策略迭代与价值迭代两种动态规划算法的核心区别。","opts":[],"ans":null,"explain":"教材从算法逻辑和中间结果两个角度对比了两种动态规划方法。\n策略迭代与价值迭代的核心区别：（1）执行逻辑不同：策略迭代由“策略评估”和“策略改进”两个独立且交替的过程组成，每一次循环都需要通过多次扫描状态集将当前策略的值函数精确评估至收敛，然后再基于贪心原则改进策略；价值迭代将策略评估进行了截断，直接将策略改进与评估结合在一起，利用对动作取最大值的更新规则同时推进价值函数和策略的收敛。（2）中间结果的含义不同：策略迭代过程中维护明确的策略和对应的值函数；价值迭代在中间过程中不给出明确的策略，中间得到的价值函数也不对应任何具体策略，仅作为数值递推的中间状态。"},{"id":"ai13011-pl-P5155078","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"简述Sarsa与Q-learning两种时序差分控制算法的主要区别。","opts":[],"ans":null,"explain":"教材从策略类型、更新公式和应用场景三个维度对比了两种TD控制算法。\nSarsa与Q-learning的主要区别：（1）学习策略类型不同：Sarsa是On-policy（同策略）方法，即用于更新Q值的行为策略与要评估的目标策略是同一个策略；Q-learning是Off-policy（异策略）方法，行为策略与目标策略不同。（2）更新公式不同：Sarsa使用五元组(S_t,A_t,R_{t+1},S_{t+1},A_{t+1})，目标值为R_{t+1}+γQ(S_{t+1},A_{t+1})，其中A_{t+1}是实际将要执行的动作；Q-learning的目标值为R_{t+1}+γmax_a Q(S_{t+1},a)，使用贪心选择的动作而非实际执行的动作。（3）应用场景不同：Sarsa在训练过程中更谨慎，适合在线学习；Q-learning更激进，直接学习最优策略，适合离线学习。"},{"id":"ai13011-pl-P5155079","type":"sa","tier":"创新","conf":"adapt","chap":"第5-7章","q":"简述DQN（深度Q-learning）对传统Q-learning的三大改进及其作用。","opts":[],"ans":null,"explain":"教材系统阐述了DQN的三项核心改进及其各自的原理和作用。\nDQN对Q-learning的三大改进及其作用：（1）利用深度卷积神经网络逼近值函数：用神经网络替代Q表，解决了高维或连续状态空间无法建表的问题，实现了非线性函数逼近；（2）利用经验回放训练强化学习的学习过程：将交互数据存入经验池并随机采样，打破采样数据在时间上的关联性，满足神经网络训练独立同分布的前提，使网络训练更稳定；（3）设置目标网络来单独处理TD偏差：设置独立的目标网络θ⁻计算TD目标，切断目标值与当前参数的实时关联，即使用公式θ_{t+1}=θ_t+α[r+γmax_a Q(s&#039;,a&#039;,θ⁻)-Q(s,a,θ)]∇Q(s,a,θ)，有效消除了数据间的关联性，使训练更加稳定。"},{"id":"ai13011-pl-P5155036","type":"calc","tier":"创新","conf":"adapt","chap":"第5-7章","q":"某自动驾驶公司需要训练一个智能体来控制车辆在模拟环境中行驶。请回答以下问题：（1）为什么强化学习适合解决自动驾驶控制问题？（2）请简述Q-learning算法的基本原理和更新公式。（3）如果状态空间很大（如连续的图像输入），传统的Q-learning算法无法处理，应该采用什么方法？请说明该方法的核心改进。","opts":[],"ans":null,"explain":"本题综合考查强化学习的适用场景、Q-learning算法原理以及DQN的核心改进，要求学生理解从传统强化学习到深度强化学习的演进思路。\n（1）强化学习适合自动驾驶的原因：①自动驾驶本质上是序贯决策问题，智能体需要根据当前环境状态（传感器数据）连续做出决策（加速、刹车、转向等），这与强化学习的交互式学习框架高度契合；②强化学习通过试错搜索和延迟奖励来学习最优策略，智能体可以在模拟环境中不断尝试，从成功和失败中学习，无需人工标注每个状态下的正确动作；③强化学习能够处理长期回报最大化问题，自动驾驶不仅需要考虑当前动作的即时效果，还需要考虑对未来状态的影响（如安全行驶到目的地）。（2）Q-learning算法基本原理：学习一个动作值函数Q(s,a)，表示在状态s下采取动作a后遵循最优策略能获得的期望累计折扣回报。通过不断更新Q值，使其逼近最优动作值函数q_*。更新公式：Q(S_t,A_t) ← Q(S_t,A_t) + α[R_{t+1} + γ max_a Q(S_{t+1},a) - Q(S_t,A_t)]。其中α是学习率，γ是折扣率，R_{t+1}是即时奖励，max_a Q(S_{t+1},a)表示在下一状态选择最优动作的估计Q值。（3）应采用深度Q-learning（DQN）方法。DQN的三大核心改进：①利用深度卷积神经网络逼近值函数：用神经网络替代Q表，将连续图像输入直接映射为各动作的Q值，解决了高维状态空间无法建表的问题；②经验回放：将交互数据(S_t,A_t,R_t,S_t&#039;,end)存入经验池并随机采样进行训练，打破数据时序关联性，满足神经网络独立同分布的要求，使训练更稳定；③目标网络：设置独立的目标网络θ⁻计算TD目标值y_j = R_j + γ max_a Q(S_j&#039;,a&#039;,θ⁻)，与在线网络θ分离，切断目标值与当前参数的实时关联，显著提高训练稳定性。"},{"id":"ai13011-pl-P5155127","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"强化学习中，智能体的目标是最大化接收到的__1__总量，即最大化长期累积奖励的期望值。","opts":[],"ans":["奖励"],"explain":"智能体的目标就是最大化接收到奖励总量。\n参考答案: A.奖励"},{"id":"ai13011-pl-P5155128","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"在Q-learning算法中，学习的动作值函数$Q$不依赖于其所遵循的策略而直接近似于最优动作值函数$q_*$，因此Q-learning是一种__1__的TD控制算法。","opts":[],"ans":["Off-policy"],"explain":"Q-learning是一种Off-policy的TD控制算法。\n参考答案: A.Off-policy"},{"id":"ai13011-pl-P5154854","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"本章数据分析实例所采用的数据集是著名的（ ），也称为鸢尾花卉数据集。","opts":["A. MNIST","B. IMDB","C. iris","D. CIFAR10"],"ans":2,"explain":"本章数据分析实例所采用的数据集是著名的iris数据集，也称为鸢尾花卉数据集。"},{"id":"ai13011-pl-P5154855","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"Iris数据集中，所有记录的属性类型均为（ ），且无缺失值。","opts":["A. 整数","B. 实数","C. 字符串","D. 布尔值"],"ans":1,"explain":"Iris数据集所有记录的属性类型均为实数，且无缺失值。"},{"id":"ai13011-pl-P5154856","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在数据可视化中，“bo”代表（ ）。","opts":["A. 蓝色圆圈","B. 红色圆圈","C. 蓝色十字","D. 红色十字"],"ans":0,"explain":"颜色代码“b”代表蓝色，“o”代表圆圈，“bo”代表蓝色圆圈。"},{"id":"ai13011-pl-P5154857","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"pylab库中，“r+”代表（ ）。","opts":["A. 红色圆圈","B. 红色十字","C. 绿色十字","D. 蓝色十字"],"ans":1,"explain":"“r”代表红色，“+”代表十字，“r+”代表红色十字。"},{"id":"ai13011-pl-P5154858","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在Iris数据集的分类实验中，使用高斯朴素贝叶斯模型，将原始数据划分为训练集和测试集，比例为（ ）。","opts":["A. 5:5","B. 6:4","C. 7:3","D. 8:2"],"ans":1,"explain":"制定训练集与测试集比例为6:4。"},{"id":"ai13011-pl-P5154859","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"混淆矩阵中，正确的猜测都在表格的（ ）上。","opts":["A. 第一行","B. 第一列","C. 对角线","D. 最后一列"],"ans":2,"explain":"混淆矩阵中正确的猜测都在表格的对角线。"},{"id":"ai13011-pl-P5154860","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"线性回归模型通过计算每个数据点到拟合线的（ ）的平方和，找到平方和最小的最佳拟合线。","opts":["A. 水平距离","B. 垂直差","C. 欧几里得距离","D. 曼哈顿距离"],"ans":1,"explain":"LinearRegression模型通过计算每个数据点到拟合线的垂直差的平方和，找到平方和最小的最佳拟合线。"},{"id":"ai13011-pl-P5154861","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在Iris数据集上使用PCA降维时，$explained\\_variance\\_ratio\\_$指标代表（ ）。","opts":["A. 各主成分所丢失的信息比例","B. 各主成分所保留的方差贡献率","C. 各主成分的特征值大小","D. 各主成分的特征向量"],"ans":1,"explain":"教材通过输出示例表明，$explained\\_variance\\_ratio\\_$代表各主成分保留的信息（方差贡献率），其累加值越接近100%说明保留的原始信息越完整。"},{"id":"ai13011-pl-P5154862","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在Iris数据集上使用PCA将维度降到2维后，第一个主成分保留了（ ）的方差信息。","opts":["A. 53.0%","B. 92.46%","C. 97.76%","D. 99.48%"],"ans":1,"explain":"教材输出结果显示，PCA的$explained\\_variance\\_ratio\\_$为$[0.92461621, 0.05301557]$，第一个主成分保留约92.46%的方差信息。"},{"id":"ai13011-pl-P5154863","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"TensorFlow是Google基于（ ）进行研发的第二代人工智能学习系统。","opts":["A. Dist Belief","B. Caffe","C. Theano","D. Torch"],"ans":0,"explain":"TensorFlow是谷歌基于Dist Belief进行研发的第二代人工智能学习系统。"},{"id":"ai13011-pl-P5154864","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在Keras中，MNIST手写数字数据库包含（ ）个训练样本和（ ）个测试样本。","opts":["A. 50000；10000","B. 60000；10000","C. 70000；10000","D. 60000；20000"],"ans":1,"explain":"MNIST有60000个训练样本集和10000个测试样本集。"},{"id":"ai13011-pl-P5154865","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在MNIST手写数字识别的CNN模型中，输出层使用的激活函数是（ ）。","opts":["A. sigmoid","B. tanh","C. relu","D. softmax"],"ans":3,"explain":"教材代码中，输出层使用的激活函数是softmax，用于多分类任务。"},{"id":"ai13011-pl-P5154866","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在MNIST手写数字识别的CNN模型中，损失函数使用的是（ ）。","opts":["A. binary_crossentropy","B. categorical_crossentropy","C. mean_squared_error","D. hinge_loss"],"ans":1,"explain":"教材代码中，编译模型时loss参数为&#039;categorical_crossentropy&#039;。"},{"id":"ai13011-pl-P5154867","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"IMDB数据集中每一条数据都是一段影评，标记为正面评价或负面评价，共计（ ）条训练数据和（ ）条测试数据。","opts":["A. 15000；15000","B. 20000；10000","C. 25000；25000","D. 30000；20000"],"ans":2,"explain":"IMDB数据集共计25000条训练数据和25000条测试数据。"},{"id":"ai13011-pl-P5154868","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在LSTM单元中，第一步“遗忘阶段”中，决定从细胞状态中丢弃什么信息的结构是（ ）。","opts":["A. 输入门","B. 遗忘门","C. 输出门","D. 更新门"],"ans":1,"explain":"LSTM中的第一步决定从细胞状态中丢弃什么信息，这个决定通过一个“遗忘门”实现。"},{"id":"ai13011-pl-P5154869","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"LSTM中，输出门的作用是（ ）。","opts":["A. 决定从细胞状态中丢弃什么信息","B. 确定什么样的新信息被存放在细胞状态中","C. 更新旧细胞状态","D. 确定输出什么值，决定细胞状态的哪个部分将输出"],"ans":3,"explain":"输出阶段创建“输出门”来确定细胞状态的哪个部分将输出。"},{"id":"ai13011-pl-P5154870","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在LSTM进行IMDB文本情感分类的模型中，输出层使用的激活函数是（ ）。","opts":["A. softmax","B. sigmoid","C. tanh","D. relu"],"ans":1,"explain":"教材代码中，输出层使用的激活函数为sigmoid，用于二分类任务。"},{"id":"ai13011-pl-P5154871","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在使用Keras预处理文本数据时，`pad_sequences`函数的作用是（ ）。","opts":["A. 将文本转换为词向量","B. 将不同长度的序列填充或截断为固定长度","C. 对文本进行分词","D. 对文本进行词频统计"],"ans":1,"explain":"教材中使用了`sequence.pad_sequences(X_train, maxlen=maxlen)`，其作用是将序列填充或截断为固定长度$maxlen$。"},{"id":"ai13011-pl-P5154921","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"LSTM中，用于决定保留或丢弃细胞状态中信息的门控结构是（ ）。","opts":["A. 输入门","B. 遗忘门","C. 输出门","D. 更新门"],"ans":1,"explain":"LSTM的遗忘门通过sigmoid函数输出0到1之间的值，决定从细胞状态中丢弃多少信息。"},{"id":"ai13011-pl-P5154928","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在Iris数据集的PCA降维分析中，当主成分数量从1维增加到4维时，$explained\\_variance\\_ratio\\_$的累加值变化为（ ）。","opts":["A. 92.46% → 97.76% → 99.48% → 100%","B. 53.0% → 76.0% → 92.0% → 100%","C. 80% → 90% → 95% → 100%","D. 50% → 70% → 85% → 100%"],"ans":0,"explain":"教材输出结果显示：1维为92.46%，2维为97.76%，3维为99.48%，4维为100.0%。"},{"id":"ai13011-pl-P5154929","type":"sc","tier":"基础","conf":"adapt","chap":"第5-7章","q":"在使用LSTM进行IMDB文本情感分类时，`Embedding`层的作用是（ ）。","opts":["A. 将文本序列转换为固定长度","B. 将整数编码的单词转换为稠密的词向量表示","C. 对文本进行情感打分","D. 对文本进行分词处理"],"ans":1,"explain":"在Keras中，Embedding层用于将正整数（单词索引）转换为固定大小的稠密向量，即词嵌入，是文本处理中的标准步骤。"},{"id":"ai13011-pl-P5155037","type":"calc","tier":"创新","conf":"adapt","chap":"第5-7章","q":"某电商平台希望构建一个商品推荐系统。请回答以下问题：（1）从数据分析实例的角度，该系统的数据导入和数据探索阶段应该做哪些工作？（2）推荐系统常用的算法包括协同过滤和基于内容的推荐。请对比这两种方法的优缺点。（3）如果要将推荐结果可视化展示给运营人员，可以选择什么可视化工具？","opts":[],"ans":null,"explain":"本题综合考查数据分析流程、推荐算法对比和可视化工具选型，要求学生具备完整的项目分析能力。\n（1）数据导入和数据探索阶段的工作：①数据导入：从多个数据源导入数据，包括用户信息表、商品信息表、用户行为日志（浏览、点击、加购、购买、评价）、订单数据等，使用pandas等工具进行数据读取和合并；②数据初识：查看数据的基本信息（shape、dtypes、describe），了解数据规模、数据类型和分布特征；③缺失值检查：检查各字段缺失情况，制定缺失值处理策略；④数据可视化探索：使用直方图查看用户年龄、消费金额分布，使用散点图查看商品价格与销量的关系，使用热力图查看用户行为间的相关性；⑤异常值检测：识别并处理异常数据（如超出合理范围的购买金额、异常高频访问等）。（2）协同过滤与基于内容推荐的对比：协同过滤优点：①不需要领域知识，自动挖掘用户和物品的相似性；②可以发现用户的潜在兴趣，推荐新颖的物品；③随着数据量增加效果会更好。协同过滤缺点：①冷启动问题：新用户或新物品缺乏交互数据；②稀疏性问题：用户-物品交互矩阵通常非常稀疏；③可解释性较差。基于内容推荐优点：①无冷启动问题，新物品可根据自身特征推荐；②可解释性强，可明确说明推荐理由；③不同用户之间独立，不存在稀疏性问题。基于内容推荐缺点：①需要大量领域知识构建特征；②推荐结果多样性较差，容易推荐相似内容；③无法发现用户跨领域的潜在兴趣。（3）可视化工具选择：①若需在Web端展示，可选择ECharts（轻量级、图表类型丰富、交互性好）或D3.js（功能强大、灵活性高、适合大数据量）；②若需进行复杂网络分析（如用户-商品二部图），可选择Gephi；③若需快速原型验证，可使用Python的Matplotlib或Seaborn。对于电商推荐场景，ECharts是性价比较高的选择，其丰富的图表类型（折线图、饼图、关系图、热力图）能满足运营监控和数据分析需求。"},{"id":"ai13011-pl-P5155129","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-7章","q":"在Keras中，用于将正整数（单词索引）转换为固定大小的稠密向量表示的层是__1__层。","opts":[],"ans":["Embedding"],"explain":"在Keras中，Embedding层用于将正整数（单词索引）转换为固定大小的稠密向量。\n参考答案: A.Embedding"}];
